WordHunterWoW_QuestEN[51428] = { title = "Azerite Wounds", description = "", objectives = "" }
WordHunterWoW_QuestEN[51429] = { title = "King Clickyclack", description = "", objectives = "" }
WordHunterWoW_QuestEN[51430] = { title = "Reverse Tinkering", description = "The sentry bots here are definitely of gnomish make. If the creator had any sort of proper education, each machine should have some sort of serial code on it.\n\nAnd if they've been properly documented, I might be able to use those codes to track that gnome down.\n\nDo you think you could bring a few of them back to me?", objectives = "Gather 4 V-300 serial plates.", progress = "Did you find anything interesting?", completion = "I'll have to send these back to Ironforge and we'll see if they can find anything." }
WordHunterWoW_QuestEN[51431] = { title = "Soul Goliath", description = "", objectives = "" }
WordHunterWoW_QuestEN[51432] = { title = "An Unusual Mentor", description = "You have done well so far, {name}, but dere is still much more for you to learn. I think it is time for you to meet an old 'friend'.\n\nDere is no better person I know of to teach you about akunda's bite, as his knowledge and respect for de plant is unrivaled.\n\nHead North beyond the desert of Vol'dun. Dere you will find a tortollan who will teach you more about de desert flower.", objectives = "Find Patu in Vol'dun.", completion = "You seek knowledge on akunda's bite? Marvelous plant, but surprisingly delicate given the harsh environment. Only the strongest will survive...\n\nHmmm... Yes, you'll do nicely.  If you assist me in my work, I would be willing to provide you with some insights." }
WordHunterWoW_QuestEN[51433] = { title = "Matron Morana", description = "", objectives = "" }
WordHunterWoW_QuestEN[51434] = { title = "Stone Golem", description = "", objectives = "" }
WordHunterWoW_QuestEN[51435] = { title = "Swashbuckling in Style", description = "First ting's first, boss-mon. Ya can't parley with pirates unless ya got da appropriate clothes.\n\nI ain't big on fashion, mon, but what ya be wearin' won't work.\n\nLuckily I collected dis box of pirate clothes. No need ta ask how. Just need ta get piratey.", objectives = "Put on a pirate disguise from the chest of Pirate Garb.", progress = "Pick whateva ya want, boss-mon. Dere be so many clothes in dat chest.", completion = "Now we be talkin', boss-mon! Ya look ready ta do some privateerin'!" }
WordHunterWoW_QuestEN[51436] = { title = "Parleyin' Wit Pirates", description = "Some a dese pirates be unhappy wit' da leadership.\n\nI been hearin' dey're da last truly free pirates. Da rest be sellin' out ta some lady named Ashvane.\n\nI don' really care 'bout dat, but da captain of dese Fogsail Freebootas  is tinkin' 'bout sellin' out too.\n\nWe gonna help stop it, and in return build a foothold here.", objectives = "Follow Shadow Hunter Ty'jin and meet First Mate Owings.", progress = "<name>, nicht wahr? Ich habe vernommen, dass Ty'jin einen Champion seiner Horde schicken würde.", completion = "I don't care about your faction wars, <name>. If you are the folks that will help save my crew, you are the folks that will get my help." }
WordHunterWoW_QuestEN[51437] = { title = "Spike the Punch", description = "Step one in causing a mutiny? Make it seem like leadership is incompetent.\n\nIf the captain wants to sell our souls to the Ashvanes, we're going to need to get dirty.\n\nI hate to say it... but we've got to muck up the booze.\n\nThat'll make the crew angry at the captain before you can even blink.", objectives = "Spike 6 Kegs of Grog.", progress = "It's a dirty deed, but it's necessary.", completion = "That is not what I...\n\nYou know what? Sure. That works." }
WordHunterWoW_QuestEN[51438] = { title = "Marking Our Territory", description = "Dis could turn out ta be quite da foothold, boss-mon!\n\nI will help wit' da settlin', turnin' da place into a good base.\n\nI tink we need some spikes.\n\nLet's be makin' tings official.", objectives = "Plant the Horde Banner in Plunder Harbor.", progress = "Dis place be feelin' like home in no time.", completion = "Dis place be feelin' like home in no time." }
WordHunterWoW_QuestEN[51439] = { title = "Cannonball Collection", description = "Walkin' through da harbor gave me some ideas, boss-mon.\n\nYa see dem big guys wit' da cannonballs?\n\nCollect some a dat ammo and bring it ta me. I tink I be havin' a use for it.", objectives = "Collect 3 Fogsail Cannonballs from Fogsail Cannoneers.", progress = "Did ya get da cannonballs?", completion = "Oh da goblins gonna be lovin' dese, mon." }
WordHunterWoW_QuestEN[51440] = { title = "A Change in Direction", description = "Whispers of dissent have been spreading through the harbor, {name}.\n\nYou can hear the grumblings of pirates who do not want to give up their freedom!\n\nRumor holds that some of the other authority figures have goals that align with mine.\n\nI forged some letters in the captain's hand. Deliver them... see who bites.\n\nOr who gets in our way.", objectives = "Deliver the forged orders to Boatswain Taryn, Quartermaster Killian, and Navigator Swink.", progress = "Mutiny is about subversion. We must fly under the radar as long as we can!", completion = "I hoped that Taryn would see the truth. Ah, well. So it goes." }
WordHunterWoW_QuestEN[51441] = { title = "Thar She Blows!", description = "Our goblin engineers been workin' on modifyin' some cannons for our uses.\n\nDa cannonballs you been collectin' be perfect ammo for dem.\n\nDere are rowboats in da harbor dat be readyin' ta bring loot to Owings's enemies. Take dis cannon and sink 'em before dey can get away!", objectives = "Use the Goblin-Engineered Hand Cannon to sink 3 Fogsail Rowboats.", progress = "Sometimes ya gotta use da ammo of ya enemies against dem, mon.", completion = "Now we be havin' ourselves a mutiny!" }
WordHunterWoW_QuestEN[51442] = { title = "I'm the Captain Now", description = "Alright {name}... It's time to take the mutiny to the captain.\n\nRhenik sits in his cave, readying himself to sell our souls to the Ashvanes!\n\nDefeat him, and I will allow you to use my port as though it were your own.", objectives = "Kill Captain Rhenik.", progress = "I cannot stand by and watch Rhenik sell our freedom.", completion = "Captain Owings...\n\nIt has a certain ring to it, don't you think?" }
WordHunterWoW_QuestEN[51443] = { title = "Battle for Azeroth: Mission Statement", description = "{name}! The Warchief has summoned you to undertake a mission of the utmost secrecy.\n\nThe very future of the Horde is at stake.", objectives = "Receive your mission from Warchief Sylvanas Windrunner within Orgrimmar.", completion = "The Dark Lady has placed her trust in us. We will not fail her, <name>." }
WordHunterWoW_QuestEN[51444] = { title = "Azerite Empowerment", description = "", objectives = "" }
WordHunterWoW_QuestEN[51445] = { title = "Thros, the Blighted Lands", description = "The Blighted Lands... \n\nIf the legends are true then inside we will witness suffering and torment the likes of which we have never known. ..\n\n...but if that is what I must endure to right what I have wronged, then I will cross that threshold gladly.\n\nWill you join me, {class}?", objectives = "Find Jaina in Thros, the Blighted Lands.", progress = "I'm with you, champion.", completion = "Words cannot express the debt I owe you for helping return my daughter to me, but unfortunately the traitor Ashvane has left us no time for celebration.\n\nWe must act." }
WordHunterWoW_QuestEN[51446] = { title = "Meet Sweetflower", description = "You have seen and learned much from these islands, but Zandalar is not de only place where you can learn. I have heard of a flower dat cannot grow on dese islands.\n\nIf you want to know more about it, you will need to find someone more knowledgeable dan myself. Fortunately for you, I know of someone who may be able to help you.\n\nHer name's Xun Xun Sweetflower, and last I heard she set up shop on the outskirts of Anyport over on de human island of Drustvar.", objectives = "Find Xun Xun Sweetflower in Drustvar.", completion = "Oh, you'd like to learn about harvesting winter's kiss?  Well that's very fortunate, for both of us..." }
WordHunterWoW_QuestEN[51447] = { title = "Aromatic Pollenator", description = "While gathering the pollen, you found a dead wasp absolutely covered in pollen.  You know that this little creature is the secret to harvesting pollen easier, but the answer seems just out grasp.\n\nMaybe if you ask Jahden about it, he might have an idea.", objectives = "Bring the Dead Pollen-Covered Wasp to Jahden Fla.\n\nProvided item:", completion = "Yes, I am familiar with dese wasps. Dey are notorious for how... Actually, this gives me an idea... but you may not like it." }
WordHunterWoW_QuestEN[51448] = { title = "Learn From the Best", description = "You want to learn how these wasps are so good at harvesting pollen, but dey will defend their territory once you set foot inside it. Dis would be a problem, but I think I have a solution.\n\nTake dis potion and go to Vol'dun, to de Prickly Grove, and drink it to turn into a plant.\n\nHere's the deal: you go out and drink the potion, you'll see firsthand how the wasps do what they do. After the potion wears off, you tell me what happened.", objectives = "Drink Jahden's potion and allow wasps to harvest your pollen.", completion = "It is good dat you experience dat first hand. It sounds like dey used their wings to stir up de pollen.  With dem being so close to de flower, de pollen had no where to go but to get stuck on the wasp.\n\nHmm, next time you've got a Swarma' Sting, try placing your hand over most of the mouth of the flower and gently blowing into it.  That might replicate what the wasps were doing." }
WordHunterWoW_QuestEN[51450] = { title = "Azerite Mining", description = "", objectives = "" }
WordHunterWoW_QuestEN[51451] = { title = "Disgustingly Damp Flower", description = "Rummaging for pollen as usual, you use the harvesting technique you learned from the wasps.  However, when you pull your hand away from the flower, you find that there is no pollen to be seen.\n\nLooking inside the swirl of petals, despite it being a mature flower, you see that there is no pollen at all.  Upon closer inspection you see that the flower is filled with a viscous liquid.  Could the flower have done this?\n\nWhile unpleasant to touch, you carefully pluck the flower to show Jahden.", objectives = "Take the Disgustingly Damp Flower to Jahden Fla.\n\nProvided item:", completion = "Hmm... Dis flower does not seem to have any pollen left. I cannot say that I have heard of a plant doing that before. Dis must be the work of some other creature." }
WordHunterWoW_QuestEN[51452] = { title = "Pollen Punching", description = "It looks like some beast managed to lap up all de pollen with it's tongue. It is curious as to what creature could have done dis, I doubt it matters.\n\nYou should be able to do dis yourself without needing any sort of rare or dangerous reagents.\n\nNext time you find a siren's sting, wet your glove so the pollen will stick to it. Water, wine, blood... It should not matter.", objectives = "Collect 12 Heaping Handfuls of Damp Pollen." }
WordHunterWoW_QuestEN[51453] = { title = "Shrine of the Storm: Behold, Pure Water", description = "", objectives = "" }
WordHunterWoW_QuestEN[51454] = { title = "Once More Into Battle", description = "", objectives = "" }
WordHunterWoW_QuestEN[51455] = { title = "Shrine of the Storm: Cleansing Fonts", description = "", objectives = "" }
WordHunterWoW_QuestEN[51456] = { title = "Shrine of the Storm: Crawling Corruption", description = "", objectives = "" }
WordHunterWoW_QuestEN[51457] = { title = "Whargarble the Ill-Tempered", description = "", objectives = "" }
WordHunterWoW_QuestEN[51461] = { title = "Deathcap", description = "", objectives = "" }
WordHunterWoW_QuestEN[51462] = { title = "Paratroopers", description = "", objectives = "" }
WordHunterWoW_QuestEN[51463] = { title = "Sky Drop Rescue", description = "", objectives = "" }
WordHunterWoW_QuestEN[51464] = { title = "Here In Spirit", description = "If you are up to de challenge, I have a task dat I believe is up your alley.\n\nDe spirits of dis land are screaming out in anguish. However, dey are either unwilling or unable to talk to me in their current state.\n\nI need you to get some fresh star moss, which will help anchor and calm their spirits. Once dey are calm, we will be able to give dem de help dey need.\n\nDo dis, and I will teach you how to harvest star moss more effectively.", objectives = "Collect 10 Fresh Star Moss.", progress = "De spirits are restless. Have you managed to get de fresh star moss yet?", completion = "You have done well. I will begin the ritual as soon as I can.\n\nIn de mean time, you are owed a lesson on how to harvest star moss.\n\nThe magic of star moss is sensitive to emotions, which is why it helps ground those dat have passed on.\n\nWhen you go to harvest, clear your mind and think of those you've lost. Dat feeling of loss, reverence, and de joy dey once brought will keep de bloom from wilting." }
WordHunterWoW_QuestEN[51465] = { title = "A Load of Scrap", description = "Hey there stranger, you want the scoop on the latest invention of the century?\n\nIt's called the Shred-Master Mk1 and this baby can triple, no QUADRUPLE your production capacity as a crafter of armor, weapons or other doohickeys you adventurers wander around with.\n\nHere, take these pants and use the Shred-Master on 'em. You'll get the gist of it.", objectives = "Use the Shred-Master Mk1 on the pair of Tattered Pants.", progress = "This machine is gonna change everything.", completion = "And just like that, you're back in business. All the materials you put into makin' the item come back to you with the Shred-Master Mk1.\n\nOkay, fine! Maybe not ALL the materials, but hey, something's better than nothin', right?\n\nOh, and keep an eye out for explusom. It's what we've discovered as a magical byproduct of the scrappin' process.\n\nIt's quite potent and only shows up when we scrap really fancy stuff." }
WordHunterWoW_QuestEN[51466] = { title = "Arvon the Betrayed", description = "", objectives = "" }
WordHunterWoW_QuestEN[51467] = { title = "Hyo'gi", description = "", objectives = "" }
WordHunterWoW_QuestEN[51468] = { title = "Bonesquall", description = "", objectives = "" }
WordHunterWoW_QuestEN[51469] = { title = "Betsy", description = "", objectives = "" }
WordHunterWoW_QuestEN[51472] = { title = "Life Preserver", description = "The Thornspeakers were assisting me but they have troubles of their own.\n\nI came in search of a powerful dragon who fell in battle many centuries ago. Melting snows have revealed Vadekius's final resting place.\n\nMy Queen has tasked me with ensuring his body cannot be reanimated and enslaved. The ritual will require my full attention and my druid friends aren't fit for combat.\n\nWatch my back while I ensure my cousin's soul flies amid the branches of G'Hanir, safe from undeath.", objectives = "Protect Zallestrasza while she conducts the ritual.", progress = "Will you watch my back as I complete the ritual?", completion = "Thank you for your help." }
WordHunterWoW_QuestEN[51474] = { title = "Forged in Fire an' Flame", description = "Ye've done more than I had any right tae ask, {name}. Recovered Ironfoe from our enemy, retrieved a fragment o' the Molten Core, an' exposed the enemy within our ranks at the Firelands.\n\nIf ye'd do me the honor, would ye come with us tae Blackrock Depths one last time while we repair our most sacred anvil?", objectives = "Speak with Moira at the Stormwind Embassy to travel to Blackrock Depths and repair the Black Anvil.", progress = "Ye've been a lifesaver, <name>.", completion = "We're grateful to ye, <name>." }
WordHunterWoW_QuestEN[51475] = { title = "Brutal Escort", description = "", objectives = "" }
WordHunterWoW_QuestEN[51478] = { title = "Ghost Busting", description = "I have spoken with de spirits. Most of dem were willing to bare their souls, calling for help from de living as dey are under attack from de blood trolls evil magic.\n\nDere was one, however, who seemed more angry dan most. It was furious dat we had not acted yet, dat we allowed things to get dis bad.\n\nGo to de Spirits Be With You inn at de port north of here and put dis spirit down, and in return I will teach you everything else I know about gathering star moss.", objectives = "Put the Angry Spirit to rest.", completion = "I owe you my thanks, <name>. Now that the spirit has been been put to rest, I can get back to work.\n\nYou have shown, once again, dat I can rely on you. In exchange, I will tell you the best kept secret of star moss.\n\nDis is going to sound crazy, but engage with it. Before you pick de flowers, talk to it, sing, hum, anything. I'm not sure why, but since I started, I have noticed one or two extra flowers will bloom before my eyes!" }
WordHunterWoW_QuestEN[51479] = { title = "The Uncorrupted", description = "This world is... not what I expected.\n\nIt is time for us to meet your warchief, {name}.\n\nThere is no need to delay any further.\n\nWe can lick our wounds once we have a roof over our heads.", objectives = "Return to Ji Firepaw in Orgrimmar to hear the end of this tale.", completion = "I see you brought a new face along with you, <name>" }
WordHunterWoW_QuestEN[51480] = { title = "Enormous Anchor Pod", description = "In all the gathering you've done, you have never come across an anchor pod of this size. Whatever the reason that it has gotten so large, there is much that can be learned from it.\n\nYour mind wanders back to Jahden, and if there is anything about it in the book you picked up earlier.", objectives = "Bring the Enormous Anchor Pod to Jahden Fla.\n\nProvided item:", completion = "Hmm... Dis certainly appears larger than usual, even de book does not have anything on a giant seed pod. I have a thought..." }
WordHunterWoW_QuestEN[51481] = { title = "More Anchor Pods", description = "I need you to bring me a handful of mature anchor pods.\n\nYou see, dis seed pod is massive, but it is still just a seed pod. If we dissect it and take careful notes, we can learn about de normal, smaller seed pods and easily see how de anatomy works.\n\nI need you to bring me more of dese mature anchor pods.  If my theory is correct, den we could actually have a factual record for de future.", objectives = "Collect 9 Mature Anchor Pods from anchor weed.", progress = "I just finished with my notes from dissecting de massive seed pod. Do you have de other seed pods for comparison?", completion = "I am still unsure as to how dis thing got so big, but I am willing to believe dat it is a gift from de Loa.\n\nDat said, when I was dissecting de big pod, I noticed dat what I thought were just thick walls along de exterior of de pod were actually a separate chamber full of seeds! See? If you carefully trim and peel back de skin on de normal pod, you can harvest some extra seeds." }
WordHunterWoW_QuestEN[51482] = { title = "Seeking More Knowledge", description = "One of de most sacred plants on dis island is anchor weed. Legend says dat it was a gift from de Loa and it can do anything from regrow limbs to granting immortality.\n\nIf you are looking for facts as to what it can do or how to harvest it, you will need to go elsewhere. \n\nThe spirits tell me dat dere is a book, dat contains de information you seek. Look for it deep within the Waycrest Manor.\n\nDey ask dat in exchange for dis knowledge, you kill whatever is causing a rift in de spirit world.", objectives = "Retrieve the Treatise on Anchor Weed from within Waycrest Manor.", progress = "Have you retrieved de book?", completion = "Dis thing is in terrible condition. Did it have dis much blood on it when you found it?\n\n<Several moments pass as Jahden flips through the pages>\n\nHmm... It is hard to tell from dese pictures, but it looks like de seed pods open when the plant is disturbed.\n\nHowever, if de first cut is at de base, dat drains a reservoir of water dat is used to open and close de pods.  So, start at the bottom, working your way up, and you should get a better harvest." }
WordHunterWoW_QuestEN[51483] = { title = "Heritage o' the Dark Iron", description = "Ye've done us proud, {name}. I've heard tales o' yer bravery during yer journeys across the surface o' Azeroth.\n\nReturn tae the mountain. We've got somethin' special fer ye.", objectives = "Meet Moira Thaurissan at Shadowforge City.", completion = "The Dark Irons never had it easy in this world. But with champions like ye tae fight for 'em, our allies know the courage that burns in our hearts.\n\nEnough fancy banter! Take this armor, then let's toast yer courage with a mug o' cold brew!" }
WordHunterWoW_QuestEN[51484] = { title = "Heritage of the Mag'har", description = "You have fought countless battles across the face of Azeroth. You have shown both our allies and enemies what it means to be Mag'har!\n\nReturn to Orgrimmar that I may recognize your dedication to our people.", objectives = "Meet Overlord Geya'rah in Orgrimmar.", completion = "Though Draenor is lost to us, we will never forget our ancestral home... or those who were lost in the fight for our freedom.\n\nYour victories in Azeroth prove that our people have earned a place in the Horde. It pleases me to honor you with this symbol of our proud lineage." }
WordHunterWoW_QuestEN[51485] = { title = "For the Horde", description = "The Mag'har face a new future, {class}.\n\nDraenor has fallen. We cannot know if we will ever set eyes upon our homeland again. But this is not the time to wallow in past sorrows.\n\nDestiny is ours to decide. Orgrimmar is our home now, and we must make our mark upon this land!\n\nShow our allies in the Horde what it means to be Mag'har. Meet with the ambassador at the warchief's embassy, then go forth and claim victories across Azeroth.\n\nStrength and honor, {name}!", objectives = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", completion = "Are you the new one? I'm supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>" }
WordHunterWoW_QuestEN[51486] = { title = "Fer the Alliance", description = "The mountain will always be home, but there's a whole world o' adventure up there on the surface. Ye look like just the sort o' {class} to find it.\n\nFer a long time, the Dark Irons stood apart from the other kingdoms. The time has come tae show 'em that we fight fer Azeroth, too.\n\nThere's an ambassador in Stormwind waitin' tae speak tae ye. He can help guide ye along on yer journey.\n\nThe Alliance needs our strength, {name}. Get out there and show 'em the might o' the mountain!", objectives = "Meet Ambassador Moorgard at the Stormwind Embassy.", completion = "Ah, there you are, <name>! We've been inspecting--err--expecting you!" }
WordHunterWoW_QuestEN[51487] = { title = "Searching for Answers", description = "There's a saying Cyrus always said when I was a kid: \"The best face is a friendly one.\" It's really helped me get to know the visitors from all over the world that come through Boralus.\n\nLet's ask some of the people in charge around here and see if they know anything about the fleet. Maybe it's just a matter of asking nicely!", objectives = "Question Sister Adrianna, Brother Darrel, and Sister Cecilia for information about the missing fleet.", progress = "I figure, worst case is we make a few friends!", completion = "No luck just yet, but I think we're making progress." }
WordHunterWoW_QuestEN[51488] = { title = "Archived Knowledge", description = "It seems like this Brother Alen we keep hearing about might have some answers. \n\nAt least, I sure hope so. Everyone here seems a bit... evasive.\n\nI think I saw some archivists heading into the southern cloister. If we follow them, I bet we'll find Alen too.", objectives = "Question Brother Alen for information about the missing fleet.", progress = "This place is way bigger than it looks!", completion = "I'd rather not stick around to see if he's right." }
WordHunterWoW_QuestEN[51489] = { title = "Time to Leave", description = "I knew it! I knew the fleet wasn't just lost!\n\nWe may be a little in over our heads here. Let's leave before things get out of hand.\n\nGaleheart can take us to Stormsong Valley from here. No point in following tradition at this point, right?", objectives = "Travel on Galeheart to Stormsong Valley.", completion = "What's going on here?!" }
WordHunterWoW_QuestEN[51490] = { title = "Border Issues", description = "They've closed off the entire valley! No wonder so many people have been complaining about trading with the Brennadam market.\n\nWe have to do something about this. These people need to make a living!\n\nYou're going to have to be an honorary cadet for me here, {name}. Tell these ruffians to clear the road!", objectives = "Convince the House Stormsong militia to clear the blockade.", progress = "We have to stop this!", completion = "Good work! Now these fine people can go about their lives." }
WordHunterWoW_QuestEN[51491] = { title = "Balethorn", description = "", objectives = "" }
WordHunterWoW_QuestEN[51492] = { title = "Gunpowder Plot", description = "Granny has everyone out running errands trying to put our hamlet back in order.\n\nI don't know what to do. The rats have gotten into our stores, they're eating everything in sight.\n\nI tried prodding one of them to get it to move along, it started foaming at the mouth, then it exploded! \n\nThink I know where all the gunpowder went...\n\nIf you recover any, can you please take it back to Marie?", objectives = "Collect 100 Gunpowder from Volatile Rats.", progress = "Were you able to find any powder, dear?", completion = "Thank you so much. I wish Charles was half as studious as you." }
WordHunterWoW_QuestEN[51494] = { title = "The Blood Gate", description = "", objectives = "" }
WordHunterWoW_QuestEN[51495] = { title = "Old Rotana", description = "", objectives = "" }
WordHunterWoW_QuestEN[51496] = { title = "Loa Your Standards", description = "", objectives = "" }
WordHunterWoW_QuestEN[51497] = { title = "Hex Education", description = "", objectives = "" }
WordHunterWoW_QuestEN[51498] = { title = "Cultural Significance", description = "I have noticed dat your skill with harvesting plants has improved, but I have also noticed dat you just treat each flower and leaf as a commodity. De flora of dese islands have a rich history, with a deep cultural significance to us.\n\nGo down to the Port of Zandalar, and ask some of the men and women what a sea stalk means to them.  Learn from us, and l will make it worth your while.", objectives = "Learn the importance of sea stalks from people in the Port of Zandalar.", completion = "De sea stalk has a unique magical property dat allows de stalk to provide de flower water, even if de flower is cut off.\n\nSailors will give their loved ones a flower and keep de stalk on themselves, so if dey fall over board, de salt water kills de flower. What you hold is more dan a stick, it is a family member's life.\n\nAs for your lesson, unlike most other magic plants, de best material to harvest for magical essence is de stem, not de leaves or flower." }
WordHunterWoW_QuestEN[51500] = { title = "Kings' Rest: The Weaponmaster Walks Again", description = "", objectives = "" }
WordHunterWoW_QuestEN[51501] = { title = "Kings' Rest: Malfunction Junction", description = "", objectives = "" }
WordHunterWoW_QuestEN[51502] = { title = "Kings' Rest: Kingsguard", description = "", objectives = "" }
WordHunterWoW_QuestEN[51503] = { title = "Gathering Mementos", description = "I have a task dat I can not really trust to anyone else, and I feel you could handle it with de reverence it deserves.\n\nAn old friend came to me today, bringing a wilted sea stalk flower with her. Her husband was on a ship off the coast of Nazmir. I am unsure if de ship went down because of de naga, de Alliance, or a squall, but she said she did not want revenge.  Only closure.\n\nIf you could go get her something to remember him by, I will tell you everything I know about sea stalks.", objectives = "Search through patches of sea weed to find a memento of the lost sailor.", progress = "Have you had a chance to search de wreckage?", completion = "I can not thank you enough for dis.\n\nDeath seems to always haunt dis land, but it is somewhat lessened by de thought dat we can still hold on to de memories of those departed.\n\nAs for your lesson, de last bit of advice I can give you is simple. To help you get de most of each sea stalk, instead of cutting the stem off from de plant, carefully pull it out of de sand and tear off de roots." }
WordHunterWoW_QuestEN[51504] = { title = "Cookie Delivery", description = "Before you head out, dear, I have one more favor to ask of you.\n\nPlease take these cookies with you to Charles.\n\nWhat sort of grandmother would I be if I didn't bake some for him too!?\n\nA terrible one, that's what, and I've no wish to be accused of that!", objectives = "Deliver Box of Cookies to Charles Davenport in the Sprucewood.", progress = "Are those cookies I smell!?", completion = "Cookies, for me!? Thank you!" }
WordHunterWoW_QuestEN[51505] = { title = "Quillrat Matriarch", description = "", objectives = "" }
WordHunterWoW_QuestEN[51506] = { title = "Barbthorn Queen", description = "", objectives = "" }
WordHunterWoW_QuestEN[51507] = { title = "Gorehorn", description = "", objectives = "" }
WordHunterWoW_QuestEN[51508] = { title = "Vicemaul", description = "", objectives = "" }
WordHunterWoW_QuestEN[51512] = { title = "Bilefang Mother", description = "", objectives = "" }
WordHunterWoW_QuestEN[51513] = { title = "Zalazane Returns", description = "{name}, I have never needed your help as much as I do this day. My home be under attack.\n\nI only just heard myself. Master Gadrin be callin' for aid. Zalazane, an old enemy of da Darkspear, has returned to da Echo Isles and has brought with him an army of da dead.\n\nZalazane be a traitor who has slain many Darkspear and defiled their souls. Will you come with me to defeat him? We can take da ship dat departs da Port of Zandalar.", objectives = "Reach Master Gadrin in the Echo Isles.", completion = "You... you brought da Zandalari with you?" }
WordHunterWoW_QuestEN[51514] = { title = "Broken Bargain", description = "These mindless undead just keep coming. They be far stronger than they were the last time Zalazane walked this world.\n\nPlease, help us drive these undead back.", objectives = "Destroy 20 Mindless Trolls on Darkspear Isle.", completion = "The dead should stay dead." }
WordHunterWoW_QuestEN[51515] = { title = "Vengeance for Vol'jin", description = "If we mean to destroy Zalazane then we gonna need something that can damage that spirit.\n\nDa Glaive of Vol'jin might be what we need to do this.\n\nZalazane be hovering near where he fell so many years ago. Rokhan and Talanji have already gone to face him.\n\nGo, slay Zalazane, and then plunge da glaive into the spirit before it can escape. Let us hope de bargain Vol'jin made be powerful enough to destroy this enemy.", objectives = "Destroy Zalazane.", progress = "Zalazane has plagued the Darkspear longer than any enemy we ever faced. His destruction must happen swiftly.", completion = "Da blade... it be glowin'. It never did dat before." }
WordHunterWoW_QuestEN[51516] = { title = "Atal'Dazar: Ashes of a Warchief", description = "I have learned much of de Darkspear lately. Truth is, I have quietly admired dem since I was a little girl, hearin' of Vol'jin's defiance of Zul's reckless call to action.\n\nVol'jin was Warchief of the Horde, chieftain of de Darkspear, and more troll den most can claim to be.\n\nHis ashes should be honored in a place of kings and queens.\n\nTake de ashes to Atal'Dazar with my blessing and honor your former Warchief as he deserves.", objectives = "Bring Vol'jin's ashes to Atal'Dazar.", progress = "What you doin' my friend?", completion = "You and I need be talkin'." }
WordHunterWoW_QuestEN[51517] = { title = "You Owe Me a Spirit", description = "Ya not leaving that here.\n\nOl' Vol'jin not be dancin' in my house. I not be seein' his spirit for a long time.\n\nIts absence has broken de bonds dat held Zalazane in my control.\n\nSo... I want you to lift dat heavy urn, and bring it to my necropolis.\n\nVol'jin and I gonna have a face to face on my ground.", objectives = "Bring the Urn of Vol'jin to Bwonsamdi in Nazmir.\n\nProvided item:", completion = "I have waited some time for dis. Long overdue hee hee... wait a moment." }
WordHunterWoW_QuestEN[51518] = { title = "The Lost Spirit", description = "It high time you an' I had a talk about ol' Vol'jin's missin' spirit. \n\nDis goes beyond simple bargains and rights of passage. Spirits don' just go missin'.\n\nYou gotta few friends dat are gonna help ya track Vol'jin's spirit down. Dem who was friends to him in life should have da strength to find him in death. And if not, Talanji gonna help ya.  \n\nGo to Talanji's ship in da Port of Zandalar. It be dat banged up ship ya came in on. You gonna do a little seance.", objectives = "Speak with Princess Talanji in the Port of Zandalar.", completion = "I am here because Master Gadrin and Rokhan asked for my aid and it is my gratitude for their deeds and yours that makes me willing to do this.\n\nNOT because Bwonsamdi insisted.\n\nIf he can't keep track of his own spirits that is a \"him\" problem, not a \"me\" problem." }
WordHunterWoW_QuestEN[51519] = { title = "Spirit Call", description = "We gonna be reachin' far into de Shadowlands for this. If Vol'jin has gone beyond Bwonsamdi's vision than either he be lost somewhere or hiding.\n\nEither way, I am hoping the bond he shares with de gathered Darkspear here can help bring him to us.\n\nStay close and don't interrupt de ritual once it has begun.", objectives = "Observe Talanji's ritual.", completion = "'Ello mon." }
WordHunterWoW_QuestEN[51520] = { title = "Justice for the Fallen", description = "Justice for da sons and daughters of lost loa. Justice for da heart of Zandalar. G'huun must be slain, and a symbol of his death displayed to those who need see it most.\n\nTake me glaive, drive it into da corpse of dat beast, and let Talanji show it to her people.\n\nLet peace be started in da hearts of da Zandalari.", objectives = "Bloody the Glaive of Vol'jin in G'huun's corpse.", progress = "Madness and darkness be movin' on da other side. Da pain of so many be mighty.", completion = "Dis been a foe that threatened da trolls for many generations. We may not have always known his name, but we felt his curse.\n\nToday, you won da justice for thousands of generations of trolls." }
WordHunterWoW_QuestEN[51521] = { title = "The True Leader of Zandalar", description = "Now, take me glaive and walk with Talanji. Let her present your victory to her people. Let da trolls know justice, and the strength of a leader.", objectives = "Present the Glaive of Vol'jin with Talanji to the people of Zandalar.", completion = "Talanji is da true ruler of Zandalar, even if she be doubting it. With guidance, she will eclipse her father's reign.\n\nFor now, ya have me thanks." }
WordHunterWoW_QuestEN[51526] = { title = "The Warlord's Call", description = "Warfang Hold is our best position on Kul Tiras. We can not allow it to fall!\n\nThe Warchief has placed High Warlord Cromush in charge of our reinforcement efforts, you are ordered to report to him as soon as possible.", objectives = "Report to High Warlord Cromush in Zuldazar.", completion = "Hurry up and get yourself squared away, <name>. We've got a battle to get to." }
WordHunterWoW_QuestEN[51527] = { title = "Executioner Blackwell", description = "", objectives = "" }
WordHunterWoW_QuestEN[51528] = { title = "Captain Leadfist", description = "", objectives = "" }
WordHunterWoW_QuestEN[51529] = { title = "Talon", description = "", objectives = "" }
WordHunterWoW_QuestEN[51530] = { title = "Wedding Crashers", description = "", objectives = "" }
WordHunterWoW_QuestEN[51532] = { title = "Storming In", description = "Front and center, {name}!\n\nAs of last night, we received word that Rexxar's force at Warfang Hold in Stormsong was surrounded by a Kul Tiran army and an attack is imminent.\n\nAs soon as you have your things packed, go speak with Dread-Admiral Tattersail and we'll get underway. There's no time to waste!", objectives = "Speak with Dread-Admiral Tattersail.", completion = "I don't know what foul sorcery those Kul Tirans used upon our ships, but right now our men are being pushed to the shore with nowhere to evacuate!\n\nNo time to puzzle things over, we have to act now!" }
WordHunterWoW_QuestEN[51533] = { title = "The Glaive of Vol'jin", description = "When fighting someone who has escaped the grasp of Bwonsamdi, as Zalazane has, it is best to bring weapons that can hurt him.\n\nIn Darkspear Hold you will find the Glaive of Vol'jin.\n\nIt should have enough bond with Vol'jin's spirit to aid us in this fight.", objectives = "Obtain the Glaive of Vol'jin.", progress = "Did you find the glaive?", completion = "The bond between Vol'jin and Zalazane was one of magic and bargains with loa.\n\nThe bond between Vol'jin and dis weapon was also great. Dis may be what we need to finally destroy that spirit." }
WordHunterWoW_QuestEN[51534] = { title = "The Battle for Brennadam", description = "", objectives = "Collect 1 Salvaged Bullets." }
WordHunterWoW_QuestEN[51535] = { title = "A Veteran's Summons", description = "{name}, we received word from Orgrimmar. Eitrigg has requested a meeting. Says it's important. He left a letter for you.\n\nI wouldn't keep him waiting or he might expire of old age before you find out what he wants.", objectives = "Meet Eitrigg at the Orgrimmar Embassy.<name>, we received word from Orgrimmar. Eitrigg has requested a meeting. Says it's important. He left a letter for you.\n\nI wouldn't keep him waiting or he might expire of old age before you find out what he wants.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[51536] = { title = "On the Hunt", description = "Looks like the magic the Kul Tirans used on our ships is beginning to dissipate, but I'm sure what happened to our ships here is only just the beginning.\n\nGet to the shore. We need to contact the survivors and find out just what we're up against.", objectives = "Search Seawatch Point for survivors.", completion = "Thank you, friend.\n\nThese humans have made a grave error today." }
WordHunterWoW_QuestEN[51538] = { title = "Word from the Deep", description = "A dark soul has infiltrated the Zanchuli Council, seeking an accord with Queen Azshara.\n\nSome followed, through greed or fear. Others were too trusting and believed his lies.\n\nWe fall, one by one. They will soon clear the path of resistance.\n\nAzshara's motives are hidden behind a vast darkness. She reaches into a place from where she cannot return.\n\nI would pity her, but she killed my followers...\n\nWhen the time comes, I will rip her apart.", objectives = "Share Gral's warning with the Seekers.", completion = "It seems the naga have moved up in threat level from \"mere nuisance\". These are dark days indeed." }
WordHunterWoW_QuestEN[51539] = { title = "Inform the Horde!", description = "This was all perpetrated by someone on the Zanchuli Council. \n\nThey sacrificed their own people, Gral's followers, for Azshara. That is unconscionable!\n\nThey weaken the foundation, so the kingdom will fall.\n\nOne of your people must have direct access to the king. Anyone else could be the traitor.", objectives = "Warn Baine of the betrayal.", completion = "It was wise of you to bring this to me, <name>." }
WordHunterWoW_QuestEN[51540] = { title = "Explosive Situation", description = "<This crate has fallen into the water. It contains bombs built to take out large mechanical devices.>\n\n<If we had more of them, we could destroy the Venture Company's Reef Breaker.>", objectives = "Collect 5 Bot Buster Bombs.", progress = "You'll need more of these bombs if we want to destroy the Reef Breaker.", completion = "Many battles are won by those who take the initiative and exploit an opportunity. You have spotted an excellent opportunity.  \n\nNow you should exploit it!" }
WordHunterWoW_QuestEN[51541] = { title = "Arclight", description = "", objectives = "" }
WordHunterWoW_QuestEN[51542] = { title = "Avalanche", description = "", objectives = "" }
WordHunterWoW_QuestEN[51543] = { title = "Saplings in the Snow", description = "Be wary mainlander, dangers lurk nearby. \n\nOne such creature, Greenstalker, used to be an ally. In his corrupted, mindless rage he nearly killed my brother and I while we were trying to help someone in the wilds. There is something which might help but I must tend to my brother's wounds and cannot obtain the remaining item on my own.\n\nPlease go onto the mountainside and pull some saplings out of the earth for me. The plants here are healthy and their roots run deep so they won't come easily.", objectives = "Collect 6 Mountain Saplings.", progress = "Did you find the mountain saplings I need?", completion = "Thank you for returning quickly. These are new growth, full of potent life-giving energy and a necessary sacrifice to cleanse corruption.\n\nGive me a moment as I create the charm." }
WordHunterWoW_QuestEN[51544] = { title = "Disarming the Cannons", description = "With your arrival, our salvation may have arrived. Your rowboats will serve as a way for us to evacuate the most critically injured.\n\nUnfortunately, the Horde have brought in a ship, and there's no way we can get our boats past their blockade.\n\nWhile the rest of us load our injured on the boats, we need you to infiltrate their ship and disable those cannons.", objectives = "Disable the cannons on the Horde ship.", completion = "Now we can get our wounded to safety." }
WordHunterWoW_QuestEN[51545] = { title = "Breaker Bad", description = "The combined fire power of all the bombs you have collected should be able to destroy the Venture Companies Reef Breaker.\n\nIt's time to act and protect the reef and this sacred cave.", objectives = "Destroy the Reef Breaker.", completion = "You have done us a great service." }
WordHunterWoW_QuestEN[51546] = { title = "It's the Pits", description = "", objectives = "" }
WordHunterWoW_QuestEN[51547] = { title = "WANTED: Rindlewoe", description = "A monstrous beast of wood and flesh has been terrorizing the nearby river territories.\n\nIf any adventurers are brave enough to vanquish this beast, the town of Fallhaven would gratefully proffer a reward.\n\nPlease report to Mayor White if you wish to help.", objectives = "Defeat Rindlewoe outside of Fallhaven.", progress = "Yes?", completion = "The beast has been slain? You have my thanks, <class>.\n\nHere is your reward, as promised." }
WordHunterWoW_QuestEN[51548] = { title = "Nagative Feedback", description = "", objectives = "" }
WordHunterWoW_QuestEN[51550] = { title = "Bubbles and Trouble", description = "", objectives = "" }
WordHunterWoW_QuestEN[51552] = { title = "The Days Are Just Packed", description = "Hello there! Would you mind checking on someone for me?\n\nSergeant Calvin was supposed to meet me here. We were going to go out looking for new alchemical reagents, but he hasn't shown up yet.\n\nI know the militia has been really busy lately so I guess he's busy, but he should still be in Brennadam Square. Would you mind checking in on him?", objectives = "Find Sergeant Calvin in Brennadam Square.", completion = "This can't be happening..." }
WordHunterWoW_QuestEN[51554] = { title = "Reloading", description = "Daryl's making every shot count, but there's just too many Horde. We're going to need more ammo soon!\n\nI need you to take this note to my uncle Leo at Deadwash, he'll be able to help.", objectives = "Deliver the note to Leo Shealds.", completion = "Lea Martin?  She's a tough one!  I'll try to help her, but we gotta save our people first." }
WordHunterWoW_QuestEN[51555] = { title = "Keep Them On Task", description = "Princess Talanji's actions have thrown off our pursuers. Her loa is powerful indeed.\n\nWe need to be certain if there were survivors, they do not gain a foothold on Zandalar. I am concerned that our Forsaken compatriots might get... overzealous. Please keep an eye on them, and remind them of what is honorable.", objectives = "Speak with Dennis Grimtale at Talanji's Rebuke.", completion = "You've been sent to check up on me?" }
WordHunterWoW_QuestEN[51556] = { title = "Myself Again", description = "I joined the tidesages because I wanted to show my brother I wasn't a weakling.  \n\nI loved the magic and power, but I started to do unspeakable things. I even tried to hurt my own family.\n\nPlease get word to my brother at Dire Hills Lodge. Tell him I have come to my senses. I am myself again.", objectives = "Speak to Patrick Eckhart at Dire Hills Lodge.", completion = "It's just like Julian to realize his mistakes long after he's done harm to others.  I hope he finds his way, but right now I have people here to worry about." }
WordHunterWoW_QuestEN[51557] = { title = "Irontide Warning", description = "Horde's taking this town! I'm not gonna stick around to watch!\n\nYou could help me out though. Go see Leo Shealds in Deadwash.  \n\nTell him, Irontide is still coming and we're taking the gold!", objectives = "Speak to Leo Shealds at Deadwash.Horde's taking this town! I'm not gonna stick around to watch!\n\nYou could help me out though. Go see Leo Shealds in Deadwash. \n\nTell him, Irontide is still coming and we're taking the gold!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[51558] = { title = "Spider Scorching", description = "", objectives = "" }
WordHunterWoW_QuestEN[51559] = { title = "Damaged Goods", description = "", objectives = "" }
WordHunterWoW_QuestEN[51561] = { title = "Spider Scorching", description = "", objectives = "" }
WordHunterWoW_QuestEN[51562] = { title = "Damaged Goods", description = "", objectives = "" }
WordHunterWoW_QuestEN[51564] = { title = "Fertilizer Duty", description = "", objectives = "" }
WordHunterWoW_QuestEN[51565] = { title = "Feeding Frenzy", description = "", objectives = "" }
WordHunterWoW_QuestEN[51566] = { title = "Resurgence of the Beast", description = "", objectives = "" }
WordHunterWoW_QuestEN[51567] = { title = "Island Expeditions", description = "Welcome to the World of Warcraft: Battle for Azeroth PAX demo!\n\nThe table in front of you can be used to queue for Island Expeditons.\n\nGrab two friends and prepare for adventure!\n\nWe hope you enjoy your time in Azeroth today!", objectives = "" }
WordHunterWoW_QuestEN[51568] = { title = "Ritualistic Preparations", description = "Hey! I just got a request for a shipment of storm silver. Wanna help? \n\nAs you know, storm silver is lightweight and resists corrosion. What you may not know is that we use it throughout our ships. It's so light our marines and pirates use it for armor because they can swim in it!\n\nHowever, any parts that go onto a ship have to be blessed by a tidesage, or it'll be cursed to a watery doom!\n\nHarvest a bucketful of ore, smelt it, and get it blessed for me, and I will teach you how to mine it easier.", objectives = "Mine Unsanctified Storm Silver Ore, use a forge to smelt Unsanctified Storm Silver Ingots, then get them blessed by a tidesage.", progress = "Did you get the storm silver? Don't forget that it needs to be blessed.", completion = "Good work! These look great!\n\nThese bars will be used as part of our next warship.\n\nNow then, you scratched my back, and I will scratch yours. Storm silver is very brittle naturally. When you mine it, use several small swings instead of one big one. That'll keep the metal from being chipped away." }
WordHunterWoW_QuestEN[51569] = { title = "The Zandalar Campaign", description = "It is time that we begin to think of our enemy, {name}. The Horde spreads its influence throughout Zandalar unchecked.\n\nKing Anduin has charged us with establishing footholds in the areas of Zuldazar, Nazmir, and Vol'dun.\n\nI have taken the liberty of deploying some of our forces in key locations, but each will need a firm hand--your hand--to direct our efforts.\n\nWhich location shall we secure first?", objectives = "Use the Zandalar Campaign Map to choose a foothold.", completion = "A fine choice, <name>." }
WordHunterWoW_QuestEN[51570] = { title = "Foothold: Zuldazar", description = "Zuldazar is the seat o' power fer the Zandalar empire.\n\nI've deployed some o' me mole machines in a place called Xibala. There's a nearby Azerite deposit that'll be o' great interest to the King. My lads say they're under attack.\n\n                 - Moira Thaurissan", objectives = "Assist Kelsey Steelspark in Zuldazar.", completion = "You have chosen to sail to Zuldazar." }
WordHunterWoW_QuestEN[51571] = { title = "Foothold: Nazmir", description = "The swamp of Nazmir is home to the notorious blood trolls.\n\nCaptain Conrad has been dispatched to determine how we can use their hatred toward the Zandalari to our advantage. Reports from the jungle have proven disconcerting at best.\n\n                     - Mathias Shaw", objectives = "Assist Brann Bronzebeard in Nazmir.", completion = "You have chosen to sail to Nazmir." }
WordHunterWoW_QuestEN[51572] = { title = "Foothold: Vol'dun", description = "The desert of Vol'dun has a promising harbor for our fleet.\n\nAn indigenous snake people known as the sethrak occupy the area. They are aggressive and cannot be negotiated with. We have little choice but to eliminate them.\n\n                    - Magister Umbric", objectives = "Assist Alliance forces in Vol'dun.The desert of Vol'dun has a promising harbor for our fleet.\n\nAn indigenous snake people known as the sethrak occupy the area. They are aggressive and cannot be negotiated with. We have little choice but to eliminate them.\n\n                    - Magister Umbric" }
WordHunterWoW_QuestEN[51573] = { title = "I've Got Your Back", description = "It's good to see a new face around here. I've got a problem and you look like you can handle a fight.\n\nDat group of murderous thugs over dere are looking for trouble and I need someone to back me up.\n\nDe truth is dat I used to be one of dem myself, but I left for a second chance at an honest life.\n\nI need to convince Mojambo and his henchmons to leave before dey start causing trouble for de rest of de outcasts here.", objectives = "Guard Razgaji while he meets with Mojambo.", progress = "Mojambo isn't going to back down easily.", completion = "Mojambo will come back with all his minions. And when he does... dere will be blood." }
WordHunterWoW_QuestEN[51574] = { title = "Freshly Squeezed", description = "Is this troll a friend of yours? I'm so glad Kiro let me keep her. \n\nHe's a bit wary of outsiders, but he's a great healer. \n\nShe'll wake up, I promise. And when she does, she'll be thirsty.\n\nThe sands are short on water, but you're in luck. The grove that surrounds this camp is filled with pricklevines. \n\nYou wouldn't want to eat the flesh, but the liquid inside can quench any thirst.\n\nJust give them a good squeeze to collect their juice.", objectives = "Collect 8 Pricklevine Juice.", progress = "Do you have the juice? Your friend will be thirsty when she wakes.", completion = "That's a lot of juice!" }
WordHunterWoW_QuestEN[51575] = { title = "Lost But Not Forgotten", description = "Hey, {name}, would you be interested in getting back a personal possession?\n\nDere is a raptor in Xibala dat took an ancient and valuable artifact from my people. My attempts to negotiate with de beast have not gone well, resulting mostly in mutual screaming and biting.\n\nFind de raptor Bonescreamer, kill it, and bring me de lost artifact.\n\nIn return, I will show you how to skin dese beasts of de land more effectively.", objectives = "Kill Bonescreamer and bring the 'Ancient Artifact' to Rana the Cutta.", progress = "Have you slain de beast yet?\n\n<Rana chuckles as she smiles slyly.>", completion = "Ah ha! Would you look at dat! I thought I would never see you again!\n\n<Rana snuggles the small stuffed raptor happily.>\n\nWhat is with dat face? I told the truth.\n\nI lost it when I was a child, so that is practically a lifetime ago, it has tremendous sentimental value to me, and I am one of my people.\n\nBut, you did do as I had asked, so I will teach you a little something.\n\n<Rana joyfully explains some of the more elusive techniques to harvesting leather.>" }
WordHunterWoW_QuestEN[51576] = { title = "Any Witch Way but Dead", description = "", objectives = "" }
WordHunterWoW_QuestEN[51577] = { title = "Defending the Academy", description = "", objectives = "" }
WordHunterWoW_QuestEN[51578] = { title = "The Sea Runs Red", description = "", objectives = "" }
WordHunterWoW_QuestEN[51579] = { title = "Dark Ranger Clea", description = "", objectives = "" }
WordHunterWoW_QuestEN[51580] = { title = "Rear Admiral Hainsworth", description = "", objectives = "" }
WordHunterWoW_QuestEN[51581] = { title = "Azerite Mining", description = "", objectives = "" }
WordHunterWoW_QuestEN[51582] = { title = "Make it Mildenhall", description = "You've no doubt enjoyed a mug or three of world-famous Mildenhall Mead in your local tavern. Today is your day to become a part of the official meadery of Stormsong Valley!\n\nIdeal applicants have a hunger for craft mead, honey, and boundless innovation. Military experience recommended, but not required.\n\nMust not be allergic to bees.\n\nMildenhall Mead - Make it Mildenhall.", objectives = "Speak with Ancel Mildenhall at the Mildenhall Meadery.", completion = "<Ancel is nearly hysterical.>" }
WordHunterWoW_QuestEN[51583] = { title = "Azerite Wounds", description = "", objectives = "" }
WordHunterWoW_QuestEN[51584] = { title = "Azerite Madness", description = "", objectives = "" }
WordHunterWoW_QuestEN[51585] = { title = "Quit Your Witchin'", description = "", objectives = "" }
WordHunterWoW_QuestEN[51586] = { title = "Azerite Empowerment", description = "", objectives = "" }
WordHunterWoW_QuestEN[51587] = { title = "Onward!", description = "I'm glad you came, {name}. With your help, we will show these Kul Tiran dogs what happens when you face a cornered beast!\n\nWarfang Hold is just up the path from here. Come, I'll fill you in on the details.", objectives = "Accompany Rexxar.", completion = "I thought I was going to meet the Earthmother along with the rest of my men." }
WordHunterWoW_QuestEN[51588] = { title = "Familiar Foes", description = "", objectives = "" }
WordHunterWoW_QuestEN[51589] = { title = "Breaking Kul Tiran Will", description = "Our partnership with the Zandalari will soon be secured. Took a little longer than I expected... but such is the way of things.\n\nUnfortunately, the Alliance seems intent on securing a naval force of their own. That can't be allowed to happen.\n\nWe set sail for Tiragarde Sound when you're ready.", objectives = "Sail to Tiragarde Sound.", completion = "We're here. Now, to cause a bit of trouble for the locals.\n\n<Nathanos looks at you, then at the rest of the group.>\n\nWe don't look too conspicuous, do we?" }
WordHunterWoW_QuestEN[51590] = { title = "Into the Heart of Tiragarde", description = "Step one is to establish a more suitable base of operations. A pirate's den will do in a pinch, but I believe the warchief expects better of us.\n\nLet's split up and push farther inland, to the west. Be on the lookout for something defensible and inconspicuous.", objectives = "Rendezvous with Nathanos and Lilian in central Tiragarde Sound.", completion = "<Nathanos peers around the corner at the Kul Tiran roughneck camp.>\n\nThis will do. Not only is it well-hidden in the forest, but the locals seem to be rather dull and easily outwitted." }
WordHunterWoW_QuestEN[51591] = { title = "Our Mountain Now", description = "{name}, go take care of those \"roughnecks.\" They might fashion themselves as tough, but a bit of your unique brand of Horde savagery should have them running in no time.\n\nLilian, scout the area. We need to know about any nearby threats.\n\nRangers, secure the perimeter. We'll reconvene in the roughneck camp once {name}'s work is done.", objectives = "Slay 10 Roughnecks in Timberfell Outpost.", progress = "Me? I'll go where I'm needed.", completion = "<Nathanos looks around the camp and nods to himself.>\n\nThis will do." }
WordHunterWoW_QuestEN[51592] = { title = "Making Ourselves at Home", description = "Log cabins will do in a pinch, but... if we're going to be spending any time here, we might as well make ourselves comfortable.\n\nThe roughnecks left us no shortage of lumber and food supplies, but we'll need canvas and chains to set up some proper Forsaken tents and banners. Bridgeport sounds rather lootable, doesn't it?", objectives = "Obtain 7 Lengths of Chain and 7 bolts of Sail Canvas from the outskirts of Bridgeport.", progress = "With a name like Bridgeport, I have to assume that the town has plenty of supplies in transit, ready for looting.", completion = "I'll have the rangers start working with these right away." }
WordHunterWoW_QuestEN[51593] = { title = "Bridgeport Investigation", description = "While you're in Bridgeport, you might keep an ear out for any information that will be of aid to us.\n\nYou'd be surprised what you can learn by staying quiet and listening to people who think they're alone...", objectives = "Spy on the denizens of Bridgeport.", completion = "Explosives in the Ashvane Foundry? Clearly we can put that information to use. Well done.\n\nIt sounds like that Captain Stone is somewhat of a big-shot as well. It would be a shame if something were to happen to her..." }
WordHunterWoW_QuestEN[51594] = { title = "Explosives in the Foundry", description = "I'm most interested in those explosives, though.\n\nMeet me in the foundry, east of here. You probably passed through it on your way from Plunder Harbor.", objectives = "Meet Lilian Voss at the Ashvane Foundry.", completion = "<Lilian gestures toward a pile of crates nearby.>\n\nThink those are filled with the explosives?" }
WordHunterWoW_QuestEN[51595] = { title = "Explosivity", description = "I don't want to waste your time. Let's make absolutely sure that these are what we're looking for.\n\nHere, take this torch and toss it over onto those crates. If they explode, then we'll know what to do next.", objectives = "Use Lilian's Torch on the Pile of Ashvane Crates near the Ashvane Foundry.", progress = "Well?", completion = "I... ah... I guess we've found our gunpowder then." }
WordHunterWoW_QuestEN[51596] = { title = "Ammunition Acquisition", description = "First: we get as much of that gunpowder as we possibly can. Imagine the terror in the Kul Tirans' eyes when they realize the Horde has turned their own weapons against them.\n\nImagine it, {name}.\n\n<Lilian's eyes briefly glaze over, and the corner of her lips turns upward in a half-smile.>", objectives = "Obtain 8 crates of Ashvane Explosives.", progress = "I've managed to round up a few crates myself. How did you do?", completion = "Excellent." }
WordHunterWoW_QuestEN[51597] = { title = "Gunpowder Research", description = "I suppose that, before we steal all the Kul Tirans' violently explosive gunpowder and use it against them, we should learn how they make the stuff.", objectives = "Obtain the Ashvane Explosives Formula and the Gunpowder Manufacturing Guide.", progress = "Let's see the paperwork.", completion = "<Lilian quickly looks over the documents and nods.>\n\nI suppose that someone in the Horde will find this information useful.\n\nProbably goblins." }
WordHunterWoW_QuestEN[51598] = { title = "A Bit of Chaos", description = "This place seems fairly well-defended for a manufacturing facility, doesn't it?\n\n<Lilian shrugs.>\n\nI suppose we'll have to kill them, then.", objectives = "Slay 15 workers at the Ashvane Foundry.", completion = "<Lilian bounces her blade in her hands, looks up, and nods approvingly at you.>" }
WordHunterWoW_QuestEN[51599] = { title = "Death Trap", description = "We started this mission with a goal, but not much of a plan. I think I can see the pieces coming together, though.\n\n<Lilian surveys the horizon, thinking.>\n\nPlace these explosives over on the southwest edge of town. Somewhere inconspicuous.\n\nWe'll meet again over there. In the meantime... I need to find a horse.", objectives = "Place 8 Gunpowder Crates in a hidden location southwest of Bridgeport.", completion = "Lucky for us, horses are in no short supply around here.\n\nYou placed the gunpowder?" }
WordHunterWoW_QuestEN[51601] = { title = "The Bridgeport Ride", description = "Pay attention, {name}, because this isn't going to be our standard assassination mission.\n\nYou and I are going to take this horse through Bridgeport and... cause a scene. I want every single guard on our tail, along with that Captain Stone character. Once we've rounded them up, it's over to those explosives, and...\n\n<Lilian's eyes grow wide with delight.>\n\nBoom.", objectives = "Mount the Stolen Horse, then use it to round up 10 Bridgeport Guards and Captain Stone. Then escort them to the southwest corner of town.\n\nGetting knocked off of your horse could prove fatal, and will fail the mission.", completion = "I heard the blast from up here. I think I may have even gotten a piece of guard on my cloak." }
WordHunterWoW_QuestEN[51602] = { title = "Bandit Blades", description = "We only have enough weapons to arm half of de tribe against Mojambo's gang.\n\nWe're going to need more weapons if we are going to survive de approaching battle.\n\nTongo's crew is sure to have a ready supply of weapons at their hideout.\n\nSearch de hideout for any weapons you can find and bring dem back to de arena.", objectives = "Retrieve 8 Sandworn Blades.", progress = "Do you have de weapons?", completion = "Dese ancient blades may not be in de best condition, but dey are finely forged. I am sure dey will hold up in battle just fine." }
