WordHunterWoW_QuestEN[51663] = { title = "Preparing for the Fall", description = "<A large quantity of supplies are scattered throughout the temple grounds, much of it under heavy guard. The Jambani appear to be preparing for a siege or another significant event.\n\nZul would likely think it wise to stymie their efforts.>", objectives = "Destroy 8 Jambani stockpiles.", completion = "Good. I did not need to tell you to do dis thing.\n\nDe Jambani prepare for de fall of Zuldazar as foretold by Vol'jamba. Dis will not happen, but destroying their stockpiles will make dem easier to eradicate once Rastakhan decides to deal with dis situation." }
