WordHunterWoW_QuestEN[51667] = { title = "This Bird You Cannot Change", description = "", objectives = "" }
WordHunterWoW_QuestEN[51668] = { title = "Mojambo", description = "Mojambo and his gang are attacking!\n\nWe must defend de arena. Mojambo must be defeated! De outcasts will take care of his gang. Mojambo is all yours...\n\nBring Tongo's head with you and use it to challenge Mojambo to a duel. His pride is too great to resist such a challenge!", objectives = "Slay Mojambo.", progress = "Mojambo must be defeated!", completion = "At last dis war be over and we can live in peace. I do not know how to thank you for all you've done." }
WordHunterWoW_QuestEN[51669] = { title = "Black-Eyed Bart", description = "", objectives = "" }
WordHunterWoW_QuestEN[51670] = { title = "Lumbergrasp Sentinel", description = "", objectives = "" }
