WordHunterWoW_QuestEN[51672] = { title = "Tangled Webs", description = "", objectives = "" }
WordHunterWoW_QuestEN[51674] = { title = "Douse the Flames", description = "Do you smell it, {name}? Smoke! They're burning down Warfang Hold!\n\nThere is little point to our battle if our base burns to the ground!\n\nTheir tidesages use wands to control their constructs of water. In our hands they may give us a chance to save the Hold! \n\nGet those wands and put out the fires before the camp burns to ash!", objectives = "Obtain a Fading Umbral Wand and use it to put out 4 flames around Warfang Hold.", progress = "We're fortunate that the Kul Tirans have a greater affinity for water than they do for fire.", completion = "Fire, blood, war. Nothing will stop us." }
WordHunterWoW_QuestEN[51675] = { title = "Hunt Them Down", description = "These Kul Tirans, they don't seem normal. Humans can be a cruel bunch from what I've heard, but these ones seem to take pleasure in slaying the fallen. \n\nThe worst of them was a woman wearing a peculiar mask. She seemed to be shouting orders to the others, so I guess she's their leader.\n\nHonor the fallen and ensure they and their leader don't survive.", objectives = "Slay Captain Ara and 8 Storm's Wake Footmen.", completion = "You've done us a great service, <name>." }
WordHunterWoW_QuestEN[51676] = { title = "What a Gull Wants", description = "", objectives = "" }
WordHunterWoW_QuestEN[51677] = { title = "Mending Body and Soul", description = "Good. You have brought me the last ingredients I will need to concoct a solution to close the king's wounds.\n\nYou are not a moment too soon. He is fading.\n\nI am not comfortable working at an elevated pace, but the situation requires it. You must be my hands, for I am very slow.\n\nBring me what I need, and let Jamil and I worry about the rest.\n\nSpeak to me when you are ready to begin.", objectives = "Follow Jol's directions to assist in healing King Rastakhan.", progress = "Stay on your toes. You have more of them than I do.", completion = "<Jol wheezes.>\n\nThat did not... work how I imagined it would." }
WordHunterWoW_QuestEN[51678] = { title = "Rastakhan's Might", description = "Do you see de ship out in de bay, {name}?\n\nDat is my flagship, Rastakhan's Might. It is not here under my orders.\n\nWe will deal with de Prophet Zul in good time. For now, those who took my vessel must pay.\n\nYou are to bring me de head of Windcaller Ula'jan. De ship does not move without him, and it will not be moving again once he is dead!", objectives = "Collect Windcaller Ula'jan's skull aboard the flagship Rastakhan's Might.", progress = "Without de windcaller, my ship cannot be used to challenge my rule.", completion = "I will display dis behind my throne as a reminder. No one double-crosses Rastakhan and lives to speak of it." }
WordHunterWoW_QuestEN[51679] = { title = "A Strange Port of Call", description = "I know Rastakhan is furious dat dey claimed his ship, of all de vessels in our navy.\n\nBut dere is a better question to ask. Why did dey bring it here?\n\nZeb'ahari is a small fishing village. Dere are no warriors here, no powerful supporters of de king. Dere must be another reason.\n\nBoard de ship and have a good look around. See if you can find out why dey brought dat beast of a boat way out here.", objectives = "Search Rastakhan's Might for clues.", progress = "Did you learn anything, <name>?", completion = "I think I know what dis means, <name>, and it does not bode well for my loa." }
WordHunterWoW_QuestEN[51680] = { title = "In Bwonsamdi's Shadow", description = "Something is wrong, {name}.\n\nMy king is blessed by de loa in ways your kind cannot imagine. He has been given long life, swift healing, and strength beyond most trolls. But still, he lingers on death's door. I can practically hear Bwonsamdi laughing.\n\nTwo of his most trusted menders are with him. Go and find out what is taking so long.\n\nI will make sure dey are not interrupted.", objectives = "Speak to Jol the Ancient and Jamil Abul'housin.", completion = "Now you understand the precariousness of this situation. We will need your hands if we are to succeed in this complex bit of mending ahead of us." }
WordHunterWoW_QuestEN[51681] = { title = "Basic Witch", description = "", objectives = "" }
WordHunterWoW_QuestEN[51682] = { title = "Witches by the Dozen", description = "", objectives = "" }
WordHunterWoW_QuestEN[51683] = { title = "Slash and Burn Tactics", description = "", objectives = "" }
WordHunterWoW_QuestEN[51686] = { title = "Where My Witches at?", description = "", objectives = "" }
WordHunterWoW_QuestEN[51687] = { title = "A Smelly Solution", description = "", objectives = "" }
WordHunterWoW_QuestEN[51689] = { title = "Tortollan Rescue", description = "", objectives = "" }
WordHunterWoW_QuestEN[51690] = { title = "The Shadows of Corlain", description = "", objectives = "" }
WordHunterWoW_QuestEN[51691] = { title = "Almost Worth Saving", description = "We tried to evacuate as many of our people from the hold as we could, but some of the peons weren't so lucky. \n\nThey're worthless as fighters, but we'll need their labor in the times ahead.\n\nPlease, save them if you can.", objectives = "Rescue 6 Frightened Peons from Warfang Hold.", completion = "Good work, <name>. We'll have need of their labor when we rebuild." }
WordHunterWoW_QuestEN[51693] = { title = "Intercepting the Irontide", description = "", objectives = "" }
WordHunterWoW_QuestEN[51694] = { title = "Which Witch?", description = "", objectives = "" }
WordHunterWoW_QuestEN[51696] = { title = "Reclaiming What's Ours", description = "I'm impressed. You not only saved our people, but you also managed to kill the leader of the attacking forces.\n\nAt the top of this tower is our warhorn. At the signal, our troops will come running and we'll get this hold back under our control.\n\n{name}, I think you've earned the honors.", objectives = "Sound the warhorn and retake control of Warfang Hold in Stormsong Valley.", completion = "Good work, <name>\n\nMost of the buildings were easily repaired but we'll have to send to the Warchief for more troops.\n\nWe're going to have to fight for our place in this land... of this I'm certain." }
WordHunterWoW_QuestEN[51697] = { title = "Hunting for Truffle Hunters", description = "", objectives = "" }
WordHunterWoW_QuestEN[51699] = { title = "Blighted Monstrosity", description = "", objectives = "" }
WordHunterWoW_QuestEN[51703] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[51704] = { title = "Tracking Quest", description = "", objectives = "" }
