WordHunterWoW_QuestEN[51709] = { title = "Bombarbment", description = "", objectives = "" }
WordHunterWoW_QuestEN[51710] = { title = "Rise of the Yetis", description = "", objectives = "" }
WordHunterWoW_QuestEN[51711] = { title = "Having a Blast", description = "We're going to really hit 'em where it hurts, {name}.\n\nThey're carting tons of black powder right out of that mine. This could end very badly for all of us if we don't do something.\n\nThe mines are relatively undefended, I bet you can get in and wipe out their workers before they realize what's happening.\n\nKeep an eye out for some explosives, if we can use their own tools against them, even better!", objectives = "Acquire a Bundle of Dynamite and use it to kill 16 Warfang Miners and 4 Mine Technicians.", progress = "They won't stand a chance!", completion = "Sheesh... with all those explosions, I expect there's no one even left alive in that mine." }
WordHunterWoW_QuestEN[51712] = { title = "Eye for an Eye", description = "This is it, {name}. Now is the time to strike. \n\nTake this shredder and destroy their stronghold. Burn everything to the ground!\n\nShow no mercy. They certainly didn't offer any to all of the innocent civilians they slaughtered in Brennadam!", objectives = "Use the Prototype Shredder to burn 8 Warfang Buildings and kill General Blackstone and 30 Horde Soldiers.", progress = "Make them pay for what they've done to us.", completion = "I can't believe you actually pulled that off. We may actually stand a fighting chance now!" }
WordHunterWoW_QuestEN[51714] = { title = "Mission from the King", description = "Och, good ta see ya! Feels great ta stretch me gryphon's wings above the seas.\n\nI'm here ta assist with the war effort. Happy to help!\n\nLet's go meet with Master Shaw, matey.\n\nHa! Always wanted to say somethin' piratey. Did ya know they named a ship after me once? It was wild!", objectives = "Meet Spymaster Mathias Shaw on the Wind's Redemption.", completion = "Good, we're all here. I asked for you by name, <name>. Falstad as well." }
WordHunterWoW_QuestEN[51715] = { title = "War of Shadows", description = "Every war is fought on multiple fronts, {class}.\n\nKing Wrynn has tasked Halford Wyrmbane and his 7th Legion with securing our position in Kul Tiras as well as Zandalar.\n\nBut they cannot succeed without us. We are the unseen hand. The shadows in the darkness.\n\nI have been charged with establishing an elite strike force, and I need you to act as liaison between Wyrmbane's efforts and my own.\n\nYou will help direct our missions going forward. Let us begin.", objectives = "Send Falstad on a mission.", progress = "Without us, this war would be lost easily.", completion = "I am sure Falstad will handle this mission with his usual grace." }
WordHunterWoW_QuestEN[51717] = { title = "The Best Honey In Vol'dun", description = "If you can handle rescuin' de others by yourself, Zulsan and I will head back to de inn and start cleanin' up de place.\n\nDon't worry, I still be cookin' up a special batch of my famous scorpid blood drinks for you.\n\nIn fact, you gonna be runnin' right past my friend Rikati. He sells de best honey in all of Vol'dun!\n\nBring back a few bottles of it for me and let's add some sweetness to de drinks!", objectives = "Meet Rikati at The Four Stingers.", completion = "Rhan'ka sent you? He still owes me for the last batch of honey I sold him!" }
WordHunterWoW_QuestEN[51718] = { title = "Harvesting \"Honey\"", description = "I don't know what Rhan'ka's doing down in that oasis with all of the honey he's bought from me. Frankly, I suspect I don't even want to know.\n\nBut whatever his reasons, Rhan'ka is my best customer.\n\nSo even though my supply's getting low, because Rhan'ka sent you, I'll give you a special deal.\n\nThe wasps here keep all their honey stored in their stingers. Bring some to me, so I can drain them for honey and I'll give you a big batch of the sticky stuff to take back to Rhan'ka.", objectives = "Collect 12 Bilewing Stingers.", progress = "Don't fret if some sand gets mixed in. It'll taste the same either way.", completion = "It'll just take me a moment to get the honey out of these." }
WordHunterWoW_QuestEN[51719] = { title = "A Glaive Mistake", description = "", objectives = "" }
WordHunterWoW_QuestEN[51720] = { title = "Get Shredded", description = "I was scouting ahead while you were wreaking havoc in the mine.\n\nSpotted a hulking, armored shredder in their lumber yard. Bet we could do some real damage with that thing! \n\nI tried to start it up, but looks like it might be out of juice. Maybe they forgot to charge it?\n\nSee if you can grab a fresh power core from one of the other shredders nearby.", objectives = "Find an Energized Power Core and install it in the Prototype Shredder MK-03.", progress = "<Energized Core required.>", completion = "<As the key clicks into place and the new core activates, a low hum begins emitting from the shredder. It accelerates into a high pitched whirring as the instrument panels light up all over the cockpit.>" }
WordHunterWoW_QuestEN[51723] = { title = "Saw Dusted", description = "If we want to keep them from expanding into Stormsong, we need to cripple their lumber production!\n\nThey've only got so many lumberjacks running around. If we can cut some of them down, they'll be forced to reconsider their plans.", objectives = "Kill 10 Warfang Lumberjacks.", progress = "How many d'ya get?", completion = "Good work. That'll definitely put a damper on things." }
WordHunterWoW_QuestEN[51726] = { title = "Get Out of Here", description = "I can't believe you're here. Please, we need help!\n\nThey've been forcing us to mine nonstop. The weakest among us have been steadily dropping. At this rate, we'll all be dead soon.\n\nThe chains are weak. You may be able to pry the lock apart.\n\nI'll keep a lookout until the others are free. Don't worry about me!", objectives = "Free 6 Captured Miners.", progress = "Did you free everyone?", completion = "Thank you for rescuing us, we'd have been trapped in here until we all slowly perished." }
WordHunterWoW_QuestEN[51727] = { title = "A Shot at the Dark Iron", description = "", objectives = "" }
WordHunterWoW_QuestEN[51728] = { title = "Burn It All Down", description = "Alright, the flamethrower is all patched up. Now we're going to get a little payback for Brennadam!\n\nIf it's flammable, it's a target. If not, well, it probably still needs to die anyway. And let's bring down those siege towers while we're at it.\n\nBurn it all to the ground!", objectives = "Burn 6 Lumber Piles and 2 Siege Towers.", progress = "Well at least the flamethrower hasn't blown up on ya yet.", completion = "Nothing quite like the smell of freshly roasted Orc!" }
WordHunterWoW_QuestEN[51737] = { title = "Bruin Potions", description = "", objectives = "" }
WordHunterWoW_QuestEN[51738] = { title = "Witches by the Dozen", description = "", objectives = "" }
