WordHunterWoW_QuestEN[51747] = { title = "Early Warning", description = "", objectives = "" }
WordHunterWoW_QuestEN[51751] = { title = "Operation Royalty", description = "I think we've got a real shot at crippling their invasion force, here and now!\n\nWhile you were out there terrorizing those poor peons, I managed to sneak around and get a peek inside their camp.\n\nI spotted an armor clad undead in the great hall, he was poring over detailed battle plans.\n\nI'm willing to bet the very shirt off my back that he's their general. Think you're up for the challenge $p!?", objectives = "Kill General Blackstone.", completion = "I can't believe you actually pulled it off. We may actually stand a fighting chance now!" }
WordHunterWoW_QuestEN[51752] = { title = "Grizzled", description = "I saw a particularly ugly and quite agitated goblin barking orders at the rest of the miners.\n\nI'm willing to bet he's crucial to their entire operation. If you can get into the mine and eliminate him, hopefully it will throw things into disarray.", objectives = "Kill Chief Engineer Grizz.", completion = "Hopefully his death throws a wrench into their operation." }
WordHunterWoW_QuestEN[51753] = { title = "Champion: Rexxar", description = "", objectives = "Through countless wars, I've learned that those who stand alone will fall.\n\nLet us stand as one, <name>. Together, we will face anything our foes send our way." }
WordHunterWoW_QuestEN[51754] = { title = "Dogged Tenacity", description = "", objectives = "" }
WordHunterWoW_QuestEN[51758] = { title = "Weapons Shipment", description = "", objectives = "" }
