WordHunterWoW_QuestEN[51770] = { title = "Mission from the Warchief", description = "Lady Sylvanas issued orders for Garona Halforcen to take on a task of great import.\n\nShe will orchestrate missions from the Banshee's Wail, and is to assemble a strong force to execute on our plans.\n\nThis effort will be vital to our war against the Alliance, and your assistance will certainly be necessary.", objectives = "Walk with Garona Halforcen belowdecks on the Banshee's Wail.", completion = "Our task is not to be taken lightly, <name>." }
WordHunterWoW_QuestEN[51771] = { title = "War of Shadows", description = "I have begun to assemble heroes for our cause. Perhaps you already know Arcanist Valtrois? We will need to recruit more in the future, but this is a promising beginning.\n\nOur missions will be those of subterfuge, reconnaissance, assassination, and other focused strikes against our enemies.\n\nLet us test the mettle of this nightborne, shall we?", objectives = "Send Arcanist Valtrois on a mission.", progress = "I will not deviate from my mission.", completion = "Yes, this will do. The shadows will be stained blue with Alliance blood." }
WordHunterWoW_QuestEN[51772] = { title = "The Tortaka Tribe", description = "Have you ever met a tortollan before? Dey have all kinds of useful scrolls and artifacts for sale.\n\nWe used to trade often with de Tortaka tribe, but we haven't seen or heard from dem in weeks.\n\nDe tribe has a village in Darkwood Shoal. We need someone to make contact with dem and reestablish our trading partnership.", objectives = "Meet with Torka.", completion = "You're from the troll tribe at the arena? I'm afraid we don't have much to trade right now..." }
WordHunterWoW_QuestEN[51773] = { title = "The Ashvane Threat", description = "De Ashvane Trading Company has a mining operation in Redrock Harbor.\n\nDon't let de fancy name fool you, dey are as dangerous a band of pirates as I've ever seen.\n\nRecently, one of their crew members has been trying to make contact with us. I need someone to meet with him and see what he wants.\n\nIt might be a trap, but whatever information he has on de Ashvane Trading Company could prove useful to our survival.", objectives = "Meet with Randall Redmond.", completion = "You look like the kind of <race> that likes to make some coin. Am I wrong or am I right?" }
WordHunterWoW_QuestEN[51774] = { title = "Ragna", description = "", objectives = "" }
WordHunterWoW_QuestEN[51775] = { title = "Camp Lastwind", description = "A vulpera caravan recently set up camp not far from here.\n\nDis could be a good opportunity to establish new trade partners with de tribe.\n\nDe desert is a dangerous place, {name}. Go see if dey need any assistance. I'm sure dey could use experienced hands like yours.\n\nIn exchange, perhaps dey'd be willing to offer de tribe a discount on goods and services.", objectives = "Speak with Norah.", completion = "So you've come from the trolls at the arena and you're looking for work? I'd be happy to do business with you in exchange for a little help..." }
