WordHunterWoW_QuestEN[51783] = { title = "Zem'lan Rescue", description = "", objectives = "" }
WordHunterWoW_QuestEN[51784] = { title = "A Stroll Through a Cemetery", description = "Our next stop is in Drustvar.\n\nThere, along with some help, we shall identify and extract the body of a Kul Tiran war hero.\n\nWith his aid, we will learn much of the Kul Tiran fleet. Enough to break it with ease.\n\nWe shall meet you outside Barrowknoll Cemetery.\n\nDo try not to waste time, would you?", objectives = "Meet Nathanos Blightcaller outside Barrowknoll Cemetery. \n\nDread-Admiral Tattersail can bring you to Drustvar.", completion = "Ah <name>. You're here.\n\nYou remember Captain Stone, don't you? I think you shall find her quite a bit more... agreeable now." }
WordHunterWoW_QuestEN[51785] = { title = "Examining the Epitaphs", description = "Without Stone's knowledge, this mission shall require some extra legwork.\n\nRead the plaques in the cemetery. Find the corpse of the most import.\n\nThe rest should be quite simple.", objectives = "Examine 4 Grave Plaques in Barrowknoll Cemetery.", completion = "Marshal M. Valentine... yes, that name rings a bell. In a locked crypt, you say?\n\nThere are ways around that." }
WordHunterWoW_QuestEN[51786] = { title = "State of Unrest", description = "There is one thing you should know about ghosts, {name}.\n\nThey are a mockery of the dead. Spirits, holding on although they have no hope. In that form, they shall never truly live again. Not as long as they keep haunting our world.\n\nBut if they return to their bodies, perhaps they will become of specific use to us someday down the line.\n\nPut those spirits down.", objectives = "Kill 8 Enraged Spirits.", completion = "Perhaps we shall have use for these people one day.\n\nSurely they will be thankful." }
WordHunterWoW_QuestEN[51787] = { title = "Our Lot in Life", description = "It seems that Amalia isn't taking to undeath well.\n\nI know an herb that may help.\n\nThis cemetery is crawling with gravebloom. For the living, it grants the ability to see spirits.\n\nAs for the undead...\n\nThis may tie her back to reality just enough to be... sane.", objectives = "Collect 10 Gravebloom.", progress = "What Amalia is going through... is familiar to me. She will learn how to embrace her new status as Forsaken.\n\nI will help.", completion = "Ah yes... in perfect condition.\n\nThis should do the trick." }
WordHunterWoW_QuestEN[51788] = { title = "The Crypt Keeper", description = "I've been keeping my sights on the cemetery.\n\nThere is one ghost that walks with a purpose, unlike the others.\n\nHe is the crypt keeper, the keeper of the keys.\n\nIf we want to get to Valentine's body, we will need to go through the ghost first.", objectives = "Collect Valentine's Key from Brutus Thornton.", progress = "Nothing can stand in our way. Not today.", completion = "Only one thing left to do." }
WordHunterWoW_QuestEN[51789] = { title = "What Remains of Marshal M. Valentine", description = "We have the key. We found the crypt.\n\nNext, Valentine's body shall be ours.\n\nNo need to wait for Lilian and Stone. Let's finish this now.", objectives = "Assist Nathanos Blightcaller in retrieving Valentine's body.", progress = "No time to dally. We have plans to enact.", completion = "Another inconvenience. At least Stone finally proved herself useful." }
WordHunterWoW_QuestEN[51791] = { title = "Bubbling Totem Testing", description = "", objectives = "" }
WordHunterWoW_QuestEN[51792] = { title = "Erupting Totem Testing", description = "", objectives = "" }
WordHunterWoW_QuestEN[51793] = { title = "Bubbling Totem Testing", description = "", objectives = "" }
WordHunterWoW_QuestEN[51794] = { title = "Erupting Totem Testing", description = "", objectives = "" }
WordHunterWoW_QuestEN[51795] = { title = "The Battle for Lordaeron", description = "King Wrynn has mustered our forces, {name}. We mean to launch a full-scale assault on Lordaeron.\n\nWe'll drive the Horde from the keep and reclaim it for the Alliance. It's been far too long since our flag flew in Tirisfal.\n\nReady to ship out? Captain Angelica here will see to your transport.", objectives = "Complete the Battle for Lordaeron.", completion = "Ah, good to see you back on your feet, <name>. Many others were not so fortunate.\n\n\n\nKing Anduin has returned to Stormwind Keep. He must plan what our next move will be." }
WordHunterWoW_QuestEN[51796] = { title = "The Battle for Lordaeron", description = "The Alliance has called its banners and marches on the Undercity.\n\nNow the war has truly begun.\n\nOur mage will send you on your way. Go.\n\nSee to our defenses, and get the civilians to safety. I will join you soon.\n\nLok-tar ogar, {name}.", objectives = "Complete the Battle for Lordaeron.", progress = "The High Overlord awaits.", completion = "Our war has only begun." }
WordHunterWoW_QuestEN[51797] = { title = "Tracking Tidesages", description = "Rexxar has been tracking a powerful tidesage to help us find the body of Marshal Valentine. He has sent word of a breakthrough.\n\nTravel to Stormsong. Help the half-ogre and Lilian find this tidesage, and bend him to the will of the Horde.\n\nDo not come back without a way to find Marshal Valentine.", objectives = "Meet Rexxar within Warfang Hold in Stormsong.", completion = "<name>. I'm aware of what the Horde needs. Let's get started." }
WordHunterWoW_QuestEN[51798] = { title = "No Price Too High", description = "I have tracked a tidesage to a camp nearby. He has been staying there with his family.\n\nBe warned, tidesages are powerful foes. They have mastery over all the elements, and some even manipulate the Void.\n\nIf this man is with his family, it means he may not give up so easily. \n\nLet us hope he's smart enough to keep them out of this.\n\nCome.", objectives = "Help Rexxar track down a tidesage.", completion = "Let's hope this tidesage is telling the truth or else it's about to get very bloody." }
WordHunterWoW_QuestEN[51800] = { title = "Foothold: Tiragarde Sound", description = "Tiragarde Sound has lotsa pirates on da coastline.\n\nI made contact wit' a first mate of a crew, and she tinks we can take on da captain and get a nice outpost in de process.\n\n          - Shadow Hunter Ty'jin", objectives = "Assist Shadow-Hunter Ty'jin in Tiragarde Sound." }
WordHunterWoW_QuestEN[51801] = { title = "Foothold: Drustvar", description = "It seems Drustvar has a big seam of Azerite underground.\n\nDo you like profit? I LOVE profit. This seems like a golden opportunity, if ya catch my meanin'. Time is money!\n\n          - Trade Prince Gallywix", objectives = "Assist Gallywix and Eitrigg in Drustvar.", completion = "You have chosen to sail to Drustvar." }
WordHunterWoW_QuestEN[51802] = { title = "Foothold: Stormsong Valley", description = "We established and fortified an outpost in Stormsong Valley called Warfang Hold.\n\nThe Kul Tiran forces have it surrounded and an attack is imminent. We need reinforcements. Do not delay.\n\n                                 - Rexxar", objectives = "Assist Rexxar in Stormsong Valley.We established and fortified an outpost in Stormsong Valley called Warfang Hold.\n\nThe Kul Tiran forces have it surrounded and an attack is imminent. We need reinforcements. Do not delay.\n\n                                 - Rexxar" }
WordHunterWoW_QuestEN[51803] = { title = "The Kul Tiras Campaign", description = "Our enemy spreads its influence throughout Kul Tiras, recruiting new allies to fight against the Horde.\n\nWe must establish footholds in these enemy lands if we are to win this war.\n\nThe Warchief requires your assistance in securing outposts in Stormsong Valley, Drustvar, and Tiragarde Sound.\n\nWhich location shall we secure first?", objectives = "Use the Kul Tiras Campaign Map to choose a foothold.", completion = "You have the Queen's trust. For now." }
WordHunterWoW_QuestEN[51804] = { title = "Running Interference", description = "", objectives = "" }
WordHunterWoW_QuestEN[51805] = { title = "They Will Know Fear", description = "Finally, a chance to strike at the Alliance AND Kul Tirans!\n\nSagehold is crawling with initiate tidesages studying magic and Kul Tirans trying to fortify the place against the Horde.\n\nLet's strike some fear into them. Make them rethink trying to help the Alliance fight the Horde.\n\nTake this horn. In my hands, it calls a val'kyr. In yours, it will sow terror amongst our enemies.\n\nI trust you above all others with this horn. Do not let me down.", objectives = "Terrorize 20 Kul Tiran Builders or Tidesage Recruits with the Val'kyr Horn.", completion = "I could hear their screams from here! Maybe now the Kul Tirans will rethink helping the Alliance." }
WordHunterWoW_QuestEN[51806] = { title = "Pest Remover Mk. II", description = "", objectives = "" }
WordHunterWoW_QuestEN[51810] = { title = "Captain Hartford", description = "I'm almost ready to leave Vol'dun once and for all. There's just one thing left to be done...\n\nWe need to murder the captain of the ship.\n\nIf Captain Hartford finds out I've deserted, I won't be safe in Boralus or anywhere else. He'll hunt me to the Eastern Kingdoms and back if he has to!\n\nThis will be dangerous. So you'll want to disguise yourself before boarding The Siren's Call.\n\nThis will be our last job together. Do it and I'll give you the code to the captain's lockbox. A pirate's bounty!", objectives = "Slay Captain Hartford.", completion = "A toast to the former captain of The Siren's Call. He was a good man, but good men don't live long around here!" }
WordHunterWoW_QuestEN[51811] = { title = "Trapped Tortollans", description = "", objectives = "" }
WordHunterWoW_QuestEN[51813] = { title = "Blackrock Depths", description = "Have you heard how the Dark Iron dwarves joined the Alliance? It was a most unusual turn of events.\n\nBrave heroes of the Alliance had been fighting the Dark Iron dwarves for years until a schism happened in their ranks.\n\nMoira Thaurissian, estranged daughter of the former dwarven king Magni Bronzebeard, was leading a faction of the Dark Iron dwarves.\n\nMoira wished to aid the Alliance. This began with an offer to help research Azerite and its potential uses within Blackrock Depths...", objectives = "Speak with Moira at the Stormwind Embassy to travel to Blackrock Depths.", progress = "The mind o' a <race> is a glorious thing.", completion = "Meddlin' goblin bastards!\n\n<Moira takes a deep breath.>\n\nSorry, I just canna abide those green miscreants any longer." }
WordHunterWoW_QuestEN[51814] = { title = "Ravoracious", description = "", objectives = "" }
WordHunterWoW_QuestEN[51815] = { title = "Eggstermination", description = "", objectives = "" }
WordHunterWoW_QuestEN[51816] = { title = "Pterrible Ingredients", description = "", objectives = "" }
WordHunterWoW_QuestEN[51817] = { title = "Trapped Tortollans", description = "", objectives = "" }
WordHunterWoW_QuestEN[51818] = { title = "Commander and Captain", description = "This brings me no joy, {name}, but I will do what I must to make sure my family is happy and safe.\n\nI would prefer we avoid violence, but if we must... there are two targets. Their leaders. Captain Malia and Commander Augustine.\n\nTheir loss should force the two groups to retreat from the area. \n\nAlso, Augustine confiscated a book of mine. Recover it and my powers are yours, for however long I have left.", objectives = "Kill Captain Malia and recover the Book of Forbidden Magics from Commander Augustine.", progress = "I don't need the details of what happened down there. Just the book.", completion = "I won't dwell on the grim task you've done. But I will show you just what this dying man is capable of, now that I have my book." }
WordHunterWoW_QuestEN[51819] = { title = "Scattering Our Enemies", description = "We've been scouting the area of Sagehold for some time now. It was recently retaken by a large force of Alliance and Kul Tirans.\n\nWe have been waiting for an opportunity to strike when their defenses were weakened. Now is that time.\n\nGo down to Sagehold and show the forces that remain what happens to those who take up arms against the Horde.", objectives = "Kill 10 Alliance and Kul Tiran soldiers within Sagehold.", completion = "Good. The area of Sagehold should be overrun again by the rebel tidesages once we are done." }
