WordHunterWoW_QuestEN[51829] = { title = "Ranah's Wrench", description = "<The wrench is worn from repeated use, but otherwise appears to be in good shape. \n\nEngraved on the handle is the name: Ranah.>", objectives = "Deliver the wrench to Ranah in the Withering Gulch.", progress = "Do you have something for me?", completion = "I've been looking everywhere for this!" }
WordHunterWoW_QuestEN[51830] = { title = "Zelling's Potential", description = "<cough> My body won't last much longer, but Miss Voss insists I display what my powers truly are.\n\nI can instill within you a <cough> <wheeze> magical font that will absorb void essence from slain creatures.\n\nWhen the font is full, you can unleash devastating wind magic.\n\nGo to <cough> Port Fogtide. There you will find those tainted by the Void.\n\nSlay them, fill the font, and you will <wheeze> see my magic at work.", objectives = "Fill Zelling's Void Font by slaying enemies in Port Fogtide and unleash his devastating wind magic.", progress = "Is this <cough> enough for you?", completion = "We all <cough> saw the magic from here. Miss Voss believes the time has come." }
