WordHunterWoW_QuestEN[51837] = { title = "Whatever Will Be", description = "Well, here we are. Zelling seems like he'll be a powerful asset, as long as we ensure his family is taken care of.\n\nHe doesn't have much time left. Let's see if he can locate Marshal Valentine for us before he passes.", objectives = "Get Zelling to locate Marshal Valentine.", progress = "Well?", completion = "We had best get moving. As much as I want this to turn out differently... odds are it won't." }
