WordHunterWoW_QuestEN[51845] = { title = "Storm's End", description = "I've no doubt he can feel our presence, but so long as Lord Stormsong maintains his spell the first move is ours. \n\nWe have him surrounded, cornered like the rat he is. We must end this together.", objectives = "Confront Lord Stormsong.", completion = "Samuel was a good man, with a true heart. A fool... but our fool." }
