WordHunterWoW_QuestEN[51870] = { title = "Island Expedition", description = "Our spies have intercepted an Alliance message describing an outcropping of Azerite out in the Great Sea.\n\nThe Banshee's Wail isn't quick enough to get us there before they do. Lucky for us, I've arranged to have a Zandalari ship rigged and ready to go for opportunities like this.\n\nGo speak with Captain Rez'okun on the western side of the docks. He's been briefed, and should be waiting for you.", objectives = "Report to Captain Rez'okun at the Port of Zandalar.", completion = "You da Horde champion I'm waitin' for? Let's get to work." }
WordHunterWoW_QuestEN[51874] = { title = "Gorged Boar", description = "", objectives = "" }
WordHunterWoW_QuestEN[51881] = { title = "The Mine Sweeper", description = "<One of the goblin flamethrowers. Unfortunately the tank has been cracked. It would be a good idea to bring it back to Felecia, she might have something to fix it up.>", objectives = "Deliver the Cracked Mine Sweeper to Felecia Gladstone just outside the Saltstone Mine.", completion = "A flamethrower!? This could be quite useful, but why couldn't you find one in better shape?" }
WordHunterWoW_QuestEN[51884] = { title = "Haywire Golem", description = "", objectives = "" }
