WordHunterWoW_QuestEN[51888] = { title = "Island Expedition", description = "We better be quick if we're gonna get to de island before de Alliance.\n\nYou ready?", objectives = "Speak with Captain Rez'okun to start the expedition, then explore the Uncharted Island.", progress = "Ready when you are.", completion = "Nice work, <name>. We make a good team. Let's do this again sometime." }
WordHunterWoW_QuestEN[51889] = { title = "The Wrath of Grapes", description = "You look familiar. Do you owe me money? Wait... no, that's not it.\n\nIf you are here to learn, I could show you my secret mining technique, bu- Ugh...\n\nI'm a little busy trying to see straight right now. Ugh... it feels like someone is swinging a pick at my skull. \n\nThe best cure for a hangover is pickle juice, a big greasy breakfast, and whatever I did not finish last night.\n\nTell you what, get me those things, preferably quickly and quietly, and I will teach you whatever ya want.", objectives = "Bring a Jar of Pickle Juice, a Mountain of Bacon, a Pile of Sausages, and a Hillock of Eggs to Franklin The Drunk.", progress = "These shadows are loud. Can you fix that, too?", completion = "I needed this!\n\n<Franklin spends several moments shoveling food into his mouth.>\n\nMmm... Right! If I recall correctly, you were asking about storm silver seams?\n\nLet me tell you my secret technique, not even Myra knows. The metal is prone to stress fractures, but instead of scoring the metal where it meets the rock and breaking it off, just remove the rock.\n\nThe metal naturally forms prisms, and can be easily pulled out of the stone without wasting anything once it is loosened up." }
