WordHunterWoW_QuestEN[51904] = { title = "Island Expedition", description = "Alright! Let's snap to it! We've got to get to that island before the Horde does, don't we?\n\nYou ready?", objectives = "Speak with Flynn Fairwind to start the expedition, then explore the Uncharted Island.", progress = "Ready when you are.", completion = "You and I make a pretty good team, don't we? Let's, uh, do this again sometime." }
