WordHunterWoW_QuestEN[51961] = { title = "The Ongoing Campaign", description = "We have made excellent progress on Zandalar, {name}, but we must continue to expand our influence.\n\nIt is time for us to cross the sea once again to exert pressure on enemy lands, lest they fall fully into Horde hands.\n\nWhich location shall we secure next?", objectives = "Use the Zandalar Campaign Map to choose a foothold.", completion = "Excellent choice, <name>." }
WordHunterWoW_QuestEN[51962] = { title = "Lumbering Away", description = "The hardwoods in dis jungle are dense enough dat dey rival coal in terms of how much heat a skilled miner can get out of dem.\n\nThe biggest problem using local timbers, however, is dat de jungle is always wet. If de wood is not stored properly, it takes weeks to dry out entirely.\n\nI bring dis up because my forge is starting to run low on fuel.\n\nBring me some dry firewood to keep it going, and in exchange I will teach you a trick for mining monelite.", objectives = "Collect 9 Pieces of Dry Firewood.", progress = "Have you got more wood for me?", completion = "Dis should do nicely.\n\nListen well for your reward: When you are mining monelite, do not just chip away at de rock. Instead, try using de pick to pierce de metal, and den peel all of it away from de rock." }
WordHunterWoW_QuestEN[51963] = { title = "The Wrath of Vorrik", description = "", objectives = "" }
WordHunterWoW_QuestEN[51964] = { title = "Insufferable Bloodsuckers", description = "{name}! I have some actual work that you could do for me.\n\nSince your mining skills are still not what Zandalari consider \"decent\", in exchange, I will show you how to mine monelite better.\n\nDe blood trolls of Nazmir have dese enormous ticks that they keep as pets and I have heard dat dey have managed to get within de borders of Zuldazar to de north. Dis does not sit well with me.\n\nThin their numbers for me, so I can happily die by being eaten by a pterrordax or something else respectable instead.", objectives = "Kill 8 Bloodbelly Flyers and 8 Blood Trolls.", completion = "Commendable effort, and you seem no worse for wear. I need to remember dis next time I need something exterminated.\n\nI doubt you have noticed that monelite is extremely maleable, ya? Otherwise I would not have to teach you dis method. But you can exploit its malleability, even before smelting it.\n\nBy using your pick to deform the metal while it is still in the vein, you can cause it to heat up and get a bigger haul using the other technique I taught you." }
WordHunterWoW_QuestEN[51965] = { title = "Lending a Hand", description = "If you are looking for some work, I have something you can do.\n\nI went mining recently and a diemetradon managed to bite off my hand before I could get away from it.\n\nI do not care about the hand, I have already regenerated dat, but I did lose a couple rings dat I made.\n\nIf you go get them back, I will show you how to harvest more monelite from a seam. Or not. I do not care, but if you were looking for a chance to finally impress me, dis could be it.", objectives = "Retrieve Secott's Rings.", progress = "For de record, those rings are worth more den your life. Empirically speaking, of course.", completion = "<Secott places the rings on his new hand.>\n\nGood! As a goldsmith without jewelery, I was beginning to feel naked.\n\nVery well, your lesson is that when you are mining monelite from a seam, it behaves very differently than a normal deposit.\n\n<Secott spends as little time as necessary explaining the different techniques of mining monelite seams.>" }
WordHunterWoW_QuestEN[51967] = { title = "Return to Boralus", description = "I think that's enough excitement for today, lad!\n\nWhy don't ya get back ta Wyrmbane and tell the man we've got this place all under control.\n\nI'll make sure the blood trolls don't get any more of our folk! Ha!", objectives = "Return to Halford Wyrmbane on the Wind's Redemption in Boralus Harbor. Desha Stormwallow can give you a ride.", completion = "The lands of Nazmir are cruel to all who enter, but Fort Victory shall stand firm in the face of danger.\n\nWell done, <name>." }
WordHunterWoW_QuestEN[51968] = { title = "Return to Boralus", description = "You know, a lot has happened since you arrived in Zuldazar! I'm sure Mr. Wyrmbane would appreciate a report.\n\nOh, not from me. Maybe somebody a bit more serious... like you!\n\nI bet Daria over here could get you back pretty quick!", objectives = "Return to Halford Wyrmbane on the Wind's Redemption. Daria Smithson can give you a ride.", completion = "We'll base our operations out of Xibala, then. And I'll have some reinforcements sent out to assist Brigadier Thom.\n\nThank you for your report, <name>. Well done." }
WordHunterWoW_QuestEN[51969] = { title = "Return to Boralus", description = "Shatterstone Harbor is an expansive foothold, and one that we will use to great advantage against the Horde.\n\nI will leave Umbric and the others in charge here. Let's get back to the Wind's Redemption and return to Boralus.", objectives = "Return to Halford Wyrmbane on the Wind's Redemption in Boralus.", completion = "The waters outside Vol'dun are rough, but Jes-Tereth is one of the best helmsmen on the sea!\n\nLet us roll one victory into another." }
WordHunterWoW_QuestEN[51970] = { title = "The Caterer", description = "", objectives = "" }
WordHunterWoW_QuestEN[51971] = { title = "An Exquisite Brooch", description = "You find a bloody brooch that features impeccable craftsmanship.\n\nThe design and quality of work reminds you of rings you previously recovered for Secott.\n\nPerhaps this is another item he lost and would like to see returned.", objectives = "Bring the Exquisitely Crafted Brooch to Secott.\n\nProvided item:", completion = "Wow, dis is a nice brooch. Good craftsmanship in it.\n\nWhoever it used to belong to, it is mine now.\n\n<Seeing the disapproval on your face, Secott sighs heavily while rolling his eyes and gives you a sidelong glance.>\n\nTell ya what, in exchange for dis, I guess I can tell you the rest there is to know about mining monelite seams.\n\n<Secott explains in depth, several techniques which will allow you to mine monelite from seams more effectively.>" }
WordHunterWoW_QuestEN[51972] = { title = "Lost Goat", description = "", objectives = "" }
WordHunterWoW_QuestEN[51974] = { title = "Sabertron", description = "", objectives = "" }
WordHunterWoW_QuestEN[51975] = { title = "Champion: Shadow Hunter Ty'jin", description = "", objectives = "You be impressin' me wit ya skills in parleyin', boss-mon.\n\nI tink da two of us should be stickin' togetha. Da spirits insist!\n\nDon't be worryin'. I'll get changed." }
WordHunterWoW_QuestEN[51976] = { title = "Sabertron", description = "", objectives = "" }
WordHunterWoW_QuestEN[51977] = { title = "Sabertron", description = "", objectives = "" }
WordHunterWoW_QuestEN[51978] = { title = "Sabertron", description = "", objectives = "" }
WordHunterWoW_QuestEN[51979] = { title = "The Ongoing Campaign", description = "The Warchief wishes for us to continue spreading our influence throughout Kul Tiras.\n\nWith our grip on Zandalar on the rise, now is the time to move forward with this objective in the lands of the enemy.\n\nWhich location shall we secure next, {class}?", objectives = "Use the Kul Tiras Campaign Map to choose a foothold.", completion = "You have made your choice." }
WordHunterWoW_QuestEN[51980] = { title = "WANTED: Jabra'kan", description = "To any hunters worthy of the challenge:\n\nFind and defeat the troll known as Jabra'kan. His poaching ways have robbed Warbeast Kraal of valuable eggs, hides, and beasts for their pens.\n\nSeek out Wingrider Nivek for your reward.", objectives = "Slay Jabra'kan the Poacher.", progress = "If I see dat thieving wretch, I will wear his tusks for a necklace. Is it done?", completion = "You have my thanks. He was a slippery one, dat poacher." }
WordHunterWoW_QuestEN[51981] = { title = "Earthcaller's Abode", description = "", objectives = "" }
WordHunterWoW_QuestEN[51982] = { title = "Storm's Rage", description = "Horde forces are pushing deeper into Stormsong Valley. We can not allow this aggression to go unchecked!", objectives = "Repel the Horde forces assaulting Stormsong Valley.", progress = "We cannot rest until the people of Stormsong Valley are protected from the Horde!", completion = "You served the people of Stormsong Valley, and the Alliance, well today. Thank you, <name>. With persistence, we will drive the Horde from this land." }
WordHunterWoW_QuestEN[51983] = { title = "Vorrik's Vengeance", description = "", objectives = "" }
WordHunterWoW_QuestEN[51984] = { title = "Return to Zuldazar", description = "Look at dis place, boss-mon! We got da pirates, a location close to da Kul Tiran capital...\n\nI tink we should be bein' pretty proud of dis one.\n\nWe should get goin' back and tell Nathanos about our success. Maybe we can even get him to crack a smile.", objectives = "Return to Nathanos Blightcaller on the Banshee's Wail. Erul Dawnbrook can give you a ride.", completion = "That's quite a location Ty'jin scoped out.\n\nThe pirates are another boon. If we ever need some bodies to fall on swords for us... they will do." }
WordHunterWoW_QuestEN[51985] = { title = "Return to Zuldazar", description = "You know kid, I think I've got it all covered here. My guys will find all the Azerite they can here and make me rich!\n\nI mean, you know, make the Horde rich. With power!\n\nAnyway, you can go tell Nathanos we're done here. This base is the best place to launch any attacks against the Kul Tirans here in Drustvar -- that's a Gallywix guarantee!", objectives = "Return to Nathanos Blightcaller on the Banshee's Wail. Swellthrasher in Anyport can give you a ride.", completion = "You've established a foothold in Drustvar with the goblins? Good.\n\nI will have my men keep an eye on Gallywix's activities there. Just in case." }
WordHunterWoW_QuestEN[51986] = { title = "Return to Zuldazar", description = "Warfang Hold is our most secured of the footholds we hold in Kul Tiras.\n\nKaga and her forces will be able to keep fortifications running, thanks to you. The Alliance will never see us coming!\n\nTell Nathanos that we have succeeded in our mission. I will help here until I am needed.", objectives = "Return to Nathanos Blightcaller on the Banshee's Wail. Muka Stormbreaker can give you a ride.", completion = "Warfang Hold is an important strategic base for the Horde.\n\nIt is imperative that it stays safe. Rexxar will see to that." }
WordHunterWoW_QuestEN[51987] = { title = "Champion: Hobart Grapplehammer", description = "", objectives = "Now that everything's all set up around here, I'm out of work!\n\nI bet you're going to need a pretty handy engineer. Why don't you take me along with ya?" }
WordHunterWoW_QuestEN[51988] = { title = "Whitney \"Steelclaw\" Ramsay", description = "", objectives = "" }
WordHunterWoW_QuestEN[51989] = { title = "Braedan Whitewall", description = "", objectives = "" }
WordHunterWoW_QuestEN[51990] = { title = "Wings for the Kraal", description = "It seems your little one needs a moment to rest after dat adventure. I will look after it.\n\nIf you want to make yourself useful while you wait, I heard de pterrordaxes to de north have been laying lots of eggs recently. Go collect de ones dat are wiggling and making noises. Dey are about to hatch.\n\nOur beasts breed well, but we always need more wings for de kraal.", objectives = "Collect 8 Nearly-hatchling Pterrordax Eggs.", progress = "Do you have de eggs I asked for?", completion = "I will get dese to a handler. We should be de first thing dey see if we want to keep dem." }
WordHunterWoW_QuestEN[51991] = { title = "Charging the Batteries", description = "These little fellas are ravenous whirlwinds of devouring destruction. When they get going, they consume anything in their path, without even stopping! When sated, they discharge power from them little 'lectric zingers on their heads! \n\nThen they nap.\n\nLucky for us, we found just the right frequency to control their tiny bug brains. Hit that device, and you can take your own little zapper out for a spin... literally!\n\nMake sure ya bring it back full, so we can keep our rigs charged!", objectives = "Fill that ranishu's belly.", progress = "All juiced up?", completion = "Hey! Not bad for your first time! They're so ugly they're cute, aren't they?" }
WordHunterWoW_QuestEN[51995] = { title = "Vorrik's Vengeance", description = "", objectives = "" }
WordHunterWoW_QuestEN[51996] = { title = "Earthcaller's Abode", description = "", objectives = "" }
WordHunterWoW_QuestEN[51997] = { title = "Thar She Sinks", description = "", objectives = "" }
WordHunterWoW_QuestEN[51998] = { title = "DGH: Now With Real Direhorn", description = "...Listen, {name}. I need one more thing to finish making this supplement of mine.\n\nDirehorn Growth Hormone can't exactly be made without, you know, actual direhorn. But I floated the idea of harvesting a few of their beasts and all of a sudden I got a bunch of spears pointed at me.\n\nSo I came up with another plan.\n\nThose flying beasts eat direhorns, right? The big green flappy ones. I'm sure if you kill a few of them you'll find all the direhorn bits I need.", objectives = "Collect 8 Partially-Digested Direhorn Flesh.", progress = "We'll keep this between you and me, okay?", completion = "Let's not talk about this ever again. Deal?" }
WordHunterWoW_QuestEN[52003] = { title = "Champion: Kelsey Steelspark", description = "", objectives = "You know <name>, I've been following your adventure for a while and I just think you're so cool!\n\nI was hoping that maybe I could tag along with you, maybe help you out? I'm not so good in a fight, but nobody can beat my mechanical skill!" }
WordHunterWoW_QuestEN[52004] = { title = "Counter Intelligence", description = "", objectives = "" }
WordHunterWoW_QuestEN[52005] = { title = "Mission Report: The Wolf's Den", description = "<Your followers have sent a report regarding the assault on Wolf's Den.\n\nIt details that victory was hard-fought, but all of the bandits previously living in the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.>", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission to Tiragarde Sound?", completion = "It seems the mission to create an additional foothold in Tiragarde Sound was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52006] = { title = "Preemptive Assault", description = "", objectives = "" }
WordHunterWoW_QuestEN[52007] = { title = "Engines of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[52008] = { title = "Champion: Magister Umbric", description = "", objectives = "I swear, sometimes I don't know how I end up in these situations!\n\nFirstly, there is nothing of interest to me here. Secondly, the heat is absolutely sweltering. I would have understood if I was requested to study the stone that the sethrak held... but alas.\n\nWould you take me out of here and let me get back to doing work of actual import?" }
WordHunterWoW_QuestEN[52009] = { title = "Crab People", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52010] = { title = "The Tendrils of Fate", description = "", objectives = "" }
WordHunterWoW_QuestEN[52011] = { title = "Fiendish Fields", description = "", objectives = "" }
WordHunterWoW_QuestEN[52012] = { title = "Wolves For The Den", description = "Our scouts have spotted a large pack of dire wolves not far from here. This is a good omen!\n\nWe should send a beast master to capture the wolf pack and bring them to the outpost to be tamed.\n\nThe dire wolves will make fine hunting companions and sniff out any Alliance spies that come poking around!", objectives = "Complete the mission, \"Wolves For The Den.\"", completion = "Rexxar brought us a fine pack dire wolves, <name>. Our operation will be much more secure with the dire wolves patrolling the outpost!" }
WordHunterWoW_QuestEN[52013] = { title = "Champion: John J. Keeshan", description = "", objectives = "Now that we've settled in here... I aim my sights higher.\n\nYou've dealt with Conrad. You've dealt with the blood trolls. What's next for you, I wonder?\n\nWhatever it is, I'm in. You're going to need a hardcore, experienced, tenacious combatant like me if you plan on winning this war!" }
WordHunterWoW_QuestEN[52014] = { title = "Ritualistic Preparations", description = "I have received a request for a shipment of storm silver. It is a fine metal, lightweight and resistant to corrosion. We use it althroughout our ships. It is so strong even de naga use it in some of their weapons!\n\nHowever, any parts that go into de ship have to be blessed by a wavesinger. I can not be bothered with dat nonsense. I do not believe it needs these extra blessings, but what do I know?\n\nHarvest a bucketful of ore and get it blessed for me, and I will teach you how to mine it easier.", objectives = "Mine Unsanctified Storm Silver Ore, smelt it into Unsanctified Storm Silver Bars, and get them blessed by Wavesinger De'zan.", progress = "Did you get those storm silver bars? Don't forget dat it needs to be blessed. Otherwise dey are 'land metal' and will curse a ship.", completion = "Nice, dis looks good. Dey should not be able to tell dat I didn't gather it myself.\n\nThese bars will be used as part of our next warship. Well, after dey get gold plated.\n\nWhat? You did not think dat de ornaments were solid gold, did you?  Ha! Dat would cause dem to weigh tons!\n\nNow then, you scratched my back, and I will scratch yours. Storm silver is very brittle naturally. When you mine it, use several small swings instead of one big one. Dis keeps de metal from being chipped away." }
WordHunterWoW_QuestEN[52015] = { title = "Brined Justice", description = "{name}, I just got word dat one of our ships was attacked and a large amount of storm silver stolen!\n\nDe sacred materials can not be replaced. Once it is blessed by de wavesinger, it is buried underwater for a year. While I do not care for such nonsense, others do, and will not sail on dat ship.\n\nFrom what I heard, a group of naga followed de ship to see where the metal was buried on de sea floor before killing de crew and taking her cargo.\n\nKill de naga, and get me dat metal!", objectives = "Collect 100 Stolen Storm Silver Bars.", progress = "Loa damn de naga!\n\nHave you found de bars?", completion = "Ah!  Dis is fantastic news! I will have someone run these out to da docks right away.\n\nI was starting to fear dat you might not make it. Not dat I care, I just did not want to have to explain myself twice.\n\nDat said, you have avenged my people.  In exchange, let me show you the finer points of harvesting storm silver.\n\n<Secott takes the next several minutes to explain what he knows about harvesting storm silver deposits.>" }
WordHunterWoW_QuestEN[52016] = { title = "Three Sheets to the Wind", description = "You want to know more about storm silver?\n\nFine, if you are mining from a seam and make a mistake, you can make a deadly cloud of powderized metal. Now go.\n\n<After a moment Secott's face softens.>\n\nI am very busy, but if you insist on not dying, you should talk to my former apprentice, Biru. He is a drunk at Spirits Be With You, but he has some knowledge.\n\nTalk to Ximo, de Innkeeper, and buy him a drink. If he likes it, he'll talk, if not... well, I hope you have enough coin for more drinks.", objectives = "Bring Biru The Drunk a drink he likes to learn his mining secrets.", progress = "<Secott's former apprentice, Biru, drunkenly stares at you.>\n\nWhadda you wan?", completion = "<Biru rambles almost incoherently, explaining the mechanics of mining storm silver from a seam>\n\n... and dat is how you... get de most of mining... Zzz...\n\n<As Biru drifts to sleep amidst a pungent cloud of brandy vapors, you think of the advice he provided.\n\nEager to experiment with your new mining technique, you leave the sleeping troll laying where he is.>" }
WordHunterWoW_QuestEN[52017] = { title = "Back to Biru", description = "Oh, you are still here?\n\nWell, I wish I could help you but being de only goldsmith in de city of gold, I am unsurprisingly busy.\n\nI heard you had built a rapport with Biru. I'm sure he remembers more, if you're still looking for more information.\n\nAsk him if he can show you anything else. Tell him if he keeps you from bothering me for the rest of de day, I will stop sending fool hardy miners to him.", objectives = "Speak with Biru The Drunk.", completion = "Secott sent you?\n\nWait... my old master? Dat Secott?" }
WordHunterWoW_QuestEN[52023] = { title = "Informing the Horde", description = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts.\n\nWere it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive.\n\nWe must inform our allies of what has transpired in Vol'dun.\n\nI'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now.\n\nI'm sure our paths will cross again, {name}. It was an honor fighting with you.", objectives = "Speak with Baine Bloodhoof.", completion = "I shall inform the Dark Lady of your activities in Vol'dun at once. She will know how to best proceed against this  new threat." }
WordHunterWoW_QuestEN[52024] = { title = "Informing the Horde", description = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts.\n\nWere it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive.\n\nWe must inform our allies of what has transpired in Vol'dun.\n\nI'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now.\n\nI'm sure our paths will cross again, {name}. It was an honor fighting with you.", objectives = "Speak with Baine Bloodhoof.General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts.\n\nWere it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive.\n\nWe must inform our allies of what has transpired in Vol'dun.\n\nI'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now.\n\nI'm sure our paths will cross again, <name>. It was an honor fighting with you.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[52026] = { title = "Overseas Assassination", description = "Ready to go to war, {name}?\n\nMathias Shaw has assembled a list of priority Horde targets, and the first is an influential blood elf by the name of Arlethal Sunwatcher. Intelligence shows that he's the highest ranking member of the Reliquary, an elite blood elf excavation force.\n\nHe's just standing out in the middle of the desert in Vol'dun, practically begging to be assassinated. Shall we?", objectives = "Speak with Grand Admiral Jes-Tereth to sail to Vol'dun.", completion = "Here we are. Let's begin." }
WordHunterWoW_QuestEN[52027] = { title = "The Vol'dun Plan", description = "Our target: Arlethal Sunwatcher, High Examiner of the Reliquary.\n\nBefore we charge off blindly into the dunes, however, I'd like to hold a quick strategy meeting with you and the others.", objectives = "Discuss strategy with Halford Wyrmbane and Shandris Feathermoon.", progress = "Let's talk strategy, <name>.", completion = "I admire Shandris's... directness.\n\nWe will proceed with both plans. Let's move." }
WordHunterWoW_QuestEN[52028] = { title = "Comb the Desert", description = "It's time to mobilize, then.\n\nI'll stick with you, {name}. Keep an eye out for Horde activity.", objectives = "Search Vol'dun for Horde activity.", completion = "I don't think she's spotted us yet." }
WordHunterWoW_QuestEN[52029] = { title = "Dirty Work", description = "That surveyor is wearing a Reliquary tabard. Sunwatcher must be hiring goblins to do his dirty work while he lounges somewhere in the shade.\n\n<Shandris nocks an arrow in her bow.>\n\nLet's find out what she knows.", objectives = "Slay Nazlara and find out what she knows.", progress = "What is that goblin up to?", completion = "<Halford looks over the Reliquary document you've obtained.>" }
WordHunterWoW_QuestEN[52030] = { title = "Keep Combing", description = "Guzbert will be busy planting explosives for a while. We should continue south, looking for more signs of the Horde.", objectives = "Search for more signs of the Horde.", completion = "Up there, by the ruins. You see them?" }
WordHunterWoW_QuestEN[52031] = { title = "Classic Reliquary", description = "Another goblin surveyor, and this one's reporting to a blood elf overseer of some sort. We're closing in on them, {name}.\n\nYou know the drill.", objectives = "Help Shandris assassinate Elisa Veilsong and Daxx Bombhand, then find out what they know.", progress = "Sunwatcher will be ours soon.", completion = "A map! Perfect. This should give us all the information we need..." }
WordHunterWoW_QuestEN[52032] = { title = "Never Stop Combing", description = "<Halford eyes the map one last time before folding it up.>\n\nOnward to the south, then.", objectives = "Continue searching for signs of the Horde.", completion = "We have an opportunity here, <name>. It would be a shame to pass it up." }
WordHunterWoW_QuestEN[52033] = { title = "WANTED: The Rime Huntress", description = "The Waycrest Guard is offering a reward for any hunter who can track down and eliminate the Rime Huntress from the vicinity of Highroad Pass.\n\nTrack her with caution. She is a ferocious beast, and has been known to ambush even seasoned hunters.", objectives = "Defeat The Rime Huntress near Highroad Pass.", completion = "So someone has finally managed to track down the Rime Huntress?  Now our traders can continue their routes to Tiragarde without fear of the beast.\n\nTake your reward, and my thanks." }
WordHunterWoW_QuestEN[52034] = { title = "A Message to the Zandalari", description = "I know we're here to hunt the Horde, but this is an opportunity.\n\nExiles or not, these are Zandalari trolls, and the Zandalari have all but put in their lot with the Horde.\n\nLet's show them what we do to friends of the Horde.", objectives = "Slay 12 Zandalari Exiles.", completion = "I hope you left a few alive.\n\nThey need to learn to fear us." }
WordHunterWoW_QuestEN[52035] = { title = "Improvised Survival", description = "The entirety of our copter's hold was reserved for bombs. There's actually still a lot of bombs left inside. Unfortunately, that meant that we weren't able to pack sufficient water and rations for our survival.\n\nDesert natives hoard supplies efficiently. I'm certain the Zandalari trolls up ahead wouldn't miss a few lost supplies.", objectives = "Gather 15 Zandalari Water Jugs and 15 Zandalari Rations.", progress = "<Halford nods sternly at you.>", completion = "Excellent reconnaissance. Well-done.\n\n<Halford begins distributing water and rations to the others in your group.>" }
WordHunterWoW_QuestEN[52036] = { title = "They Have Alpacas Here", description = "Did you see? Did you see them? The floofy alpacas?!\n\nI'VE ALWAYS WANTED A... I mean, ahh, ahem! I would like to acquire an alpaca. To study. For scientific reasons. Nothing to do with floofiness at all.\n\nHere, this should help you wrangle one back here.", objectives = "Use the Ultra-Safe Electrified Alpaca Lasso to obtain a Lost Alpaca, then bring it back to Explosioneer Zoidfuse.", progress = "So... floofy...", completion = "What a cutie. Look at her!\n\nLOOK AT HER." }
WordHunterWoW_QuestEN[52038] = { title = "Splitting Up", description = "<Halford looks over the map again.>\n\nThe final Reliquary digsite is southwest of here.\n\n{name}, you and Shandris are responsible for laying the explosives at the digsite. I'll work with Zoidfuse to establish a safe position to detonate from.", objectives = "Continue traveling southwest across the desert.", completion = "<Shandris licks her lips in anticipation.>" }
WordHunterWoW_QuestEN[52039] = { title = "Delayed Deathification", description = "While we can handle the assassination portion on our own, I suppose there's no harm in distributing these gnomish bombs around the enemy's digsite.\n\nThey're designed to be detonated remotely, so try to bury them in the sand where they won't be noticed.", objectives = "Bury 8 Remote-Detonation Deathbombs.", progress = "I hope you left them somewhere inconspicuous.", completion = "It's done? Good. Let's get a move on." }
WordHunterWoW_QuestEN[52040] = { title = "Full of Arrows", description = "There's no need for Halford's overly-complicated desert explosion operation. We can take care of Arlethal Sunwatcher right here and now.\n\nHe's right over there. We can just... kill him.\n\nYou engage him. I'll join in when he least expects it. You ready?", objectives = "Slay Arlethal Sunwatcher with Shandris.", progress = "Whenever you're ready, <name>.", completion = "Won't Halford be happy to find out that we've done his work for him?" }
WordHunterWoW_QuestEN[52041] = { title = "Report to Wyrmbane", description = "Our work here is done. Halford and Zoidfuse should be further down the coast, to the east.\n\nIf you don't mind, I'll meet you there.", objectives = "Report to Halford Wyrmbane in Vol'dun.", completion = "Arlethal is already dead?\n\nThat's good, I suppose... though it does take some of the fun out of my plan." }
WordHunterWoW_QuestEN[52042] = { title = "The Big Boom", description = "Still, we've placed all those explosives, and there's nothing stopping us from detonating them and laying waste to the Horde's excavations.\n\nSpeak with Zoidfuse when you're ready, and we'll get this explosive gnome tech going!", objectives = "Speak with Explosioneer Zoidfuse to initiate the Vol'dun Explosion Protocol.", progress = "Whenever you're ready.", completion = "Ha ha! That should set the Reliquary back a few months." }
WordHunterWoW_QuestEN[52043] = { title = "The Wrath of Grapes", description = "You look familiar. Do you owe me money? Wait... no, that's not it.\n\nIf you are here to learn, I could show you my secret mining technique, bu- Ugh...\n\nI am currently busy trying to see straight right now, amongst other things. Ugh... it feels like someone is swinging a pick at my skull. \n\nDe best cure for a hangover is pickle juice and a big greasy breakfast.\n\nTell you what, get me those things, preferably quickly and quietly, and I will teach you whatever want.", objectives = "Bring a Jar of Pickle Juice, a Mountain of Bacon, a Pile of Sausages, and a Hillock of Eggs to Biru The Drunk.", progress = "Dese shadows are loud. Can you fix dat, too?", completion = "Dis is just what I needed.\n\n<Biru spends several moments shoveling food into his mouth.>\n\nMmm... Right! If I recall correctly, you were asking about de storm silver seams?\n\nLet me tell you my secret technique, not even Secott knows. De metal is prone to stress fractures, but instead of scoring de metal where it meets de rock and breaking it off, just remove de rock.\n\nThe metal naturally forms prisms, and can be easily pulled out of the stone without wasting anything once it is loosened up." }
WordHunterWoW_QuestEN[52044] = { title = "An Exceptional Platinum Shard", description = "Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks.\n\nYou wonder to yourself if Myra could teach you to harvest this much every time.", objectives = "Bring the Exceptional Platinum Shard to Myra Cabot.\n\nProvided item:", completion = "Oh, wow! This is really impressive. You managed to get a decently sized shard of platinum in a single piece.\n\nIt looks like you managed to hit the ore in line with it's strata... Think of it like chopping wood with the grain, instead of against it.\n\nYou know, I bet if you sacrificed some of the power of your swing to keep the pick in line with the strata, you could probably get chunks this size all the time!" }
WordHunterWoW_QuestEN[52045] = { title = "Boarder Patrol", description = "", objectives = "" }
WordHunterWoW_QuestEN[52046] = { title = "An Exceptional Platinum Shard", description = "Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks.\n\nYou wonder to yourself if Secott could teach you to harvest this much every time.", objectives = "Bring the Exceptional Platinum Shard to Secott the Goldsmith.\n\nProvided item:", completion = "Hey, dis is actually pretty impressive. A decently sized shard of platinum in a single piece.\n\nI can only assume dat dis was done unintentionally?\n\nLet me save us both some time, I will tell you everything I know about platinum. If you have any further questions, take dem to someone else.\n\nDe ore forms with striations, like de grain in wood. Keep your pick aligned with de strata when you swing and it will keep de chunks intact, instead of breaking apart." }
WordHunterWoW_QuestEN[52047] = { title = "Against the Storm", description = "", objectives = "" }
WordHunterWoW_QuestEN[52049] = { title = "X Marks the Plat!", description = "You find a folded piece of aged paper next to the deposit\n\nOpening it up, you find a map of Drustvar with an X along the western coast.\n\nSeveral crude poems adorn the paper, with one in particular drawing your attention.\n\n\"Once I were a pirate,\nlivin' for rum and pleasure.\nSince the mutiny, I've retired,\nan' now I mine for treasure.\"\n\nWhoever left this appears to have spent a significant time mining in these lands. They may have some insights you could benefit from.", objectives = "Find the Tattered Map's maker in Drustvar.\n\nProvided item:", completion = "<Seeing the map, Cinderfuse puts down her weapon.>\n\nI see ye found me map. Guess that means ye be a miner, too?\n\nWell then, if yer lookin' fer booty, best bet would be ta check yer breeches. However, if ye lookin' fer work, then I got just the task fer ya." }
WordHunterWoW_QuestEN[52050] = { title = "A More Challenging Career", description = "As ye can imagine, piratin' be in me blood. Spent many of the best years of me life lootin' and plunderin'.\n\nMe favorite part was when takin' a chest filled ta the brim with gold and jewels, and buryin' it where only ye know.\n\nAlas, that life be too chaotic for me nowadays. Swashbucklin' makes me tired, and grog makes me sick. But... I can still bury me treasure.\n\nBring me some booty worth buryin', and I'll teach ya everythin' I've learned about minin' over the years.\n\nSo, wanna be me scallywag?", objectives = "Collect 20 Platinum Nuggets.", progress = "The winds be fine for adventure!", completion = "A fine haul! Pull up a crate, and grab a tankard of rum! This story be a long one!\n\n<Over many drinks, Cinderfuse regales you with many a humorous and informative tale, including several about mining platinum.>" }
WordHunterWoW_QuestEN[52051] = { title = "LFGDungeons - BFA - Raid Finder - 1st", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[52052] = { title = "LFGDungeons - BFA - Raid Finder - Nth", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[52053] = { title = "The Platinum Map", description = "Nestled within the fissures of the deposit, you find a small disc of pure platinum.\n\nDusting it off, you see etchings in its surface and recognize it as a map of Vol'dun. You also notice what appears to be a small cave in the south west that has been circled.\n\nWhoever left this apparently has a wealth of knowledge of the metal and wants to be found.", objectives = "Find the Platinum Map's maker in Vol'dun.\n\nProvided item:", completion = "It is good to meet you. My name is Ta'mil. Please, take a seat, we have much to discuss.\n\nA long time ago, I used to be a miner and a shaman.\n\nI would tell de spirits what metals I needed and why I needed it, and ask them for what dey could spare. Dey would bring what dey could to de surface for me.\n\n<The warmth from his voice leaves as his face turns somber.>\n\nNow de spirits tell me I am not long for dis world. Even in dis desert, I feel de cold creeping into my bones." }
WordHunterWoW_QuestEN[52054] = { title = "Too Much To Bear", description = "", objectives = "" }
WordHunterWoW_QuestEN[52055] = { title = "An Ore for an Eye", description = "I have one last request before I can go.\n\nI wish to see de sunset one last time. I have an enchantment in mind, and I have all the materials I need except de metal.\n\nI need you to bring me twenty platinum nuggets.\n\nI have asked de spirits to bring me de ore, but dey do not listen to me anymore. Dat is why I hid de map where only someone who could be of help would find it.\n\nIf you help me out, I will teach you what I can about mining platinum.", objectives = "Collect 20 Platinum Nuggets.", progress = "De elements beckon me. Do you have de platinum nuggets?", completion = "Excellent!\n\n<Ta'mil mutters an incantation under his breath as he cradles the platinum nuggets in his hands. A bright light bursts out from between his fingers, fading away as he finishes. Turning to you, he smiles as he holds out what looks like a pair of platinum eyeballs.>\n\nI see you. I thank you for dis. I suppose dis means de next sunset will be my last.\n\nAs for your training...\n\n<Ta'mil picks up a large chunk of rock with platinum veins, and shows you his secrets to harvesting the metal.>" }
WordHunterWoW_QuestEN[52056] = { title = "The Tendrils of Fate", description = "", objectives = "" }
WordHunterWoW_QuestEN[52057] = { title = "Against the Storm", description = "", objectives = "" }
WordHunterWoW_QuestEN[52058] = { title = "A Short-Lived Peace", description = "{name},\n\nAs the Legion's presence wanes from our world, a new threat has risen. It is with a heavy heart that I must ask you to put your life on the line for the Alliance once more. \n\nI have received a disturbing message from our operatives stationed in Orgrimmar.\n\nI await your arrival at Stormwind Keep to discuss matters further.", objectives = "Report to King Anduin Wrynn in Stormwind Keep.", completion = "You have fought bravely in the name of the Alliance time and time again. For that, I owe you a great debt of gratitude.\n\nBut even more must be asked, I fear." }
WordHunterWoW_QuestEN[52059] = { title = "Thar She Sinks", description = "", objectives = "" }
WordHunterWoW_QuestEN[52060] = { title = "The Horde Uprising", description = "Given the potential of Azerite to change the face of warfare, it comes as no surprise that the Warchief seeks to lay claim to it. Reports indicate that she is mobilizing an army to march on Silithus--the site of the great wound.\n\nHeroes of the Horde and the Alliance fought side-by-side during the Argus campaign. To think that Sylvanas is ready to cast that unity aside...\n\nSpeak with Mathias Shaw. I want you to oversee our presence in Silithus.", objectives = "Report to Master Mathias Shaw for further instruction.", completion = "Wait! Our reports were wrong!" }
WordHunterWoW_QuestEN[52061] = { title = "Taptaf the Pig!", description = "", objectives = "Taptaf looks up at you wide-eyed, after seeing his previous master slain. He seems eager to follow you now." }
WordHunterWoW_QuestEN[52062] = { title = "A Disturbance in Ashenvale", description = "The damned Horde! Clever bastards, I'll give them that. They diverted at the north fork of the Barrens and are now marching on Ashenvale.\n\nThe kaldorei forces already set sail for Silithus--must be halfway there by now. The only defenders still in the area are the Darnassian City Guard. They are en route to Astranaar, but they won't last long against an army. Their commander goes by the name of Delaryn Summermoon.\n\nFind her, {name}, and buy us time. We will get our fleet there as soon as we can.", objectives = "Report to Captain Delaryn Summermoon in Astranaar.", completion = "Are you the one Malfurion sent?" }
WordHunterWoW_QuestEN[52063] = { title = "Boarder Patrol", description = "", objectives = "" }
WordHunterWoW_QuestEN[52064] = { title = "Fiendish Fields", description = "", objectives = "" }
WordHunterWoW_QuestEN[52065] = { title = "Worse Than It Looks", description = "As bad as things are here we're managing to hold on.\n\nThings are actually a lot worse at Beacon Hill.  They're closer to the main attack, and will need all the help they can get.\n\nHead there and see if you can help.", objectives = "Speak to Felicia Gladstone at Beacon Hill", completion = "Patrick's a good person.  If he trusts you, your help is welcome." }
WordHunterWoW_QuestEN[52067] = { title = "Survivors", description = "Patrick and Daryl Eckhart have a place north of town. If I know them, they'll be taking in survivors from Brennadam.\n\nCheck in with Patrick and see if they need any help.", objectives = "Speak to Patrick Eckhart at the Eckhart Lodge.", completion = "Calvin sent you? We can use all the help you can provide!" }
WordHunterWoW_QuestEN[52068] = { title = "Helping Out, Somewhere Else", description = "You've been a big help and now we've got a lot of gold to divvy up!   \n\nYou should go west to Seabreeze Village. Treat it like a vacation, keep your mind off the gold. We'll be fine here. When you come back later, we'll have your share all ready for you.\n\nYou'd just be getting in the way here.", objectives = "Speak to Lieutenant Bauer at Seabreeze Village.", completion = "Did he owe you any money? He always sends me people he owes money to!" }
WordHunterWoW_QuestEN[52069] = { title = "More Fodder", description = "Leo Shealds at Deadwash is a crook, but he recognizes the threat the naga pose. He'll send men to help us if we ask, even if most are just fodder.\n\nTravel to Deadwash and ask for help.", objectives = "Speak to Leo Shealds at Deadwash.", completion = "The way the Irontide's hitting us, there should be plenty of volunteers to go help." }
WordHunterWoW_QuestEN[52070] = { title = "Bauer Backup", description = "We've not heard anything from the coast since the Horde attack started. I need you to check in on Lieutenant Bauer at Seabreeze Village and see that they're safe.", objectives = "Speak to Lieutenant Bauer at Seabreeze Village.", completion = "Glad to hear Felecia is safe.  We could use your help here though." }
WordHunterWoW_QuestEN[52071] = { title = "Briarback Mountain", description = "", objectives = "" }
WordHunterWoW_QuestEN[52072] = { title = "The Light of Elune", description = "My sisters lie slain on the soft earth of Ashenvale.\n\nWe are trained to expect losses. Soldiers die in battle. But this... this was a despicable attack, even for the Horde.\n\nWe have little time to grieve, but we are not savages like our enemy.\n\nPlease, {name}. Help me say a prayer to Elune in honor of the fallen. Their wisps deserve the light of her blessing.", objectives = "Honor the bodies of the fallen soldiers in Astranaar.", completion = "Elune bless you, <name>." }
WordHunterWoW_QuestEN[52073] = { title = "Petitioning Krag'wa", description = "Nothing! I cannot believe de weapon had no effect!\n\nDamn Ateena and her dark magic! We must get up there somehow, kill her for good, and remove dat barrier!\n\nBut how can we get to de top of dat building... ah, of course! Krag'wa! \n\nDe loa of frogs hates de blood trolls. I am sure he will lend us his aid. Then, finally, we will be able to put an end to Ateena's madness.", objectives = "Summon Krag'wa to ask for his help.", completion = "This is it, no more running around! \n\nNow, we will end this threat to my homeland once and for all!" }
WordHunterWoW_QuestEN[52074] = { title = "Deliverance", description = "Mainlander! Stop a moment, I could really use a hand!\n\nMy team and I were hunting in the ruins of Gol Koval when the stones began to attack us! I've never seen anything like that before. Ranger Wons sent Duke and I to get some medical supplies for our injured.\n\nDuke didn't get hit by those possessed stone monsters but he wasn't as fortunate with the spiders nearby. He'll be okay if he rests here for awhile, but my team needs these medical supplies!\n\nPlease take these to Ranger Wons!", objectives = "Bring supplies to Ranger Encampment in Gol Koval.\n\nProvided item:", completion = "Rebecca sent you? Bless that girl! You've come just in time." }
WordHunterWoW_QuestEN[52075] = { title = "Boned", description = "If the living rocks weren't bad enough, it seems the undead are hauling themselves out of the ground, too!\n\nThis used to be a Drust settlement, so those are probably Drust bones. They hated us and the feeling is definitely mutual right now.\n\nI don't know what has them stirred up, but they're a danger to us and everyone else. Take them out and I'll reward you for the work.", objectives = "Defeat 8 Vengeful Bones.", completion = "Hopefully those monsters will stay down. You have my thanks." }
WordHunterWoW_QuestEN[52113] = { title = "Vol'jin, Son of Sen'jin", description = "Even in da Echo Isles we have heard of da traditions of da Golden Road.\n\nWe must walk in da presence of royalty and hail da accomplishments of Vol'jin so dat his spirit be welcome here amongst da ancient kings.\n\nI shall carry da ashes, if you light da fires.\n\nKnow that any member of any other tribe may contest us. As our champion, we will need you to fend them off if they do.", objectives = "Escort Vol'jin's Ashes to Atal'Dazar.", completion = "Vol'jin. I must admit, I am impressed with his deeds. Had we met in dis world, I am sure he and I would have had much in common." }
WordHunterWoW_QuestEN[52114] = { title = "Honoring a True Leader", description = "Vol'jin. I have often felt our old chieftain's spirit whisperin' to me. His strength was da lifeblood of da Darkspear tribe. Some would even say he was da spirit of da true Horde.\n\nPrincess Talanji's offer is a great one. I shall travel with Vol'jin's ashes to Atal'Dazar.\n\nIf ya be wishin' to join us for dis procession, meet us upon da famed Golden Road.", objectives = "Meet Master Gadrin at the Golden Road in Zuldazar.", completion = "Da power here... it be in da very earth. Da spirits be strong and ancient in dis land." }
WordHunterWoW_QuestEN[52115] = { title = "In the Shadow of the Kraken", description = "", objectives = "" }
WordHunterWoW_QuestEN[52116] = { title = "A Soft Glow", description = "The wisps... they sing with sorrow, but also with purpose. The forest stirs, aglow with their light.\n\nThat sound... in the distance. Could it be our Shan'do?\n\nQuickly, {name}! Malfurion beckons!", objectives = "Find Malfurion in Ashenvale.", completion = "I am glad you have come, <name>." }
WordHunterWoW_QuestEN[52117] = { title = "Briarback Mountain", description = "", objectives = "" }
WordHunterWoW_QuestEN[52118] = { title = "Cutting Out the Competition", description = "I've never cared much for battle, but I'll be damned if those fiends think they're gettin' this mill.\n\nBest if we clear the area quickly. Grab an axe and show me what you got.", objectives = "Pick up a Sturdy Axe, then gather 5 Freshly-Chopped Wood from the nearby Sapling.", progress = "What're you waiting for?", completion = "You're a natural." }
WordHunterWoW_QuestEN[52119] = { title = "Goblin Azerite Extraction", description = "", objectives = "Use the Goat Shears on 1 Gentle Goats." }
WordHunterWoW_QuestEN[52120] = { title = "Gnomish Azerite Extraction", description = "", objectives = "Use the Goat Shears on 1 Gentle Goats." }
WordHunterWoW_QuestEN[52122] = { title = "To Be Forsaken", description = "Let's move. Zelling is probably with his family now.\n\nEither they're happily reunited and he helps us find Valentine... or he just helps us find Valentine.\n\nLet's go.", objectives = "Go with Lilian Voss to find Thomas Zelling.", completion = "Excellent work. I was wondering why Kyra was summoned away. Lucky for Lilian it was for a worthy cause.\n\nOur new ally is getting acclimated to his new life. We'll soon be ready to find Marshal Valentine." }
WordHunterWoW_QuestEN[52124] = { title = "Losers Weepers", description = "", objectives = "" }
WordHunterWoW_QuestEN[52126] = { title = "This Little Piggy Has Sharp Tusks", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52127] = { title = "The Wolf's Den", description = "The raid you planned on Wolf's Den in Tiragarde Sound was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Wolf's Den in Tiragarde Sound and establish fortifications there.\n\nWolf's Den will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", objectives = "Claim Wolf's Den for the Horde.", completion = "Throm-Ka, <name>. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Tiragarde Sound!" }
WordHunterWoW_QuestEN[52128] = { title = "Ferry Pass", description = "<Cyrus takes an official looking document from his jacket, signs it, then offers it to you.>\n\nHere, this will give you access to the ferry system.", objectives = "Speak with Cyrus Crestfall and receive the Ferry Pass.", completion = "There are ferry stations all along the interior coastline of the sound. Don't forget about them during your travels!" }
WordHunterWoW_QuestEN[52129] = { title = "Power Problems", description = "Rozzy, part of the extraction crew, headed out with some gear to work on a plan to keep these reconfigulators all charged up.\n\nGo see see if she could use some help!", objectives = "Check in with Rozzy.", completion = "If Merd wants you to help, I've got just the thing!" }
WordHunterWoW_QuestEN[52130] = { title = "Deadliest Cache: Carpe Diem", description = "Bah, don't listen to these landlubbers. They haven't fished an honest day in their lives!\n\nBefore they met me they were as dry as the sands o' the shoreline at low tide.\n\nI'll spin ye the tale o' the day we met. 'Twas also the day I saved the wharf from the biggest, meanest, largest monster o' the briny deep ye could imagine!", objectives = "Listen to Coxswain Hook's tale.", progress = "These landlubbers owe me their lives, if ye ask me!", completion = "Quite the story, eh lad?! Make sure ye tell yer friends!" }
WordHunterWoW_QuestEN[52131] = { title = "We Need Each Other", description = "My father believes he is indulging me. He has ruled for two hundred years, many lifetimes of trolls. In his mind, de threats dat face our kingdom are minor.\n\nI have seen too much to believe dat.\n\nSo since my father and his advisors would not help, I turned to someone who would.\n\nYour warchief needs our fleet, and I need her champions. So here is what we need to do.", objectives = "Listen to Princess Talanji.", completion = "Make your choice when you are ready." }
WordHunterWoW_QuestEN[52132] = { title = "The Proof of Piracy", description = "One thing pirates love more than gold is rum. So we're going to find their rum stashes and blow them up. With the rum all gone, a lot of the pirates should move on.\n\nUse my special barrel busting bombs to destroy the pirates' hidden rum stashes.", objectives = "Destroy 6 pirate Rum Stashes.", progress = "Let's blow up some rum!", completion = "That was hard, but it had to be done." }
WordHunterWoW_QuestEN[52133] = { title = "Good Boy!", description = "", objectives = "" }
WordHunterWoW_QuestEN[52139] = { title = "To Matters at Hand", description = "Princess Talanji should be ready to speak with you regarding how to save our empire.\n\nI would go speak with her now. She has a planning area set up nearby.", objectives = "Speak with Princess Talanji within the Great Seal.", completion = "Good, you have returned. Dere is no time to waste." }
WordHunterWoW_QuestEN[52140] = { title = "A Thorny Problem", description = "", objectives = "" }
WordHunterWoW_QuestEN[52142] = { title = "Restocking", description = "", objectives = "" }
WordHunterWoW_QuestEN[52143] = { title = "Smaller Haulers", description = "", objectives = "Free 6 Urchin Workers from the Ashvane Foundry." }
WordHunterWoW_QuestEN[52144] = { title = "Foundry Meltdown", description = "", objectives = "Slay 10 Company Watchmen, Company Enforcers, or Company Fusiliers." }
WordHunterWoW_QuestEN[52145] = { title = "Heave-Ho!", description = "", objectives = "" }
WordHunterWoW_QuestEN[52146] = { title = "Blood on the Sand", description = "And with that, our mission is done.\n\nLet's verify that Guzbert and Kelsey return safely from their demo sites, and then we can head back to friendlier shores.", objectives = "Wait for Guzbert Gizmoflank and Kelsey Steelspark to return.", progress = "Shouldn't be long now!", completion = "Guzbert's... what? No!" }
WordHunterWoW_QuestEN[52147] = { title = "Crippling the Horde", description = "Our scouts report that one of Sylvanas's dark ranger captains is in Nazmir. \n\nThe dark rangers are Sylvanas's deadliest fighters and scouts. Killing one of their leaders will cripple Horde operations.\n\nShandris Feathermoon will be leading the operation in Nazmir. Head there now and strike before we lose this chance.", objectives = "Speak with Grand Admiral Jes-Tereth to sail to Nazmir.", completion = "Nazmir. Let's be done with this place." }
WordHunterWoW_QuestEN[52148] = { title = "Freehold: A Pirate's End", description = "Hey, uh, I don't usually ask for help with personal business, but I know when I'm outmatched.\n\nSomeone's gotta take down Harlan.\n\nHe's a maniac. The things I saw him do back in the day... that's why I left Freehold in the first place.\n\nH-hey don't think of it as a favor for me--even though it would be a HUGE favor--think of it as making the seas safer for everyone, or something noble like that.\n\n<Flynn leans in and whispers.>\n\nPlus there's a big fat bounty on his head!", objectives = "Slay Harlan Sweete in the Freehold dungeon.", progress = "What's say sixty-forty split on the bounty? Eh? \n\nSeventy-thirty?\n\nHow about a finder's fee?", completion = "Gotta admit, when I first saw you in that prison cell I wasn't sure what all the fuss was about.\n\nBut you really came through for me. You came through for everyone.\n\nThanks, mate." }
WordHunterWoW_QuestEN[52149] = { title = "Everburning", description = "My people have suffered loss and pain, struggling in the darkness that covered Drustvar. But now we have some light back. We have the means and the will to reclaim our lands from the lingering evils. Your help has brought much of that about.\n\nI will miss my parents. Though their end was dark, they were family. But my duty as the head of House Waycrest is clear. The dead can handle themselves. I must attend to the living and lead.\n\nThere is a short ceremony I need to conduct. Would you assist me?", objectives = "Assist in the ceremony by the statue in Arom's Stand.", progress = "Thank you.", completion = "I must continue to set my House in order, but our relations with the rest of Kul Tiras have suffered neglect for too long. I have some additional things to handle here first, but I will go to Boralus soon to set the rest right.\n\nMy deepest thanks for all you have done, <name>." }
WordHunterWoW_QuestEN[52150] = { title = "How to Kill a Dark Ranger", description = "Let's go over the plan. We don't get many chances to kill a captain of Sylvanas's dark rangers.", objectives = "Listen to Shandris Feathermoon's plan.", progress = "Well? Let's go over the plan.", completion = "We have our plan. Let's get underway." }
WordHunterWoW_QuestEN[52151] = { title = "A Nation United", description = "You've done a fine job here, {name}.\n\nWith the city secure and Jaina in command of the fleet, the time has come for Kul Tiras to formally join the Alliance.\n\nKing Anduin has already departed for Unity Square to meet with Jaina, Katherine and the heads of the major Kul Tiran houses.\n\nThey are waiting for you.", objectives = "Attend the council meeting at Unity Square.", completion = "Hero, you have brought my family and my country back together again.\n\nMy heart is whole for the first time in many years.\n\nI cannot thank you enough." }
WordHunterWoW_QuestEN[52153] = { title = "Siege of Boralus: Lady Ashvane's Return", description = "If Ashvane thinks we will sit idly by as she attempts a coup, she is sorely mistaken.  The citizens of Boralus will fight her to a man.\n\nI'll need you on the front lines to aid them, {class}. Go with Taelia to the docks and engage the enemy. \n\nWith a little luck, we may just make it out of this alive.", objectives = "Complete the Siege of Boralus dungeon.", completion = "That was incredible! I had no idea Lady Jaina was so powerful." }
WordHunterWoW_QuestEN[52154] = { title = "Our Next Target", description = "Welcome back, {name}.\n\nWe're ready to set sail on our next mission.... Now we just need to reach an agreement on where we're headed.\n\nGeneral Feathermoon and I disagree on which Horde target we should prioritize next. But if you'll give me just a moment, I'm confident I can convince her the value of my strategy and we'll be swiftly on our way.\n\nI've considered every reasonable alternative. This is the best course of action.", objectives = "Listen to the Alliance leadership debate the plan.", completion = "I'm grateful for Alleria's wisdom and our new allies' willingness to take the lead. This new two-pronged strategy opens up additional tactical options for us to consider.\n\nI must ask Alleria to stay behind with me to coordinate our efforts on both ends. I'll need you to join Umbric on this mission and ensure its success. Good luck." }
WordHunterWoW_QuestEN[52155] = { title = "Treasure in the Tides", description = "", objectives = "Loot 8 Shipwreck Supplies in the Wailing Tideway." }
WordHunterWoW_QuestEN[52156] = { title = "Tortollans in Distress", description = "Our first task is to rescue the tortollans captured by the blood trolls. \n\nKeeshan's report indicates the tortollans are familiar with all things Nazmir. They should know about the Horde's operations here.\n\nThe tortollans tend to stay neutral in most matters. They'll give us details on the Horde's plans if we make a fair trade.\n\nWe'll meet afterwards at our other outpost, Redfield's Watch, north of Torga's Rest.", objectives = "Rescue 6 Tortollan Captives from the blood trolls.", progress = "What else do you need to know?", completion = "We've the information we need from the tortollans. We have to push on, time is of the essence." }
WordHunterWoW_QuestEN[52157] = { title = "A Chilling Encounter", description = "", objectives = "" }
WordHunterWoW_QuestEN[52158] = { title = "The Savage Hunt", description = "The blood trolls in Nazmir are monsters, pure and simple. No culture, no empathy, they only exist to destroy.\n\nLet's kill 'em and let whatever dark god they worship sort them out.", objectives = "Kill 15 blood trolls and their allies within Torga's Rest.", progress = "The only good blood troll is a dead blood troll. And even that's stretching it.", completion = "We've been fending off blood troll attacks on Fort Victory for too long. Good to know they got what's coming to them." }
WordHunterWoW_QuestEN[52159] = { title = "Swab This!", description = "", objectives = "" }
WordHunterWoW_QuestEN[52160] = { title = "Restocking", description = "", objectives = "" }
WordHunterWoW_QuestEN[52163] = { title = "The Winged Typhoon", description = "NYI - Parrot poop bombing runUpon completion of this quest you will gain:", objectives = "" }
WordHunterWoW_QuestEN[52164] = { title = "Rum- Paaaage!", description = "", objectives = "" }
WordHunterWoW_QuestEN[52165] = { title = "Automated Chaos", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52166] = { title = "The Faceless Herald", description = "", objectives = "" }
WordHunterWoW_QuestEN[52167] = { title = "Hardcore Raiders", description = "", objectives = "" }
WordHunterWoW_QuestEN[52168] = { title = "It's Lit", description = "", objectives = "" }
WordHunterWoW_QuestEN[52169] = { title = "The Matriarch", description = "", objectives = "" }
WordHunterWoW_QuestEN[52170] = { title = "Ending Areiel", description = "The tortollans have given us Captain Areiel's location, as well as new information. She carries a missive from the Horde.\n\nAny missive the Horde would send to Areiel must be extremely important. We must recover it and deliver the information to Halford.\n\nAreiel and I once fought side by side. She's incredibly powerful, Keeshan and I will be there to help you bring her down.\n\nGood luck, {name}.", objectives = "Recover the Horde Missive from Captain Areiel.", progress = "Did you retrieve the missive?", completion = "I know I shouldn't take pleasure in Areiel's death... but there is a part of me that is glad her reign of terror is over.\n\nWhat of the missive?" }
WordHunterWoW_QuestEN[52171] = { title = "One Option: Fire", description = "Here I thought things couldn't get worse, but now we have the Horde making camp around the home of some death god.\n\nI've got a good idea of what they've brought, thanks to my time in the first three wars. Medicine, armor, food...\n\nAnd probably offerings for this Bwonsamdi fella. Destroy all of these supplies to let the Horde know we won't let them stay here.", objectives = "Burn Bwonsamdi Offerings, Armory Supplies, Food Cache, and Medicinal Supplies in the Necropolis.", completion = "The Horde will be forced to retreat from the Necropolis without their supplies. A good win for us." }
WordHunterWoW_QuestEN[52172] = { title = "They Can't Stay Here", description = "Can't believe the Horde already have a foothold in the Necropolis. We have to stop them.\n\nThis one's simple. Kill as many Horde as you find in that cursed place, but keep your eye out for a fella named Bwonsamdi.\n\nSeems like he's some sort of death god. He's way beyond anything we can handle, but why not send a few of his followers his way?\n\nBetter they rot in his necropolis than bother the living.", objectives = "Kill 12 Horde soldiers within the Necropolis.", completion = "Good, less Horde for us to deal with in this cursed place." }
WordHunterWoW_QuestEN[52173] = { title = "The Void Elves Stand Ready", description = "Bal'a dash, {name}. Alleria and the others have informed me of your many accomplishments here in Kul Tiras.\n\nI'm honored to join you on this mission. As a representative for the void elves, I am eager to prove to King Anduin that his trust in us was well-placed.\n\nForgive me, do not allow me to delay you.\n\nAlleria and the others can brief me on the mission as we travel. You may tell the Grand Admiral that we are ready to set sail whenever you like.", objectives = "Speak with Grand Admiral Jes-Tereth and travel to Xibala.", completion = "My trackers have already scouted the area and prepared a full report for us. You and I may begin our phase of the mission immediately." }
WordHunterWoW_QuestEN[52174] = { title = "Snakes in the Shallows", description = "", objectives = "" }
WordHunterWoW_QuestEN[52179] = { title = "Fortified Resistance", description = "", objectives = "" }
WordHunterWoW_QuestEN[52180] = { title = "A Brennadam Shame", description = "", objectives = "" }
WordHunterWoW_QuestEN[52181] = { title = "Smoke and Shadow", description = "", objectives = "" }
WordHunterWoW_QuestEN[52182] = { title = "The Azerite Stuff", description = "", objectives = "" }
WordHunterWoW_QuestEN[52183] = { title = "When a Plan Comes Together", description = "Having Derek Proudmoore's body in our possession is a greater boon than we had planned for.\n\nValentine is risen, but I think it best to allow Derek to lay dead for a bit longer.\n\nIt's time to use our new allies to our advantage.", objectives = "Listen to Nathanos' plan, then travel to Plunder Harbor.", completion = "And now, we wait." }
WordHunterWoW_QuestEN[52184] = { title = "Relics of Ritual", description = "There is a reason why I am accompanying you on this mission, and it's more than familiarity. The Abyssal Scepter is locked behind a ritual, the components for which are held by three separate lieutenants spread across the compound.\n\nYou get the relics, I perform the ritual, we grab the Scepter and we get out.", objectives = "Collect the Compass of Clarity, the Curio of the Depths, and the Key of the Sea in Stormsong Monastery.", progress = "Have you collected the relics yet?", completion = "Please do not tell me who you had to get through to obtain these relics. I do not want to know." }
WordHunterWoW_QuestEN[52185] = { title = "A Well Placed Portal", description = "We have the front here under control. I am sending you and Zelling into Boralus to acquire the Abyssal Scepter.\n\nOculeth has managed to pinpoint a safe location for a portal. Get moving.", objectives = "Use the Portal to Boralus and meet with Thomas Zelling in Stormsong Monastery.", completion = "I once studied here. And now...\n\n<Zelling clears his throat.>\n\nWe have a job to do." }
WordHunterWoW_QuestEN[52186] = { title = "The Bulk of the Guard", description = "If all has gone according to plan, Proudmoore has sent her elite forces to recapture her son's body.\n\nLet's make sure they stay out of the way of our real mission, hmm?", objectives = "Kill 12 Proudmoore Guard on The Siren's Daughter and The Valorous Rose.\n\nHobart Grapplehammer can fly you out to the ships.", progress = "Oh, Katherine. You play right into our trap.", completion = "It's almost as if I could hear their screams from here." }
WordHunterWoW_QuestEN[52187] = { title = "Old Colleagues", description = "The people in charge of those two ships are old colleagues of mine, {name}.\n\nThey did not achieve their rank through hard work as I did, but rather through deception and blackmail.\n\nI think they deserve the hammer of karma. Or whatever weapon you prefer.", objectives = "Kill Captain Gastrod and Guard-Commander Trunksal on The Siren's Daughter, and Helmsman Miria on the Valorous Rose.\n\nHobart Grapplehammer can fly you out to the ships.", progress = "I am not a vengeful person... but appropriate punishment? Consider me a fan.", completion = "Each one of those people deserved nothing less than what you gave them." }
WordHunterWoW_QuestEN[52188] = { title = "Tidesage Teachings", description = "These people are not tidesages anymore. They do not deserve to bear our title, our prestige, or our knowledge.\n\nSo many of our teachings lay scattered around this monastery, potentially lost to those of us that remain.\n\nWe must reclaim these writings. Better in my hands than theirs.", objectives = "Collect 5 Tomes of Tidesage Research in Stormsong Monastery.", progress = "I will not stand for my people's research to be used for evil.", completion = "It's a relief to know that this research is free from those who would abuse it." }
WordHunterWoW_QuestEN[52189] = { title = "Forfeit Souls", description = "The tidesages here have given in to dark magics. They have submitted themselves to powers they do not understand, and my people have suffered for it.\n\nI knew them once, my brothers and sisters in the tides. But now they are lost.\n\nI guess I am too.\n\nRedeem the name of the tidesages! Kill these betrayers!", objectives = "Kill 8 Tidesage Archvists or Tidesage Summoners in Stormsong Monastery.", completion = "It didn't feel good to ask that of you, <name>. But it was right." }
WordHunterWoW_QuestEN[52190] = { title = "Gaining the Upper Hand", description = "We need to retrieve the Abyssal Scepter and get out of here before the Kul Tirans break our line in Plunder Harbor.\n\nI did some research while you were gone. I believe I uncovered the location where the ritual must take place.\n\nWhen you are ready to go, we can make our way over.", objectives = "Aid Zelling in retrieving the Abyssal Scepter from Stormsong Monastery.", progress = "Nathanos and I believe scepter will help us gain the upper hand on the Kul Tiran fleet. If you wish to win this war, the Abyssal Scepter is key.", completion = "We've got the scepter... for better or for worse." }
WordHunterWoW_QuestEN[52191] = { title = "Life Held Hostage", description = "As Lilian has pointed out, it seems we have a final visitor.\n\nShall we go pay him a visit?", objectives = "Help Nathanos Blightcaller with the last of Proudmoore's forces.", progress = "There is nothing left for us here. Let us return.", completion = "We have the scepter, we maintain our possession of Derek's corpse...\n\nLet us return to somewhere a little more... homey." }
WordHunterWoW_QuestEN[52192] = { title = "The Aid of the Tides", description = "With Derek's body and the Abyssal Scepter in stow, our undertaking here today is complete. Let us escape under their noses.\n\nWhen you are ready, let us return to Zuldazar. Sylvanas will want to hear of our victories.", objectives = "Talk to Nathanos Blightcaller and return to Zuldazar.", completion = "A couple more Kul Tiran ships on the bottom of the ocean wraps up our mission quite well." }
WordHunterWoW_QuestEN[52194] = { title = "What You May Regret", description = "{name}, Genn Greymane left this letter for you. He indicated it was urgent. I was just about to send for you.\n\n<Upon opening it, the letter reads as follows.>\n\"{name},\n\nYou have helped to unite the Kul Tirans and gained their support for the Alliance. Perhaps now you might be able to help reunite a mother with her daughter.\n\nMeet me at the family memorial by Proudmoore Keep. With luck we can convince Lord Admiral Proudmoore to grant her daughter a stay of execution.\n\n- Genn Greymane \"", objectives = "Meet with Genn Greymane at the memorial by Proudmoore Keep.", progress = "My daughter... My Jaina...", completion = "<Katherine looks away for a moment.>\n\nPriscilla- Lady Ashvane convinced me to exile my daughter. I now see she acted in her own self interest, and I do not know if my daughter still lives." }
WordHunterWoW_QuestEN[52196] = { title = "Sandswept Bones", description = "", objectives = "" }
WordHunterWoW_QuestEN[52197] = { title = "Long Away", description = "For every foe we slay, two more take their place.\n\nWe are too few in number to stand toe to toe. We must fall back, {name}. Strategy can yet overcome numbers. \n\nWe will regroup at Darnassus. I will send for Delaryn.", objectives = "Regroup with Malfurion and Delaryn at Darnassus.", completion = "These are troubling times, <name>. We must gather our strength." }
WordHunterWoW_QuestEN[52198] = { title = "Tank and Spank", description = "", objectives = "" }
WordHunterWoW_QuestEN[52199] = { title = "Rum- Paaaage!", description = "", objectives = "" }
WordHunterWoW_QuestEN[52200] = { title = "Turtle Tactics", description = "", objectives = "" }
WordHunterWoW_QuestEN[52203] = { title = "Find the Paper Trail", description = "The High Commander's intelligence was confident that Trade Prince Gallywix is currently in Zuldazar, but my trackers could not locate him within the Bilgewater camp. He's most likely somewhere nearby.\n\nGoblins do not work for free. Someone is bound to be bossing around the rest of those miners. Locate whoever is in charge, eliminate them, and search for anything that might tell us where Gallywix is.", objectives = "Collect Orders From Gallywix.", progress = "Did you find anything useful?", completion = "<Magister Umbric reads the orders you hand him and smiles.>\n\nGallywix is close!" }
WordHunterWoW_QuestEN[52204] = { title = "The Void Solution", description = "The Bilgewater Cartel are serious about protecting their investment at the mining site. My trackers have reported a heavy presence of large mech suits used for breaking rocks and suppressing attackers.\n\nI am certain that you could deal with the mechs yourself, but you need not waste your time doing so.\n\nTake this void shard and use it to cast the large mechs into the Void, where they won't be able to bother anyone again.", objectives = "Use Magister Umbric's Void Shard to destroy 4 Bilgewater Frackers.", completion = "The power of the Void is endless, <name>, if you can control it." }
WordHunterWoW_QuestEN[52205] = { title = "Bilgewater Bonanza Go Boom", description = "I have met very few goblins that I respect, but I must give them universal credit for one thing: they are persistent.\n\nThe Bilgewater Cartel, Trade Prince Gallywix's gang, has already sent a full set of replacement miners to extract Azerite from the beach site nearby.\n\nI am certain the Alliance will be pleased if you interrupt their mining operations again.\n\nMy regiment is available to aid you, but our combat tactics are unconventional. When you wish our help, call into the Void and we will answer.", objectives = "Kill 12 Bilgewater goblins and open Void Tears to summon void elf allies.", completion = "I do not doubt that those goblins will be replaced, like the ones you previously dealt with.\n\nBut we have at least set back their progress and given our allies here additional breathing room." }
WordHunterWoW_QuestEN[52207] = { title = "The Azerite Stuff", description = "", objectives = "" }
WordHunterWoW_QuestEN[52208] = { title = "Meeting of the Minds", description = "We're in luck. The missive details a meeting in Zo'bal Ruins between Talanji, Rokhan, Areiel, and Blood Prince Dreven.\n\nThis is our chance to gain more intel on Dreven and his next move. He killed our soldiers in Vol'dun, it's time for him to pay.\n\nMeet me outside of Zo'bal Ruins. We're going to sneak into the ruins, listen to their plans, and decide what to do next.", objectives = "Meet Shandris Feathermoon outside of Zo'bal Ruins.", progress = "Let's move.", completion = "Dreven will be inside of an enclosed tunnel? This is too perfect. Let's move." }
WordHunterWoW_QuestEN[52209] = { title = "Turtle Tactics", description = "", objectives = "" }
WordHunterWoW_QuestEN[52210] = { title = "Sending Out An SOS", description = "I noticed an exodus from the fleet, far out in the harbor.\n\nFlyers were sent out, they seek something, or someone.\n\nThose ships made a great journey, and they have much work ahead.\n\nPlease check in with Captain Grez'ko. I am sure he could use a hand!", objectives = "Speak to the Captain.", completion = "You're just de mon I was looking for! I have heard tales." }
WordHunterWoW_QuestEN[52211] = { title = "Red Sunrise", description = "", objectives = "" }
WordHunterWoW_QuestEN[52212] = { title = "Battle for Stromgarde", description = "", objectives = "" }
WordHunterWoW_QuestEN[52213] = { title = "Ancient Skinning Knife", description = "Within the scarred flesh of the beast, you find a notched golden blade embedded under its skin.\n\nCarefully extracting the blade, you can't help but feel like this is an old Zandalari skinning knife.\n\nYou should show this to Rana the Cutta.", objectives = "Return the Ancient Skinning Knife to Rana the Cutta.\n\nProvided item:", completion = "Ha ha! If I did not know better, I  would say dis was de skinning knife of my old master.\n\nHe went out to collect some pelts a couple years ago, and never came back. I figured de idiot got crushed by a log.\n\nIf dis was in it's skin, he must have thought he killed it, only to have it wake up and finish him off.\n\nI needed dat laugh. Thank you for dat. Lemme make it up to you.\n\n<Continuing to chuckle to herself, she uses her master's knife to show you a trick to harvesting leather from a kill.>" }
WordHunterWoW_QuestEN[52214] = { title = "Ceremonial Vestments", description = "Xanjo asked dat I gather de materials for him to make some ceremonial armor.\n\nHe requested several pieces of crocolisk hide, but all de hides I have are flawed or scarred.\n\nI need you to bring me a handful of fresh crocolisk hides dat are pristine.\n\nDe best source dat I know of are de primal snapjaws in Nazmir, as their hide is usually thick enough to avoid getting scarred when dey fight.\n\nIf you do dat for me, I will show you how to better harvest scales from, well... scaly creatures.", objectives = "Collect 3 Pristine Skins from Primal Snapjaws in Nazmir.", progress = "Have you got de skins?", completion = "Excellent!\n\nDese are good! Well, usable... for de most part.\n\nI will need to clean dem up before I can pass dem along. Regardless, look here and I will show you how to get more out of skinning things with scales.\n\n<Rana uses the skins you brought to exemplify small tweaks to be made to your technique to yield better results.>" }
WordHunterWoW_QuestEN[52215] = { title = "A Thicker Thread", description = "{name}! I was hoping you would show up!\n\nXanjo is nearly finished with de suit of ceremonial armor he has been working on, but dere is a problem.\n\nHe says dat de thread he used is too thin, and dat de weight of de leather is ripping out de stitching.\n\nHe asked me to get something dat will hold, and de best thing I can think of is de thick webbing of jungleweb crawlers.\n\nYou can find dem in northern Vol'dun. Bring me back some strands of their thick webbing, and my knowledge of scales is yours.", objectives = "Loot 5 Strands of Thick Webbing from Jungleweb Crawlers in Vol'Dun.", progress = "So, did you get de silk?", completion = "Yes, dis should do nicely.  Once de thread is replaced with dis webbing, dat armor is never going to fall apart!\n\nAlthough... dis is stickier dan I was expecting. I will have to ask Xanjo if dat is going to be a problem.\n\nBut first, your lesson. Learn quickly, my pupil.\n\n<Rana picks up a skin covered in scales, and shows you how to more effectively remove the skin without damaging the scales.>" }
WordHunterWoW_QuestEN[52216] = { title = "Hexoskeleton", description = "I have a bet going with Xanjo over what leather is de best for armor in regards to resisting piercing and slashing attacks.\n\nHe says scales are the best, but I have something better in mind.\n\nI feel de makrura's exoskeleton could be treated to act as a natural plate armor.\n\nBring me de carapace of a bittertide makrura, and I will teach you how to harvest bones more effectively from creatures you're skinning.", objectives = "Collect an Unbroken Makrura Carapace.", progress = "Do you have de carapace?", completion = "Nice.\n\nThese plates are very thick, and TECHNICALLY leather. My victory is almost guaranteed.\n\nAs for your lesson... makrura don't have bones.\n\n<Rana smiles.>\n\nFine, fine! I will teach you something useful, too.\n\n<Putting the carapace on the ground, Rana shows you how to feel if a bone is broken before removing it.>" }
WordHunterWoW_QuestEN[52217] = { title = "Loa Fit For A King", description = "Hey, {name}! Come here. Shh. Closer.\n\n<Rana's voice drops to a whisper.>\n\nI have something I want you to do for me. It may be just a touch sacreligous, but... well...\n\nRezan was once de loa of kings, but he has been taken to Atal'Dazar, and it grieves me what has happened to him.\n\nI want you to go dere, and bring me back a bone of his. Not even a whole bone. A splinter. I don't care how small.\n\nPlease do dis for me, and I will teach you everything I know about gathering bones while skinning.", objectives = "Collect Rezan's Bone Fragment.", progress = "Did you get it?", completion = "<Rana begins speaking in a whisper and places the bone fragment in a small pouch of a necklace she is wearing.>\n\nDis means a lot to me. \n\nWhile I will never be a king, I will have de Loa of Kings watching over me for de rest of my days.\n\n<Rana dusts off her hands as she returns to her normal volume.>\n\nIf I recall correctly, I promised to teach you everything  I know about gathering bones, yes?\n\n<Rana begins explaining which bones can be easily removed from the socket without breaking the bones.>" }
WordHunterWoW_QuestEN[52218] = { title = "Night Horrors", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52219] = { title = "Target: Blood Prince Dreven", description = "We must kill Blood Prince Dreven and his followers. I know of the place where they intend to go. Here is the plan.\n\nYou and Keeshan will make your way to the tunnels and act as bait, lure Dreven into a false sense of security.\n\nMyself and the sentinels will seal the entrance to trap him and his allies shortly thereafter.\n\nThen we kill them all. I'll send word to the others to get moving.\n\nLet's go.", objectives = "Meet Keeshan within the Collapsed Tunnels in Nazmir.", completion = "Keeshan has recovered, and I've sent scouts to retrieve the bodies of my sentinels.\n\nThey died fighting a monster. Keeshan and I will give them the highest honors.\n\nI'll send a report to Halford regarding what happened here. We must make the destruction of Draven our highest priority.\n\nThank you for all your help, <name>. We could not have done this without you." }
WordHunterWoW_QuestEN[52221] = { title = "Mission Report: Stonefist Watch", description = "Your followers have sent a report regarding the assault on Stonefist Watch.\n\nIt details that victory was hard-fought, but all of the bandits previously living in the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission to Tiragarde Sound?", completion = "It seems the mission to create an additional foothold in Tiragarde Sound was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52222] = { title = "Stonefist Watch", description = "The raid you planned for Stonefist Watch in Tiragarde Sound was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Stonefist Watch in Tiragarde Sound and establish fortifications there.\n\nStonefist Watch will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", objectives = "Claim Stonefist Watch for the Horde.", completion = "Throm-Ka, <name>. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Tiragarde Sound!" }
WordHunterWoW_QuestEN[52223] = { title = "Brinepinch", description = "You! {name}! I have a business proposition for you.\n\nThere is a monstrous crab nesting in some of my favorite hunting grounds.\n\nI've already been forced out of some areas because of the sirens, I'm not about to lose more to a CRAB!\n\nBring me the head of Brinepinch! In return I'll teach you how to get more leather when skinning.\n\n<Camilla pauses for a second before clarifying her thought.>\n\nSorry, most creatures that wrong me have heads. Just bring me some part of it as proof of its death.", objectives = "Kill Brinepinch, and bring its \"head\" to Camilla Darksky.", progress = "Have you slain the beast yet?", completion = "Excellent! I'll have to celebrate by going hunting later today.\n\nAs for you, <name>, allow me to show you a technique you've probably never seen before..." }
WordHunterWoW_QuestEN[52224] = { title = "Ivory Handled Dagger", description = "While skinning the beast, you feel a lump within the beast's stomach.\n\nInvestigating further, you find what appears to be a dagger with a beautifully etched ivory handle.\n\nCarefully extracting it, you wonder if Camilla Darksky might know something about this.", objectives = "Return the Ivory Handled Dagger to Camilla Darksky.\n\nProvided item:", completion = "I wondered what happened to him...\n\nYes, I recognize the blade. It was my mentor's.\n\nWe sailed here together, but later he went missing. He talked about building a home in Drustvar overlooking the ocean, so I figured that's what happened.\n\nBut I guess he was eaten by the creature... in which case, I'm thankful you avenged him by slaying it.\n\nAs a thank you for this closure, let me show you his secret to skinning.\n\n<Camilla takes out a fresh pelt and begins showcasing her lost mentor's technique.>" }
WordHunterWoW_QuestEN[52225] = { title = "In Pursuit of Fashion", description = "Despite me REPEATEDLY stating that I'm not a leatherworker, one of the fat nobles of this city has commissioned me to make him a belt of 'the finest saurolisk' hide.\n\nSo... I'm just going to get the materials together, give them and some of the gold to Cassandra to make the actual belt, and pocket the difference.\n\nThat said, I need you to bring me saurolisk leather, enough to circle a very wide lord.\n\nFor your efforts, I'll look at the skins and see if I can give you pointers on how to harvest more.", objectives = "Loot 3 Pristine Saurolisk Skins from Shallows Saurolisks in Drustvar.", progress = "Have ya got the hides?\n\nMy employer is becoming... incessant.", completion = "<Camilla takes a moment to look over the hides.>\n\nAcceptable work. We'll lose some material trimming, but there should be enough to encompass our esteemed and honorable benefactor.\n\nAlso, I think I see an error that, if corrected, could help when you're harvesting from anything with scales. Show me what you did.\n\n<Camilla hands you a knife and watches your movements as you explain. She occasionally stops you to adjust the position of your hands and states that it'll help next time.>" }
WordHunterWoW_QuestEN[52226] = { title = "Turtle Soup", description = "I cannot believe that I'm constantly stuck in this city!\n\nYou'd help me out, right?\n\nYou see, I've heard about these turtles that have been living in hot springs.\n\nWhat makes it interesting is that some of the sulphur from the water has soaked into their scales to give them interesting patterns.\n\nI'm too busy to go check myself, but if you could go get me some of their skins, I'd be more than willing to teach you everything else I know about skinning anything with scales in exchange.", objectives = "Loot 5 Sulphur Speckled Skins from Enriched Rockshells.", progress = "Please tell me you've got the skins.", completion = "Wow, these are... underwhelming.\n\nFrom they way they were described, I figured they would be irridescent or something.\n\nInstead, they're just yellow and smell of farts.\n\nRegardless, you've kept me from losing my sanity for one more day.\n\n<Camilla deftly draws her skinning knife and begins weaving it along and between scales.\n\nWhile her finesse may be without equal, you feel the demonstration is more than enough to ensure you can harvest more scales.>" }
WordHunterWoW_QuestEN[52227] = { title = "Bone Needle", description = "<You see Camilla sucking blood from a wound on her hand.>\n\nHey, can you do me a favor? I was sewing shut a battle wound in this skin, when my last bone needle broke, and now I need to get a new one.\n\nI've seen quilrats on the coast of Drustvar, one of their spines should do the trick.\n\nBring me one in perfect condition, and I'll teach you how to harvest more bones when skinning.\n\n<Camilla looks at her hand.>\n\nNow, if you'll excuse me, I need to go see a healer before this gets infected.", objectives = "Collect an Immaculate Quill.", progress = "I've got a lot of work backed up, waiting on a new needle.\n\nHave you got it yet?", completion = "Let's see... smooth, strong, sharp... Ow!  Very sharp!\n\nYeah, I think this'll do nicely.  Good job!\n\n<Camilla picks up a skin and starts mending another hole in the skin that looks like it's from combat. \n\nHappy with the result, she turns to you and starts explaining how to extract additional bones when skinning.>" }
WordHunterWoW_QuestEN[52228] = { title = "Atal'Dazar: An Unbreakable Bone Needle", description = "Hey, {name}, lookin' for work?\n\nI've heard through Alliance Intelligence that the trolls have a dead god or something similar. 'Rezan' I think was the name, over in Atal'Dazar.\n\nAfter the last time I broke a bone needle, I can't help but think that one made from the bone of a god has got to be indestructible, right?\n\nI want you to retrieve one of his bones. Or at least something big enough that I can carve an eye in and use.\n\nIn return, I'll show you everything that I know about harvesting bones.", objectives = "Travel to Atal'Dazar and collect Rezan's Bone Fragment.", progress = "I hope this works. Going the rest of my life without needing to replace that damn needle...\n\nHave ya got it?", completion = "Good! This is the perfect size for some of the smaller, more delicate work, the kind that would break needles constantly.\n\nAre you ready for your lesson?\n\n<Camilla spends the next several minutes showing you how to dislocate and quickly flay bones that were previously too time consuming to bother trying to collect.>" }
WordHunterWoW_QuestEN[52229] = { title = "Too Much To Bear", description = "", objectives = "" }
WordHunterWoW_QuestEN[52230] = { title = "Loose Change", description = "", objectives = "" }
WordHunterWoW_QuestEN[52234] = { title = "Hidden Amongst the Leaves", description = "When the Horde invaded, I did my best to thwart them but it is unknown how many forces have made passage already. This wall will slow them down, but it will not halt their attack entirely. \n\n<Malfurion's ears perk.>\n\nDo you hear that, hero? The Ancients call to us!\n\nWe must protect them at all costs, {name}! They see what our eyes cannot see, and hear what our ears cannot perceive.\n\nI have druids in the Twilight Vale. Find them. Send them to the Grove of the Ancients. I will reinforce the wall.", objectives = "Find 8 hidden Druids of the Claw.", completion = "Elune be praised!" }
WordHunterWoW_QuestEN[52236] = { title = "A Thorny Problem", description = "", objectives = "" }
WordHunterWoW_QuestEN[52237] = { title = "The Underrot: Restless Horror", description = "", objectives = "" }
WordHunterWoW_QuestEN[52238] = { title = "The Underrot: Mysterious Spores", description = "", objectives = "" }
WordHunterWoW_QuestEN[52239] = { title = "Loose Change", description = "", objectives = "" }
WordHunterWoW_QuestEN[52240] = { title = "Garden Grove", description = "Curse those goblins and their infernal machines!\n\nThey are using a shredder to desecrate our sacred grove. \n\nWe need that monstrosity taken down!", objectives = "Defeat the Monstrous Shredder.", completion = "Well done. These trees have so many stories to tell." }
WordHunterWoW_QuestEN[52241] = { title = "A Greedy Goblin's Paradise", description = "The Zandalari have many powerful and ancient artifacts tucked away on this island, hidden from view.\n\nBut some of their treasures are more... conspicuous.\n\nIt is no surprise that Trade Prince Gallywix was unable to resist the allure of Atal'Dazar, a massive city made entirely of gold.\n\nCome with me and we will hunt him down together.", objectives = "Use the Magister Umbric's Void Portal to join him in Atal'Dazar.", completion = "Gallywix has no respect for culture or history. Only money." }
WordHunterWoW_QuestEN[52242] = { title = "The Wake of Something New", description = "<Onu bellows in pain.>\n\nThe disturbance has become more severe. I am sensing a powerful force in our midst. It is unlike anything I have felt before. It comes from the earth itself.\n\nYou and Delaryn Summermoon must seek it out, {name}. Go to the water's edge, to the place you call Nazj'vel.", objectives = "Find the source of Onu's pain.", progress = "Keep your head down!", completion = "The Horde have taken the Master's Glaive! \n\nWe thought the glow from this place was Elune's light... but it appears to be the Azerite the Horde so desperately desire." }
WordHunterWoW_QuestEN[52243] = { title = "Fuel for the Demolishers", description = "", objectives = "" }
WordHunterWoW_QuestEN[52244] = { title = "Stop the Drilling", description = "", objectives = "" }
WordHunterWoW_QuestEN[52245] = { title = "Enraged Furbolgs", description = "The ancients of the forest are all connected to one another. We can sense a disturbance from deep within our roots. \n\nI can feel it now, {name}... the rumble of their footsteps in the distance, the thundering clamor of war. With every branch they break, they awaken the ancients.\n\nSoon my brethren will answer in kind, for nothing shall disrupt the balance of nature. \n\nA disturbance is near. Our kindred spirits cry for help. Seek it out and restore balance.", objectives = "Find those who cry for help within the Blackwood Den.", completion = "Have the furbolgs been returned to the wild?" }
WordHunterWoW_QuestEN[52246] = { title = "Lost Shipment", description = "I let grief cloud my judgment and Jaina may have already paid the ultimate price for my mistake. Yet, I hold out hope she lives.\n\nI do not know where Jaina was taken after Ashvane's people took her from the Keep. The records in their offices here in Boralus will surely tell you where they took her.\n\n{name}, you helped my people when I thought I did not need it. I ask for your help again now. Save my daughter's life!", objectives = "Search the Ashvane Offices for information on where Jaina was taken.", progress = "Did you find what happened to Jaina?", completion = "<Katherine looks up, resolved.>\n\nWe have little to go on, but I must believe she still lives." }
WordHunterWoW_QuestEN[52247] = { title = "Chasing Gallywix", description = "Look at this... The goblins are looting ancient ornamentation like they're hoarding food at a buffet. What a disgrace.\n\nBut we do not have time to get bogged down in everything happening here. Gallywix will soon know that we have arrived.\n\nWe should not hesitate in ascending these stairs and locating Gallywix. I am certain that he will be wherever the thieves are carrying their treasure.\n\nOh, and please do take care. The Zandalari do not typically leave places like this unguarded.", objectives = "Find and chase Trade Prince Gallywix.", progress = "Gallywix's greed will be his undoing.", completion = "A \"pleasure palace?\" What sort of selfish leader fritters away his people's lives and fortunes in this way?" }
WordHunterWoW_QuestEN[52248] = { title = "The Shores of Xibala", description = "", objectives = "" }
WordHunterWoW_QuestEN[52249] = { title = "The Shores of Xibala", description = "", objectives = "" }
WordHunterWoW_QuestEN[52250] = { title = "Saving Xibala", description = "", objectives = "" }
WordHunterWoW_QuestEN[52251] = { title = "Compromised Reconnaissance", description = "", objectives = "" }
WordHunterWoW_QuestEN[52252] = { title = "An Explosive Entrance", description = "A hat and some smooth talking won't get us in to Freehold this time, so I'm thinking explosives. And I'm thinking we steal them from Ashvane. Fair's fair, right? She takes something from Lady Katherine, we take some Azerite empowered grenades from Ashvane.\n\nOkay, so it's not really the same, but you get where I'm going with this.\n\nHead over to Ashvane's Foundry. Grab the biggest Azerite Grenades you can get your hands on.\n\nWhile you do that I'm going to get us some air support.", objectives = "Collect 100 Large Azerite Grenades from the Ashvane Foundry.", progress = "Nicely done! These are going to make quite an impact, if you'll forgive the pun.", completion = "You got our ammo and I got our air support.\n\n<Flynn gestures to Taelia and Galeheart with a grin.>\n\nYou see where I'm going with this." }
WordHunterWoW_QuestEN[52253] = { title = "The Keys to Success in Freehold", description = "I've been known to be a betting man, and I'd place good odds on the information we need being in Harlan Sweete's Strongbox. This would be far too valuable to put anywhere else. I bet they haven't even moved the chest. The problem is the security features.\n\nSee, the chest is locked by three keys and he gave each one to a different lieutenant. We'll need to get those.\n\nBut between your skills, my finesse and Taelia's air support this will be easy.", objectives = "Collect the keys from Irontide Lieutenants.", progress = "Nicely done! See? I knew those Irontide wouldn't be a problem for you.", completion = "Okay, we have the keys. Now we just need to make a run for the chest." }
WordHunterWoW_QuestEN[52256] = { title = "Malfurion Returns", description = "Do you hear his voice?\n\nMalfurion seeks our aid! Keep your head high, {name}. The ancients stand with you this day.", objectives = "Find Malfurion at the Wildbend River.", completion = "We must push them back!" }
WordHunterWoW_QuestEN[52257] = { title = "\"Rock\" The World", description = "We do not fight alone, {name}.\n\nThis day, the ancients will bear you in their branches. Hold back nothing in your defense of our forests!", objectives = "Join the Ancients to slay Horde enemies.", progress = "We must hold them back!", completion = "We must hold them back!" }
WordHunterWoW_QuestEN[52258] = { title = "She Sells Seashells", description = "Papa wanted to go fishing, and mum is working, so he brought me along.\n\nBut I'm bored! I'm trying to sell some of the shells I found washed up on the beach, but nobody seems to be stopping. I don't think my shells are pretty enough...\n\nYou don't seem like you're afraid of those big snakes on the beach. Can you bring me back some prettier shells? Only the shiniest please!", objectives = "Gather shells for Jenny.", progress = "Come, let us parley... How was that? I'm trying to sound like a proper shell seller.", completion = "Oooh! These are so pretty! I bet they'll sell really well." }
WordHunterWoW_QuestEN[52259] = { title = "I Take No Pleasure In This", description = "I knew that Gallywix was selfish and wasteful, but this... this is too much.\n\nHis bloated pride has blacked out the sun of good leadership. He hoards the wealth of his people to satiate his gluttony, greed, and lust while his people toil under his calloused heel.\n\nAnd, maybe worse, opportunistic socialites from all across the Horde revel in the depravity.\n\nAll people of Azeroth deserve better than this. We must teach these spoiled cowards a lesson.", objectives = "Crash Gallywix's party.", progress = "How can they live like this while their people suffer?", completion = "I won't pretend that this will solve all of the goblins' problems, but it does feel good to bring a little justice to these pompous parasites." }
WordHunterWoW_QuestEN[52260] = { title = "We Have Him Cornered", description = "Did you hear Gallywix barking orders to his servants and thugs? Still concerned with frivolities as we edge ever closer.\n\nHe feels safe in his petulant palace of profits. He should not.\n\nEven here, we will strike down Trade Prince Gallywix. For the Alliance!", objectives = "Kill Trade Prince Gallywix.", progress = "Gallywix will not be missed.", completion = "The Gallywix that we fought was a decoy? A body double?\n\nInfuriating. We were so close... I'm sorry, <name>." }
WordHunterWoW_QuestEN[52261] = { title = "Gallywix Got Away", description = "I must confess my disappointment that we were not able to bring an end to Gallywix's greedy reign today.\n\nBut I blame no one but myself, and will report the same to the High Commander. Your performance was exemplary, just as I expected.\n\nI hope the Alliance will not lose faith in the void elves because of this. We have much to offer.\n\nWhen you're ready, I will open a final Void portal to take us back to Boralus.", objectives = "Return to High Commander Halford Wyrmbane on the Wind's Redemption in Boralus.", completion = "Thank you, <name>. Not every failed mission is a failure.\n\nWe've put Gallywix on the run and uncovered his decoy operations. And I, personally, also learned a thing or two from the surprising tactics of Umbric's void elf regiment.\n\nI have no doubt that the denizens of the Void will prove valuable to the Alliance in the trying days ahead." }
WordHunterWoW_QuestEN[52271] = { title = "Sea Salt Flavored", description = "", objectives = "" }
WordHunterWoW_QuestEN[52275] = { title = "Mission Report: Swiftwind Post", description = "Your followers have sent a report regarding the assault on Swiftwind Post.\n\nIt details that victory was hard-fought, but all of the wicker beasts previously infesting the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission to Drustvar?", completion = "It seems the mission to create an additional foothold in Drustvar was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52276] = { title = "Swiftwind Post", description = "The raid you planned for Swiftwind Post in Drustvar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Swiftwind Post in Drustvar and establish fortifications there.\n\nSwiftwind Post will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", objectives = "Claim Swiftwind Post for the Horde.", completion = "Welcome, <name>. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Drustvar!" }
WordHunterWoW_QuestEN[52278] = { title = "Rogue Azerite", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52279] = { title = "A Looming Threat", description = "If we hope to push the Horde out of our lands, we must call upon all the strength our people have to offer.\n\nGo, seek out the druids, the priestesses, our sentinels! Make the call to arms, and watch as the kaldorei rise to action. Only together can we hope to end the stalemate at the Wildbend River.\n\nWhen you are finished, report to Malfurion Stormrage. He awaits our fleet in Rut'theran Village.", objectives = "Rally the kaldorei forces in Darnassus.", completion = "No matter the odds, we must stay strong." }
WordHunterWoW_QuestEN[52280] = { title = "Sea Salt Flavored", description = "", objectives = "" }
WordHunterWoW_QuestEN[52281] = { title = "Under the Cover of Swiftwing", description = "Aye! So we be the first in this crazy operation. We'll be hitchin' a ride on Swiftwing to tha Isle of Fangs.\n\nThe Zandalari got one of their main ships there, called the Breath of Pa'ku, whatever that is.\n\nHop on ta Swiftwing when yer ready te go. It's gonna get real cozy on there with all of ye comin' aboard.", objectives = "Ride Swiftwing to the Isle of Fangs.", progress = "Hop on!", completion = "All we need to do is plant some bombs and cause some chaos without the mainland Zandalari knowing. \n\nEasy, right?" }
WordHunterWoW_QuestEN[52282] = { title = "How to Sink a Zandalari Battleship", description = "Let's go over our plan of attack, but remember above all things, the Zandalari cannot know our full forces are here.\n\nIf they were to discover an Alliance base within the shadow of their empire... we would be wiped out in an instant.", objectives = "Go over the plan to weaken the Zandalari naval fleet with Halford.", progress = "Let's go over the plan.", completion = "You know the plan, <name>. Stay hidden and weaken the Zandalari fleet. If we accomplish those two goals, we'll walk out of here alive." }
WordHunterWoW_QuestEN[52283] = { title = "Sabotaging the Pa'ku", description = "Our first job is to plant some bombs along these ships. I'll take care of the smaller ships, you deal with the Breath of Pa'ku.\n\nWhatever that means.\n\nKelsey says these bombs are the latest in gnome technology. We plant 'em and she can detonate them at any time.\n\nLet's get moving, and remember, this whole plan works as long as they don't see us plantin' these bombs.", objectives = "Plant 4 Remote-Detonation Deathbombs beneath the Breath of Pa'ku.", completion = "All the bombs are planted on my end. Still wish we could blow 'em up now. \n\nGuess we'll have to just wait until the time is right to blow these things sky high." }
WordHunterWoW_QuestEN[52284] = { title = "Ship Logs", description = "We've got mogu and Zandalari working together on the Breath of Pa'ku. They've got records on the Zandalari fleet's ships.\n\nWe've been making educated guesses regarding the Zandalari fleet. It's time to upgrade our intel.\n\nGo in there and get the naval records from anyone on board that ship.\n\nOh, and take these jet boots. You'll need them to reach the boat if you're planting bombs on the hull.", objectives = "Recover 6 Naval Records from Zandalari and Mogu.", progress = "Did you get those naval records? We'll need them to better plan against the Zandalari.", completion = "Perfect! I'll get these documents back to Halford. We'll be able to coordinate future attacks with this." }
WordHunterWoW_QuestEN[52285] = { title = "The Enlarged Miniaturized Submarine", description = "Our next target is a ship docked in a place across from here, the Warport Rastari.\n\nLucky for you, I can get us all there in my enlarged miniaturized submarine.\n\nShandris Feathermoon and Magister Umbric should be waiting for you on the coast of Warport Rastari.\n\nLet's get going!", objectives = "Ride Kelsey's Enlarged Miniaturized Submarine to Warport Rastari.", completion = "Glad you could make it, <name>. We've got a lot to do within Warport Rastari." }
WordHunterWoW_QuestEN[52286] = { title = "Right Beneath Their Nose", description = "We must continue with our primary goal, plant bombs on major Zandalari ships. There is one docked within the Warport.\n\nYou know what to do. Get beneath the boat, plant the bombs, and ensure no one sees... a blood troll using bombs.\n\nMy invisibility flask will give you the stealth you need, and Umbric believes the ritual will give you some other power to tap into.", objectives = "Plant 3 Remote-Detonation Deathbombs within the main warship in Warport Rastari.", progress = "Good luck, <name>, and stay safe.", completion = "Good work. The Zandalari will be in for a rude awakening when we blow up their flagships moments before our first naval incursion." }
WordHunterWoW_QuestEN[52287] = { title = "Intelligence Denial", description = "There are three Horde spymasters stationed within Warport Rastari. They are giving the Zandalari information on the Alliance fleet.\n\nWe need these targets killed. We cannot allow the Zandalari to get any advantageous information on our fleet.\n\nLuckily for us, your blood troll disguise means any witnesses will believe this to be a bold attack by the blood trolls.", objectives = "Kill Spymaster Stormhorn, Spymaster Bloodsnarl, and Spymaster Bilespreader.", completion = "You've prevented the zandalari from getting crucial information regarding our naval forces. Well done." }
WordHunterWoW_QuestEN[52288] = { title = "Void Vacation", description = "The Horde have sent emissaries to help with their potential alliance with the Zandalari. \n\nThese emissaries are also sharing secrets that the Horde have regarding the Alliance. We need to put a stop to this.\n\nTake this orb. It will create a void portal above the target and pull them... somewhere else.", objectives = "Use the Portal Orb on 6 Horde Emissaries.", completion = "Good work, this should cripple both the Horde and the Zandalari in their fight against the Alliance." }
WordHunterWoW_QuestEN[52289] = { title = "Victory is Assured", description = "Our task is finished. You've planted the bombs on two of the Zandalari's major flagships, and Keeshan has helped with the remainder.\n\nLet's return to Halford, the sooner we're done here, the better. It's far too risky for us to be at the Zandalari's doorstep.", objectives = "Meet Halford Wyrmbane at Xibala in Zuldazar.", completion = "<name>, good timing. We have to move.\n\nWe've been discovered." }
WordHunterWoW_QuestEN[52290] = { title = "My Enemy's Enemy is My Disguise", description = "We need you to kill several targets within Warport Rastari, but we also cannot reveal that the Alliance is here.\n\nUmbric has uncovered a ritual from Nazmir that will grant you a blood troll disguise. It is grim, but it must be done.\n\nYou will go through with the ritual, then use my invisibility flask to sneak into the Warport. \n\nIf discovered, the Zandalari and Horde will think it's a bold attack from the blood trolls... and not from the Alliance.", objectives = "Speak with Magister Umbric to be disguised as a blood troll.", progress = "I know this is unpleasant, but it must be done.", completion = "I have to admit, this disguise is uncanny. Let's hope the zandalari believe they are dealing with a bold blood troll and not the Alliance." }
WordHunterWoW_QuestEN[52291] = { title = "Victory Was Assured", description = "Kelsey brought back the records you retrieved on the Isle of Fangs, but it was too late.\n\nWhat you see before you is Gral's Call, the missing Zandalari flagship, and they've spotted us.\n\nIf they make it back to port, we will have the full fury of the Zandalari empire brought down upon us.\n\nWe must board the ship and eliminate every Zandalari on board.\n\nFalstad will get us there. Let's move.", objectives = "Fly to Gral's Call on Swiftwing.", completion = "We're here, and the fighting has begun. Let's hurry." }
WordHunterWoW_QuestEN[52293] = { title = "Lizards and Ledgers", description = "", objectives = "" }
WordHunterWoW_QuestEN[52294] = { title = "Fallen Idols", description = "Little creature, please... listen to me. \n\nI am Krag'wa. \n\nOnce, my worshipers were many and my powers great. Now, my followers are all but gone. What little power I have left was placed within several idols, but the idols have been stolen by the heretical blood trolls.\n\nI ask you, please recover my idols so that I can become whole once more!", objectives = "Collect Stolen Idols of Krag'wa from the blood troll camp in the Frogmarsh." }
WordHunterWoW_QuestEN[52295] = { title = "The MOTHERLODE!!: Elementals on the Payroll", description = "", objectives = "" }
WordHunterWoW_QuestEN[52297] = { title = "What's the Buzz?", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52298] = { title = "The MOTHERLODE!!: The Smarts Are In His Horn!", description = "", objectives = "" }
WordHunterWoW_QuestEN[52299] = { title = "Whiplash", description = "", objectives = "" }
WordHunterWoW_QuestEN[52300] = { title = "Wagga Snarltusk", description = "", objectives = "" }
WordHunterWoW_QuestEN[52301] = { title = "Vinespeaker Ratha", description = "", objectives = "" }
WordHunterWoW_QuestEN[52302] = { title = "The MOTHERLODE!!: He's Got Really Big Bombs", description = "", objectives = "" }
WordHunterWoW_QuestEN[52305] = { title = "Nature Versus Nurture", description = "Greetings, {name}. I am Wingminder Goja.\n\nI overheard the ordeal that Pa'ku has laid at your feet. I can help you.\n\nI oversee this roost at my loa's pleasure. I have seen many eggs become glorious beasts of war. It will be a long road ahead, with many trials to overcome, but de companionship of a pterrordax be a worthy reward.\n\nFor now, de little one is young. Simply tend to his needs while he stays in de nest. When he is ready to take on de world he will let you know.\n\nGood luck, {name}.", objectives = "Tend to Kua'fon until he is ready to fly.", completion = "<Kua'fon opens his wings and screeches gleefully at you!>\n\nSkree!!" }
WordHunterWoW_QuestEN[52306] = { title = "Croaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[52307] = { title = "Spiritual Aid", description = "", objectives = "" }
WordHunterWoW_QuestEN[52308] = { title = "Intercepted Orders", description = "Good to see you again, {name}.\n\nMathias and I are discussing what to do with new intel that his SI:7 agents procured for us.\n\nThe intercepted letter contains orders from Warchief Sylvanas for an operation the Horde is undertaking at sea.\n\nThis could be a rare opportunity, or a distraction. The letter is purposefully light on details, and it's unclear if we should make this a top priority or focus on our other missions.\n\nDo you have a moment to talk through this with Mathias and me?", objectives = "Discuss the plan with Alliance leadership.", progress = "We cannot afford a distraction... or a missed opportunity.", completion = "It's decided, then. The assassination of Blood Prince Dreven at sea will be unexpected, demoralizing, and beneficial to the long-term success of our larger campaign.\n\n<Halford Wyrmbane smiles.>\n\nEverything I'm looking for in a strategy." }
WordHunterWoW_QuestEN[52309] = { title = "SandFang", description = "", objectives = "" }
WordHunterWoW_QuestEN[52310] = { title = "Corrupted Tideskipper", description = "", objectives = "" }
WordHunterWoW_QuestEN[52311] = { title = "Sweete's Strongbox", description = "You've got the keys, and Taelia's still watching our backs. So let's head up to Sweete's, ah, \"office\" and liberate the documents in that strongbox.\n\nCome on, it's across the bridge with the rest of his treasure.", objectives = "Open Harlan Sweete's Strongbox.", completion = "I'm certain the information we need is in this chest. But given the added security, my backup plan of having Taelia bust this thing open isn't going to work. Who knows what other security is set up on this chest?\n\nWe need to get that final key." }
WordHunterWoW_QuestEN[52312] = { title = "Extinguish the Lights", description = "", objectives = "" }
WordHunterWoW_QuestEN[52313] = { title = "Mission Report: Mudfisher Cove", description = "Your followers have sent a report regarding the assault on Mudfisher Cove.\n\nIt details that victory was hard-fought, but all of the guards previously defending the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission to Drustvar?", completion = "It seems the mission to create an additional foothold in Drustvar was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52314] = { title = "Mudfisher Cove", description = "The raid you planned for Mudfisher Cove in Drustvar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Mudfisher Cove in Drustvar and establish fortifications there.\n\nThe cove will be an essential outpost in our campaign against the Alliance.\n\nMove quickly!", objectives = "Claim Mudfisher Coast for the Horde.", completion = "Throm-Ka, <name>. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Drustvar!" }
WordHunterWoW_QuestEN[52315] = { title = "Severus the Outcast", description = "", objectives = "" }
WordHunterWoW_QuestEN[52316] = { title = "Sea Creatures Are Weird", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52317] = { title = "No Ptake, Only Throw", description = "<Kua'fon places a troll skull into your palm. It is covered in teeth marks and rather slimy.>\n\nSkree!\n\n<Kua'fon peers at you expectantly.>", objectives = "Throw Kua'fon's favorite skull.", completion = "<Kua'fon's eyes shine brightly. He tucks his troll skull safely under a wing and gargles appreciatively at you.>\n\nSkree." }
WordHunterWoW_QuestEN[52319] = { title = "Mission Report: Windfall Cavern", description = "Your followers have sent a report regarding the assault on Windfall Cavern.\n\nIt details that victory was hard-fought, but Gravemaul has been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission to Stormsong Valley?", completion = "It seems the mission to create an additional foothold in Stormsong Valley was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52320] = { title = "Windfall Cavern", description = "The raid you planned for Windfall Cavern in Stormsong Valley was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Windfall Cavern in Stormsong Valley and establish fortifications there.\n\nWindfall Cavern will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", objectives = "Claim Windfall Cavern for the Horde.", completion = "Well met, <name>. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Stormsong Valley!" }
