WordHunterWoW_QuestEN[52422] = { title = "Work Order: Battle Flag: Spirit of Freedom", description = "", objectives = "Are you here to deliver supplies?", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, tailor. We needed these battle flags badly." }
