WordHunterWoW_QuestEN[52427] = { title = "Work Order: Battle Flag: Rallying Swiftness", description = "", objectives = "Are you here to deliver supplies?", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, tailor. We needed these battle flags badly." }
WordHunterWoW_QuestEN[52428] = { title = "Infusing the Heart", description = "Azeroth's voice is growin' fainter and fainter. If the seal on this chamber shatters, her soul will be lost!\n\nWe've got one chance tae save us all.\n\nAbsorb the Azerite around the chamber into the Heart of Azeroth. Then unleash the amulet's power tae seal that crack in the center of the seal.\n\nAzerite can be a destructive force, but if it's channeled through yer amulet, it can heal the world!", objectives = "Absorb Azerite to empower the Heart of Azeroth.", progress = "What are ye waitin' fer?", completion = "That was too close, <name>! Now ye've seen the true power of the Heart of Azeroth. \n\nBut we've got a long way tae go before the world is healed." }
WordHunterWoW_QuestEN[52430] = { title = "Not So Bad Down Here", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52431] = { title = "No-Landing Zone", description = "These pirates are ruthless - they're bringing in landing boats to cut off our escape!\n\nThe guards are down at the riverside holding them off, but I'm afraid they'll be overrun before my family and I can get away!", objectives = "Slay Burnsy the Blade, Wiley Jaki, and Skullcrusher Cotner.", progress = "Please help the guards fend off those pirates!", completion = "Oh thank you, thank you so much!" }
WordHunterWoW_QuestEN[52432] = { title = "Squall", description = "", objectives = "" }
WordHunterWoW_QuestEN[52436] = { title = "The Blackwood Den", description = "We have not moved all of our troops into Darkshore yet, but I think we have enough to justify establishing a foothold somewhere. I know just the place.\n\nJust south of here is the Blackwood Den. Its inhabitants, the Furbolgs, have been driven in to a hysteria. With our enemies pouring from the North, the Furbolg threat is a nuisance we cannot afford. \n\nI will lead another squad past the wall while you... negotiate with the Furbolgs.", objectives = "Drive the furbolgs out of the Blackwood Den.", completion = "Just you wait, <name> -- once we have conquered Darnassus the Elders of the Blackwood tribe will be thanking us for restoring peace to the den.\n\nWe just need to borrow it for a moment." }
WordHunterWoW_QuestEN[52437] = { title = "The Start of Something Good", description = "While the rest of our army sets up camp -- you should follow me. I spotted something... interesting... on my way back from Zoram'gar.\n\nI'll admit, not even I could have predicted such fortuitous happenstance.\n\nCome with me, {name}. And bring a pickaxe.", objectives = "Follow Sylvanas to Nazj'vel.", completion = "You heard the warchief, we got work to do!" }
WordHunterWoW_QuestEN[52438] = { title = "A Wild Ride", description = "Let me tell ya, kid... this may be some of the best work I've ever done!\n\nNow that the upgrades are in place, there's no time to waste.\n\nThe battle is raging over at Wildbend River. Take the modified hellion into battle and give 'em hell!", objectives = "Join the battle at Wildbend River.", completion = "For every enemy we slay, two replace them on the battlefield..." }
WordHunterWoW_QuestEN[52439] = { title = "Iron Stores", description = "While the mine is under Alliance banners our workers ensure the iron supply never runs dry.\n\nThis key will provide access to the stores. Take what you need.", objectives = "Use the Heavy Iron Key to access the Iron Stores.", progress = "These old chests can be quite the bother.", completion = "Well now, that was easy." }
WordHunterWoW_QuestEN[52440] = { title = "Resource Recruitment", description = "If we're to maintain our iron supply we'll need a bit of help.\n\nSee if you can wrangle us up a few fresh recruits for the mine.", objectives = "Recruit 3 Highlands Peasants to work.", completion = "Well done. Those recruits will surely help maintain our iron supply." }
WordHunterWoW_QuestEN[52443] = { title = "The Final Foothold", description = "We have established two critical footholds in Zandalar. The time has come to establish the third.\n\nLet's review the battle plan when you're ready.", objectives = "Use the Zandalar Campaign Map to review the final foothold.", completion = "Ready to go? Let's get a move on, then." }
WordHunterWoW_QuestEN[52444] = { title = "The Final Foothold", description = "We have established two critical footholds in Kul Tiras. The time has come to establish the third.\n\nLet's review the battle plan when you're ready.", objectives = "Use the Kul Tiras Campaign Map to review the final foothold.", completion = "I trust you are sufficiently prepared, then." }
WordHunterWoW_QuestEN[52445] = { title = "Tol Dagor: The Fourth Key", description = "Hey, wait a second. I know the type of key our fourth lock needs. This is the same sort of lock the Ashvane company uses. Resists lockpicks like nothing else, but they have a standard skeleton key. There was a set hanging on the wall in the Tol Dagor Armory. Given the state we left it in, it'd be easy to grab it.\n\nTaelia and I will take the chest back to the Harbormaster's office for safe keeping. \n\nYou go in to Tol Dagor and get that last key!", objectives = "Enter the Tol Dagor dungeon, recover the Ashvane Skeleton Key and kill Overseer Korgus, then return to Flynn Fairwind in the Harbormaster's Office in Boralus.", progress = "I knew securing that last key wouldn't be a problem for you, <name>!", completion = "Well, you have your answer. Jaina was sent to Fate's End." }
WordHunterWoW_QuestEN[52446] = { title = "Sister Absinthe", description = "", objectives = "" }
WordHunterWoW_QuestEN[52447] = { title = "Room To Grow", description = "Ah, I would not worry too much about de little one.\n\nSome beasts take longer than others to find their way, and Kua'fon is no exception.\n\nFor now, continue to help him grow. Keep him fed, keep him out of danger, and strengthen your bond. He will let you know when he is ready to try again.", objectives = "Tend to Kua'fon until he is ready to attempt another flight.", completion = "<Kua'fon wriggles anxiously, leveling one golden eye upon you.>\n\nSkree?" }
WordHunterWoW_QuestEN[52449] = { title = "The Mysterious Island", description = "Fate's End is just that. It's where the very worst criminals are sent. No one ever comes back.\n\nI'm sorry Lady Katherine will have to hear this, but I'm glad it isn't my job to tell her.\n\n<Flynn hands you the document solemnly.>\n\nI'm certain she'll want an update, even if the news is as bad as this.", objectives = "Report to Katherine Proudmoore in Boralus.", completion = "Fate's End! Merciful Tides, I'd hoped she wouldn't have been sent there... But of course she would be.\n\nNo matter. I must forge ahead." }
WordHunterWoW_QuestEN[52450] = { title = "Uniting Kul Tiras", description = "", objectives = "The people of Kul Tiras are diverse and capable. With their forces loyal to the Alliance, the Horde has no chance of stopping us.\n\nNow, the real work begins." }
WordHunterWoW_QuestEN[52451] = { title = "Uniting Zandalar", description = "", objectives = "The people of Zandalar are diverse and capable. With their forces loyal to the Horde, the Alliance has no chance of stopping us.\n\nNow, the real work begins." }
WordHunterWoW_QuestEN[52452] = { title = "Song Mistress Dadalea", description = "", objectives = "" }
WordHunterWoW_QuestEN[52453] = { title = "A Forlorn Hope", description = "<Lady Katherine's jaw sets.>\n\nI refuse to believe I am too late.\n\nNo one has ever come back from Fate's End, but if anyone could survive I have to believe it would be my Jaina.\n\nGo to Stormsong Valley and secure transit to Fate's End from the tidesages. Brother Pike is a good place to start.\n\nHurry, {name}.", objectives = "Go to Stormsong and speak with Brother Pike at Kraken's Reach.", completion = "Jaina Proudmoore was sent to Fate's End and her mother wishes to save her?\n\nThen we must act at once if we are to have any hope of saving her life!" }
WordHunterWoW_QuestEN[52454] = { title = "Freehold: Dread Captain Vandegrim", description = "", objectives = "" }
WordHunterWoW_QuestEN[52455] = { title = "Unbreakable", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52456] = { title = "Freehold: Veteran Man O' War", description = "", objectives = "" }
WordHunterWoW_QuestEN[52458] = { title = "Freehold: Pieces of Eight", description = "", objectives = "" }
WordHunterWoW_QuestEN[52459] = { title = "Whirlwing", description = "", objectives = "" }
WordHunterWoW_QuestEN[52462] = { title = "A Load of Scrap", description = "Hello, friend. Would you like the scoop on the latest invention of the century?\n\nIt's called the Scrap-O-Matic 1000 and this device can triple, no QUADRUPLE your production capacity as a crafter of armor, weapons or other gizmos you adventurers wander around with.\n\nHere, take these pants and use the Scrap-O-Matic on 'em. You'll get the hang of it.", objectives = "Use the Scrap-O-Matic 1000 on the pair of Tattered Pants.", progress = "This machine is gonna change everything!", completion = "And just like that, you're back in business. All the materials you put into making the item come back to you with the Scrap-O-Matic 1000.\n\nWell, maybe not ALL the materials, but hey, something's better than nothing, right?\n\nOh, and keep an eye out for explusom. It's what we've discovered as a magical byproduct of the scrapping process.\n\nIt's quite potent and only shows up when we scrap really fancy stuff." }
WordHunterWoW_QuestEN[52463] = { title = "Haegol the Hammer", description = "", objectives = "" }
WordHunterWoW_QuestEN[52464] = { title = "Osca the Bloodied", description = "", objectives = "" }
WordHunterWoW_QuestEN[52467] = { title = "Battlefield Scavenging", description = "Our efforts to reclaim the keep have left our supplies a bit lighter than we anticipated. If our forces are to continue, we'll need to restock.\n\nCheck the enemy camps for anything of value. We'll make use of what you find.", objectives = "Gather supplies from Newstead, High Perch and the Circle of Elements.", progress = "Find anything of interest?", completion = "Pilfering is a dangerous business, though I must admit I am quite impressed.\n\nWe'll be sure to put these supplies to good use." }
WordHunterWoW_QuestEN[52468] = { title = "Raiding Their Stores", description = "Our rations are low. We need to keep our forces fed if we're to continue our efforts.\n\nBefore it was overrun, Newstead had plenty of food in their stores. I only hope there's something left.", objectives = "Obtain a Roast Boar, a Colossal Cheese Wheel, a Basket of Eggs, and a Keg of Applebrew." }
WordHunterWoW_QuestEN[52471] = { title = "That's a Big Carcass", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52472] = { title = "Make Loh Go", description = "Hello, {name}! We tortollans grow up hearing the stories of Loh, a tortollan who had many adventures. These stories help to challenge a young tortollan's mind as they try to figure out how Loh would make his way through any given adventure.\n\nCare to give it a try?", objectives = "Learn how to guide Loh.", completion = "Well done, <name>!" }
WordHunterWoW_QuestEN[52473] = { title = "Bringing Down the Fleet", description = "This is it, {name}. We've weakened the Horde enough to make a daring strike on Zuldazar itself.\n\nOur forces in Zuldazar still remain hidden, thanks to the help of the Dark Iron dwarves. That gives us our chance to strike.\n\nSet sail to Zuldazar. We will be gathering our forces there for a coordinated strike to weaken their harbor defenses.", objectives = "Speak with Grand Admiral Jes-Tereth to sail to Zuldazar.", completion = "We're all gathered. Let's begin, we cannot afford to lose any more time." }
WordHunterWoW_QuestEN[52474] = { title = "Poacher Zane", description = "", objectives = "" }
WordHunterWoW_QuestEN[52475] = { title = "Where Eagles Prey", description = "", objectives = "" }
WordHunterWoW_QuestEN[52476] = { title = "The Lichen King", description = "", objectives = "" }
WordHunterWoW_QuestEN[52477] = { title = "WANTED: Ayame", description = "Wanted: For the death of twelve pilgrims and their escort to Torga's Rest. A reward is offered to anyone who brings in the head of the great serpent, Ayame. \n\n-Korkush", objectives = "Hunt down Ayame and obtain its head.", progress = "Yeah, I put up the poster. Got anything for me?", completion = "It's good to see that snake got what it deserved!\n\nHere's your reward, you earned it." }
WordHunterWoW_QuestEN[52478] = { title = "Mission Report: Hillcrest Pasture", description = "Your followers have sent a report regarding the assault on Hillcrest Pasture.\n\nIt details that victory was hard-fought, but the Stormsong defenders have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission to Stormsong Valley?", completion = "It seems the mission to create an additional foothold in Stormsong Valley was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52479] = { title = "Hillcrest Pasture", description = "The raid you planned for Hillcrest Pasture in Stormsong Valley was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Hillcrest Pasture in Stormsong Valley and establish fortifications there.\n\nHillcrest Pasture will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", objectives = "Claim Hillcrest Pasture for the Horde.", completion = "Well met, <name>. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Stormsong Valley!" }
WordHunterWoW_QuestEN[52480] = { title = "WANTED: Ayame", description = "Well equipped exterminator wanted.\n\nHuge snake seen lurking north of Fort Victory. \n\nReward offered for anyone who brings in the head of the pest.\n\n-Garrick Blacksteel", objectives = "Hunt down Ayame and obtain its head.", progress = "Got anything fer me?", completion = "Ah! Good! I've nae been able ta sleep a wink since I first saw this thing!\n\nHere's ye reward, ye earned it!" }
WordHunterWoW_QuestEN[52481] = { title = "Of Myth and Fable", description = "If Jaina is truly trapped in the Blighted Lands, that could mean we're not too late! We just need to find a way inside...\n\nWe will need to enlist the help of Lucille Waycrest. The legends of that place are deeply rooted in Drustvar's culture. If anyone would know more about it, it would be she.\n\nI will send a raven ahead for her to prepare what knowledge she can gather. Make haste to Arom's Stand!", objectives = "Meet with Lucille Waycrest at Arom's Stand in Drustvar.", completion = "I can't believe you're thinking of intentionally seeking out the Blighted Lands. The legends say it's a terrible place that exists for torment and pain.\n\nI'm not sure any prize is worth treading those grounds." }
WordHunterWoW_QuestEN[52482] = { title = "The Old Bear", description = "I cannot change your mind, can I? Very well, I may know where you can find your answers. \n\nHigh in the mountains, there is a hidden alcove of impossibly verdant growth. It is there that the druids of Kul Tiras train in the old ways of the Drust - from before the time of Gorak Tul.\n\nTheir leader is a great bear named Ulfar. I know little about him, but few are more qualified to parse the magic of the Drust.\n\nYou will find a path to his den along Highroad Pass. Good luck, Inquisitor.", objectives = "Speak with Ulfar in Ulfar's Den.", progress = "Yes?", completion = "Forgive my hesitation, mainlander. It would appear the minions of Thros are no longer confined to their own realm.\n\nI will help you cross the threshold into the Blighted Lands." }
WordHunterWoW_QuestEN[52483] = { title = "Nightmare Catcher", description = "The effigies crafted by the followers of Gorak Tul were made not of wood, but of the bones and sinew of their enemies. This will be your first task.\n\nTravel to Gol Osigr where the ancient Drust have awoken from their slumber. The bones here belong to Gorak Tul's greatest soldiers who stood with him at the final battle against the first Lord Waycrest.\n\nTheir bones seethe with hatred and anger. This will serve your needs well.", objectives = "Collect 4 Intact Drust Bones and 9 Ancient Sinew from Drust skeletons in Gol Osigr.", progress = "Do you have the materials?", completion = "I can practically feel the hatred emanating off these bones. They will do nicely." }
WordHunterWoW_QuestEN[52484] = { title = "Buried Power", description = "Since time immemorial, the Drust have used runes to shape their magics. This remains true of the spells woven by Gorak Tul and his ilk. You will need some of these runes for your effigy to be effective.\n\nIt is likely that some still exist at the site of his final battle, buried under years of soot and snow. \n\nTake this stone. It is empowered with the magic of the Thornspeakers and will react to Tul's spells. With it, you should be able to locate the runes, no matter how deep the ages have buried them.", objectives = "Use the Dowsing Stone to find and Collect 6 Drust Runestones in Gol Osigr.", progress = "What have you uncovered beneath the snows of Gol Osigr?", completion = "These runestones still throb with the twisted energy of Gorak Tul's magic. They will serve you well." }
WordHunterWoW_QuestEN[52485] = { title = "Hatred's Focus", description = "An effigy requires a central focus. The coven are fond of using animal skulls for this purpose, but for your task you will need something much more potent.\n\nKorvash was a trusted lieutenant to Gorak Tul, as well as a powerful sorcerer, until he was defeated at the battle of Arom's Stand. His bones remain at the site of his demise, now buried by the years.\n\nFind them, and take his skull.", objectives = "Collect Korvash's Skull from Korvash in Gol Osigr.", progress = "Have you found Korvash's bones?", completion = "Korvash's skull will make a powerful focus indeed, but the years have drained it of its natural potency.\n\nYou will need to take further steps to prepare it for your ritual." }
WordHunterWoW_QuestEN[52486] = { title = "Waycrest Manor: Draining the Heartsbane", description = "The skull you have taken from Korvash needs to be steeped in Gorak Tul's magic to grant the power needed to bridge the gap to Thros. You must take it to a font of his power, and let it absorb his magic.\n\nYou will find one such font in Waycrest Manor - the epicenter of the coven's power. Here, their leader has tapped so freely into Tul's power that it emanates from the very walls.\n\nBring Korvash's skull to the heart of the manor and let it feast. Then, the effigy will be complete.", objectives = "Empower Korvash's Skull in the depths of Waycrest Manor.", completion = "So, this thing is the key to opening the gateway?\n\nYou truly mean to go through with this, then?" }
WordHunterWoW_QuestEN[52487] = { title = "Into Darkness", description = "I didn't think you would find a way. Though at this point, I guess I shouldn't be surprised when you accomplish what seems impossible.\n\nI guess all that is left is to brave the Crimson Forest and see if this thing works.\n\nFirst, however, Katherine has ordered me to send word when you have found a way to Jaina. You can use one of our falcons to take a message to her.", objectives = "Speak with Ensign Josey to send a message to Katherine, then meet her at Gol Inath in the Crimson Forest.", progress = "We've made it this far. There's no turning back.", completion = "It looks like the effigy's magic is working, but I think there's something we're missing here." }
WordHunterWoW_QuestEN[52488] = { title = "Runic Resistance", description = "Whatever is going on with this effigy, I don't think it's going to open the gateway without our help.\n\nThese runes must be the key. There must be some way we can use them to activate the effigy.", objectives = "Solve the runic puzzle to activate the Drust Effigy in Gol Inath.", progress = "There must be some trick to these runes...", completion = "Remarkable! Yesterday, I believed this place to only exist in tales and legends, and now I stand a footstep away from it...\n\nI just hope that at least some of those tales were exaggerations..." }
WordHunterWoW_QuestEN[52489] = { title = "Hunting Blood Prince Dreven", description = "Between the information I gathered from my scouting mission and Mathias Shaw's intel, we know exactly where Blood Prince Dreven is going to be.\n\nWe will have our revenge, {name}. For ourselves, for my sisters, for the Alliance.\n\nWe won't underestimate the san'layn this time. We will keep the Horde off-balance and distracted with swift, targeted, ruthless attacks.\n\nThankfully, the Wildhammer are masters of those combat tactics. I'm glad they'll be joining us.\n\nAre you ready to leave?", objectives = "Ride Swiftwing to accompany Falstad and Shandris to the Great Sea.", progress = "Our strikes will be swift and true. The san'layn will fall.", completion = "The foul weather offers us some cover. Every thick cloud and raindrop is an ally.\n\n<Shandris Feathermoon smirks.>\n\nIn that sense, we actually outnumber the Horde. They don't stand a chance." }
WordHunterWoW_QuestEN[52490] = { title = "Behind Enemy Boats", description = "This is where our information ends, {name}.\n\nBlood Prince Dreven is lurking in one of those Forsaken boats, but we don't know which boat or which section of that boat he's in.\n\nWe'll split up and hit the boats simultaneously, so the Horde has less time to react.\n\nIf Dreven isn't on the boat you scout, abandon it and join me on the other one. If he's not on my boat, I'll do the same. \n\nWe'll take down Dreven together.\n\nDon't get distracted. Our resources are limited. Dreven is our only target today.", objectives = "Search the Banshee's Wail for signs of Blood Prince Dreven.", completion = "Ha! Nathanos is gonna be cryin' all the way back tae Sylvanas's nursery after that whoppin'!\n\nDid ye find Blood Prince Dreven?" }
WordHunterWoW_QuestEN[52491] = { title = "Broadside Bedlam", description = "<The ship's cannons are currently pointed at the other Forsaken ship across the water.\n\nHowever, it appears the crew hasn't loaded them with gunpowder or cannonballs yet... Probably to avoid any accidental firings while they're anchored here.\n\nYes, it'd be a real shame if \"accidental\" cannon fire damaged the other ship.>", objectives = "Collect gunpowder, cannonballs, and a torch, then fire the cannons.", progress = "Ye find anything interesting down in the ship?", completion = "I wish ye could've seen the crew panicking when ye shot off those cannons. It was hilarious!\n\nThat's the Wildhammer style!" }
WordHunterWoW_QuestEN[52492] = { title = "The Wildhammer Specialty", description = "Well, if ye didn't find Blood Prince Dreven on yer ship, he must be hiding on the other one.\n\nI can take ye down to it, but the Horde knows we're here now. What do ye say we create some distractions to hold their attention while we hunt down Dreven?\n\nMe Wildhammers are itchin' tae let the hammers fly. Ye want to join us for the first round?", objectives = "Join Falstad and Swiftwing on a bombing run over the Horde ships.", completion = "He's here." }
WordHunterWoW_QuestEN[52493] = { title = "An Unnatural Crew", description = "Blood Prince Dreven is here, and the situation's even worse than we thought.\n\nThat monster's training other san'layn. Every neophyte you see on this ship is another future Blood Prince Dreven.\n\nHis vile practices cannot be allowed to spread within the Horde. We're going to tear the san'layn out, right now, root and all.", objectives = "Kill 12 Horde crew aboard the Crimson Squall.", progress = "Every san'layn must be felled today, or we'll never be rid of them.", completion = "That is enough for now. We must focus our efforts on Blood Prince Dreven." }
WordHunterWoW_QuestEN[52494] = { title = "Foul Crystals for Foul People", description = "Blood Prince Dreven and his followers are siphoning power from blood-infused crystals to bolster their unholy abilities.\n\nDestroying those crystals will weaken Dreven before we fight him. Take out as many as you can find.", objectives = "Destroy 5 San'layn Crystals.", completion = "Good. That should weaken Blood Prince Dreven long enough for us to kill him." }
WordHunterWoW_QuestEN[52495] = { title = "Ending the San'layn Threat", description = "Blood Prince Dreven has barricaded himself in the lowest deck of this ship. He's trapped down there.\n\nDon't think that makes this easy for us. A cornered beast is more dangerous than a free one. But, if we have the will and wisdom, he can be slain.\n\nFollow me. I will break the barrier blocking his lair and we will face him together.", objectives = "Kill Blood Prince Dreven.", completion = "<Shandris raises her eyes to the sky and speaks somberly.>\n\nAnde'thoras-ethil, sisters. Shaha lor'ma." }
WordHunterWoW_QuestEN[52496] = { title = "A Clean Escape", description = "Our victory here will echo through the Horde like a warning shot.\n\nGrunts will whisper around the campfire that nowhere is safe from {name} and the Alliance.\n\nSoldiers will doubt, even for a moment, the strength of their commanders.\n\nSylvanas herself will hear the story of what we did here today, and it will infuriate her. The thought of her outraged roar when she hears the news will keep me warm tonight.\n\nLet's return to Boralus and inform the High Commander of the good news.", objectives = "Return to Boralus and report to High Commander Halford Wyrmbane.", completion = "You've done the Alliance, and all of Azeroth, a fine service today, <name>.\n\nWe will sleep in a better world than we woke to. That is all that can be asked of us.\n\nFor the Alliance!" }
WordHunterWoW_QuestEN[52497] = { title = "Raiding the Boulderfist", description = "The Boulderfist have been rather active ever since the battle began. One of our scouts reported their recent raid on Galson's Lode proved rather lucrative.\n\nScout the cave to the northeast, find the iron ore they stole and steal it back.\n\nWe can't afford to let anyone else control our resources.", objectives = "Obtain 200 pieces of Unprocessed Iron Ore." }
WordHunterWoW_QuestEN[52504] = { title = "So We Meat Again", description = "", objectives = "" }
WordHunterWoW_QuestEN[52505] = { title = "Pruning the Thorns", description = "", objectives = "" }
WordHunterWoW_QuestEN[52506] = { title = "Blunt the Spikes", description = "", objectives = "" }
WordHunterWoW_QuestEN[52507] = { title = "Sticky Mess", description = "", objectives = "" }
WordHunterWoW_QuestEN[52508] = { title = "Ritual Effects", description = "I will need some assistance in conducting the ritual to allow us to gain passage to Fate's End. To help me with that, you will require the proper items and attire.\n\nNormally I have free access to these things, but the recent upheaval has blocked myself and many of my brothers and sisters from obtaining them easily. However, the fallen tidesages across the span have all you will need.\n\nCollect a ritual knife, lantern and robes from the fallen and these so-called prophets.", objectives = "Collected a Ritual Knife, Ritual Lantern and Ritual Robes from the Fallen Hullwardens and Abyssal Prophets in Tempest's Edge.", progress = "It warms my heart to see these used for good once more.", completion = "Wonderful. These are more than just a costume, they're an essential part of our traditions. For the ritual to work, you'll need to step into the role as fully as you can." }
WordHunterWoW_QuestEN[52509] = { title = "The Strength of the Storm", description = "The ritual I must conduct is written on a scroll. To gain access to it, you'll have to break through the dark energies the fallen tidesages have placed around it, with the power of the storm.\n\nThis relic can be used to pull purified power from the enslaved elementals. Not only will you be gaining the means to our end, you will ultimately be freeing these spirits from corruption.\n\nDefeat the enslaved elementals and then call their power into the relic.", objectives = "Collected motes of Stormsurge from defeated elementals.", completion = "Well done, <name>. The staff is now imbued with the strength of those elementals. You will need it for what lies ahead." }
WordHunterWoW_QuestEN[52510] = { title = "Shrine of the Storm: The Missing Ritual", description = "The ritual which allows safe passage to Fate's End is a closely guarded secret to keep the curious from venturing there and suffering the same fate as the condemned. I have never conducted it before, but there is a scroll with instructions.\n\nIt is held in the Shrine of the Storms. To access the scroll, use the staff you have empowered to break the dark energy surrounding it.\n\nCollect the Ritual of Safe Passage and bring it to me.", objectives = "Go into the Shrine of the Storms, recover the Ritual of Safe Passage and defeat Vol'zith the Whisperer.", progress = "Were you able to recover the Ritual of Safe Passage?", completion = "Good! Time is of the essence if we are to save Lady Jaina. I have made what preparations I can. Allow me a moment to read through the ritual and then we may begin." }
WordHunterWoW_QuestEN[52511] = { title = "Opening the Way", description = "Hmm. This ritual is a bit... tricky. No matter, together we will be able to complete it.\n\nI shall begin to channel. You will need to activate the runes in the proper order. I shall leave the scroll here so you may consult it.", objectives = "Complete the ritual.", progress = "There we are. The clouds clear and the sea calms. Our way is open.", completion = "From here we shall be able to reach Fate's End. Hopefully in time." }
WordHunterWoW_QuestEN[52512] = { title = "Fate's End", description = "Fate's End is a place in turmoil. The seas froth, the air cracks with thunder. We tried to settle there once, but each settlement disappeared into the mists, every soul never to be seen again. The island did not want inhabitants.\n\nNow we send our most vile exiles there. They never return and no one knows why.\n\nShould we find and recover Jaina, she will be the first. I hope we are not too late.", objectives = "Travel to Fate's End and search for signs of Jaina.", progress = "By the Tides, I thought we were done for.", completion = "You appeared to leave the island for a brief moment, then reappeared with that creature. Perhaps where it came from is where Jaina has gone.\n\nLady Katherine should be told of this development." }
WordHunterWoW_QuestEN[52513] = { title = "Lost in Darkness", description = "If people are being pulled somewhere else, it would explain why no one has ever returned. I also choose to believe it means Lady Jaina might be able to be saved as well.\n\nGo back to Lady Katherine with all speed! She will want to know of this development.", objectives = "Return to Katherine Proudmoore in Boralus.", completion = "The Blighted Lands? Why... I thought that was only a legend used to frighten children.\n\nMy daughter... What have I done to you?" }
WordHunterWoW_QuestEN[52544] = { title = "The War Cache", description = "{name}. Let's talk.\n\nThis war won't be won simply by adding the Kul Tirans to our ranks. We eventually need to crush the Horde.\n\nYou and I will be leading an expedition to... disrupt the Horde operations in Zandalar. But first, we need resources.", objectives = "Gather 100 War Resources. War Resources can be obtained from many sources, including quests and treasure chests.", progress = "Ready to sail when you are, <name>.", completion = "<Halford looks over the gathered resources.>\n\nThis should do it." }
